class OnchainEntityChainGapTests(unittest.TestCase):
    def setUp(self) -> None:
        self.tmp = tempfile.TemporaryDirectory()
        self.original_label_db = label_ledger.DB_PATH
        self.original_label_backup_dir = label_ledger.BACKUP_DIR
        self.original_engine_db = onchain_engine.DB_PATH
        self.original_engine_backup_dir = onchain_engine.BACKUP_DIR
        self.original_engine_label_db = onchain_engine.LABEL_LEDGER_PATH
        self.original_engine_entity_db = onchain_engine.ENTITY_LABELS_PATH
        self.original_engine_arkham_cache = onchain_engine.ARKHAM_CACHE_PATH

        base = Path(self.tmp.name)
        self.label_db = base / "label_ledger.db"
        self.onchain_db = base / "onchain.db"
        self.arkham_cache = base / "arkham_cache.json"
        label_ledger.DB_PATH = self.label_db
        label_ledger.BACKUP_DIR = base / "backups"
        onchain_engine.DB_PATH = self.onchain_db
        onchain_engine.BACKUP_DIR = base / "onchain_backups"
        onchain_engine.LABEL_LEDGER_PATH = self.label_db
        onchain_engine.ENTITY_LABELS_PATH = base / "missing_entity_labels.db"
        onchain_engine.ARKHAM_CACHE_PATH = self.arkham_cache
        onchain_engine._VENUE_MAPPING_CACHE.clear()

        label_ledger._init_db()
        onchain_engine._init_db()
        self._seed_labels()
        self._seed_rpc_state()

    def tearDown(self) -> None:
        label_ledger.DB_PATH = self.original_label_db
        label_ledger.BACKUP_DIR = self.original_label_backup_dir
        onchain_engine.DB_PATH = self.original_engine_db
        onchain_engine.BACKUP_DIR = self.original_engine_backup_dir
        onchain_engine.LABEL_LEDGER_PATH = self.original_engine_label_db
        onchain_engine.ENTITY_LABELS_PATH = self.original_engine_entity_db
        onchain_engine.ARKHAM_CACHE_PATH = self.original_engine_arkham_cache
        onchain_engine._VENUE_MAPPING_CACHE.clear()
        self.tmp.cleanup()

    def test_source_backed_shadow_backtest_plan_is_read_only_and_disabled(self) -> None:
        fake_scoring = {
            "ok": True,
            "dry_run": True,
            "design_status": "ready_but_disabled",
            "chain": "bsc",
            "pool_address": "0xpool",
            "token_address": "0xtoken",
            "token_symbol": "UFLOKI",
            "source_evidence": {"route_proof": {"paircreated_evidence_id": 1}},
            "source_backed_foundation_gates": {
                "route_pool_source_backed": True,
                "exact_swap_rows_min_10": True,
                "transfer_rows_min_10_after_bridge": True,
            },
            "scoring_design": {
                "score_name": "ufloki_source_backed_research_score_v0",
                "features_from_existing_engine": {
                    "exact_swap_rows": 216,
                    "raw_distinct_tx_hashes": 156,
                    "raw_distinct_blocks": 156,
                    "best_transfer_rows_after_evidence_bridge": 176,
                    "best_transfer_wallets_after_evidence_bridge": 98,
                    "block_windows": 2,
                    "patterns": ["raw_swap_repeatability", "multi_wallet_transfer_context"],
                },
            },
            "summary": {
                "candidate_found": True,
                "source_backed_foundation_ready": True,
            },
            "blockers": ["shadow_backtest_not_ready"],
        }
        with patch(
            "services.onchain.manipulation_reliability.get_manipulation_detection_source_backed_scoring_design",
            return_value=fake_scoring,
        ):
            report = onchain_engine.get_manipulation_detection_source_backed_shadow_backtest_plan(
                chain="bsc",
                dry_run=True,
            )

        self.assertEqual(report["plan_status"], "ready_but_disabled")
        self.assertTrue(report["summary"]["shadow_backtest_plan_ready"])
        self.assertFalse(report["summary"]["shadow_backtest_executable_now"])
        self.assertFalse(report["would_run_backtest"])
        self.assertFalse(report["would_create_client_signal"])
        self.assertFalse(report["would_execute_trade"])
        self.assertFalse(report["would_write"])
        self.assertEqual(report["writes_performed"], 0)
        self.assertIn("outcome_window_dataset_missing", report["blockers"])

    def test_source_backed_shadow_backtest_outcome_schema_plan_creates_no_table(self) -> None:
        fake_shadow_plan = {
            "ok": True,
            "dry_run": True,
            "plan_status": "ready_but_disabled",
            "chain": "bsc",
            "pool_address": "0xpool",
            "token_address": "0xtoken",
            "token_symbol": "UFLOKI",
            "plan_digest": "a" * 64,
            "summary": {
                "candidate_found": True,
                "source_backed_foundation_ready": True,
                "shadow_backtest_plan_ready": True,
                "shadow_backtest_executable_now": False,
            },
            "dataset_preview": {"exact_swap_rows": 216},
            "next_data_requirements": [{"requirement": "outcome_window_dataset"}],
            "blockers": ["outcome_window_dataset_missing"],
        }
        with patch(
            "services.onchain.manipulation_reliability.get_manipulation_detection_source_backed_shadow_backtest_plan",
            return_value=fake_shadow_plan,
        ):
            report = onchain_engine.get_manipulation_detection_source_backed_shadow_backtest_outcome_dataset_schema_plan(
                chain="bsc",
                dry_run=True,
            )

        self.assertEqual(report["plan_status"], "ready")
        self.assertEqual(report["target_table"], "manipulation_shadow_backtest_outcome_windows")
        self.assertFalse(report["table_exists"])
        self.assertTrue(report["migration_required"])
        self.assertFalse(report["would_create_table"])
        self.assertFalse(report["would_insert_outcome_row"])
        self.assertFalse(report["would_create_client_signal"])
        self.assertFalse(report["would_execute_trade"])
        self.assertFalse(report["would_write"])
        self.assertEqual(report["writes_performed"], 0)
        self.assertIn("schema_preview", report)
        self.assertIn("outcome_dedupe_key_formula", report["dedupe_constraints"])
        conn = sqlite3.connect(str(self.onchain_db))
        try:
            exists = onchain_engine._table_exists(conn, "manipulation_shadow_backtest_outcome_windows")
        finally:
            conn.close()
        self.assertFalse(exists)

    def test_source_backed_outcome_window_collection_uses_local_raw_swaps_read_only(self) -> None:
        pool = "0xc722000a77d0ba1b464f38ef5aa3be638f97db61"
        quote = "0x55d398326f99059ff775485246999027b3197955"
        token = "0x86a2a205807b6250ec7e07419710abf89d06b58b"
        conn = sqlite3.connect(str(self.onchain_db))
        try:
            conn.execute(
                """
                CREATE TABLE dex_paircreated_evidence (
                    id INTEGER PRIMARY KEY AUTOINCREMENT,
                    chain TEXT NOT NULL,
                    source_type TEXT NOT NULL,
                    source_label TEXT NOT NULL,
                    source_url TEXT NOT NULL,
                    source_tier TEXT NOT NULL,
                    official_venue TEXT,
                    factory_address TEXT NOT NULL,
                    pair_address TEXT NOT NULL,
                    token0 TEXT NOT NULL,
                    token0_symbol TEXT,
                    token1 TEXT NOT NULL,
                    token1_symbol TEXT,
                    tx_hash TEXT NOT NULL,
                    log_index INTEGER NOT NULL,
                    block_number INTEGER NOT NULL,
                    block_hash TEXT,
                    event_timestamp INTEGER,
                    paircreated_event_topic TEXT NOT NULL,
                    paircreated_dedupe_key TEXT NOT NULL UNIQUE,
                    evidence_payload_digest TEXT NOT NULL,
                    raw_payload_json TEXT NOT NULL,
                    status TEXT NOT NULL DEFAULT 'pending_admin_review',
                    created_at TEXT NOT NULL,
                    source_policy TEXT NOT NULL
                )
                """
            )
            conn.execute(
                """
                CREATE TABLE dex_raw_swap_events (
                    id INTEGER PRIMARY KEY AUTOINCREMENT,
                    checkpoint_id INTEGER,
                    chain TEXT NOT NULL,
                    pair_address TEXT NOT NULL,
                    sender TEXT,
                    recipient TEXT,
                    amount0_in TEXT NOT NULL,
                    amount1_in TEXT NOT NULL,
                    amount0_out TEXT NOT NULL,
                    amount1_out TEXT NOT NULL,
                    tx_hash TEXT NOT NULL,
                    log_index INTEGER NOT NULL,
                    block_number INTEGER NOT NULL,
                    block_hash TEXT,
                    block_timestamp INTEGER,
                    event_topic TEXT NOT NULL,
                    raw_log_json TEXT NOT NULL,
                    payload_digest TEXT NOT NULL,
                    event_dedupe_key TEXT NOT NULL UNIQUE,
                    status TEXT NOT NULL DEFAULT 'raw_observed',
                    created_at TEXT NOT NULL,
                    source_policy TEXT NOT NULL
                )
                """
            )
            conn.execute(
                """
                INSERT INTO dex_paircreated_evidence (
                    chain, source_type, source_label, source_url, source_tier,
                    official_venue, factory_address, pair_address, token0,
                    token0_symbol, token1, token1_symbol, tx_hash, log_index,
                    block_number, block_hash, event_timestamp, paircreated_event_topic,
                    paircreated_dedupe_key, evidence_payload_digest, raw_payload_json,
                    status, created_at, source_policy
                ) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)
                """,
                (
                    "bsc",
                    "sqd_portal_stream_api",
                    "sqd_portal",
                    "https://portal.sqd.dev/datasets/binance-mainnet/stream",
                    "tier_2_indexer_corroboration",
                    "PancakeSwap V2",
                    "0xca143ce32fe78f1f7019d7d551a6402fc5350c73",
                    pool,
                    quote,
                    "USDT",
                    token,
                    "UFLOKI",
                    "0xpaircreated",
                    1,
                    900,
                    "0xblock",
                    1000,
                    "0x0d3648bd0f6ba80134a33ba9275ac585d9d315f0ad8355cddefde31afa28d0e9",
                    "dedupe",
                    "digest",
                    "{}",
                    "accepted_for_future_mapping_review",
                    "2026-05-22T00:00:00Z",
                    "test",
                ),
            )
            base_ts = 1_000
            timestamps = [base_ts + i for i in range(10)] + [base_ts + 1_800, base_ts + 21_600, base_ts + 86_409]
            prices = [100] * 10 + [140, 180, 220]
            for idx, (ts, price) in enumerate(zip(timestamps, prices), start=1):
                conn.execute(
                    """
                    INSERT INTO dex_raw_swap_events (
                        chain, pair_address, sender, recipient,
                        amount0_in, amount1_in, amount0_out, amount1_out,
                        tx_hash, log_index, block_number, block_hash,
                        block_timestamp, event_topic, raw_log_json,
                        payload_digest, event_dedupe_key, status, created_at, source_policy
                    ) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)
                    """,
                    (
                        "bsc",
                        pool,
                        "0xsender",
                        "0xrecipient",
                        str(price * 10**18),
                        "0",
                        "0",
                        str(10**18),
                        f"0xtx{idx}",
                        idx,
                        10_000 + idx,
                        "0xblock",
                        ts,
                        "0xd78ad95fa46c994b6551d0da85fc275fe613ce37657fb8d5e3d130840159d822",
                        "{}",
                        f"digest-{idx}",
                        f"bsc|Swap|{pool}|0xtx{idx}|{idx}",
                        "raw_observed",
                        "2026-05-22T00:00:00Z",
                        "test",
                    ),
                )
            conn.commit()
        finally:
            conn.close()

        fake_shadow_plan = {
            "ok": True,
            "dry_run": True,
            "plan_status": "ready_but_disabled",
            "chain": "bsc",
            "pool_address": pool,
            "token_address": token,
            "token_symbol": "UFLOKI",
            "plan_digest": "b" * 64,
            "summary": {
                "candidate_found": True,
                "source_backed_foundation_ready": True,
                "shadow_backtest_plan_ready": True,
                "shadow_backtest_executable_now": False,
            },
            "blockers": [],
        }
        with patch(
            "services.onchain.manipulation_reliability.get_manipulation_detection_source_backed_shadow_backtest_plan",
            return_value=fake_shadow_plan,
        ):
            report = onchain_engine.get_manipulation_detection_source_backed_outcome_window_data_collection_dry_run(
                chain="bsc",
                dry_run=True,
            )

        self.assertEqual(report["collection_status"], "ready_with_local_outcomes")
        self.assertTrue(report["backtest_readiness"]["local_outcome_backtestable_now"])
        self.assertTrue(report["backtest_readiness"]["high_quality_outcome_backtestable_now"])
        self.assertEqual(report["local_data_quality"]["price_proxy_points"], 13)
        self.assertFalse(report["would_create_client_signal"])
        self.assertFalse(report["would_execute_trade"])
        self.assertFalse(report["would_write"])
        self.assertEqual(report["writes_performed"], 0)

    def test_outcome_quality_repair_uses_local_sync_liquidity_read_only(self) -> None:
        pool = "0xc722000a77d0ba1b464f38ef5aa3be638f97db61"
        token = "0x86a2a205807b6250ec7e07419710abf89d06b58b"
        conn = sqlite3.connect(str(self.onchain_db))
        try:
            conn.execute(
                """
                CREATE TABLE dex_raw_sync_events (
                    id INTEGER PRIMARY KEY AUTOINCREMENT,
                    checkpoint_id INTEGER,
                    chain TEXT NOT NULL,
                    pair_address TEXT NOT NULL,
                    reserve0 TEXT NOT NULL,
                    reserve1 TEXT NOT NULL,
                    tx_hash TEXT NOT NULL,
                    log_index INTEGER NOT NULL,
                    block_number INTEGER NOT NULL,
                    raw_log_json TEXT NOT NULL,
                    payload_digest TEXT NOT NULL,
                    event_dedupe_key TEXT NOT NULL UNIQUE,
                    status TEXT NOT NULL DEFAULT 'raw_observed',
                    created_at TEXT NOT NULL,
                    source_policy TEXT NOT NULL
                )
                """
            )
            conn.execute(
                """
                CREATE TABLE dex_raw_liquidity_events (
                    id INTEGER PRIMARY KEY AUTOINCREMENT,
                    checkpoint_id INTEGER,
                    chain TEXT NOT NULL,
                    pair_address TEXT NOT NULL,
                    event_name TEXT NOT NULL,
                    sender TEXT,
                    recipient TEXT,
                    amount0 TEXT NOT NULL,
                    amount1 TEXT NOT NULL,
                    tx_hash TEXT NOT NULL,
                    log_index INTEGER NOT NULL,
                    block_number INTEGER NOT NULL,
                    raw_log_json TEXT NOT NULL,
                    payload_digest TEXT NOT NULL,
                    event_dedupe_key TEXT NOT NULL UNIQUE,
                    status TEXT NOT NULL DEFAULT 'raw_observed',
                    created_at TEXT NOT NULL,
                    source_policy TEXT NOT NULL
                )
                """
            )
            for idx, block in enumerate([100, 200], start=1):
                conn.execute(
                    """
                    INSERT INTO dex_raw_sync_events (
                        chain, pair_address, reserve0, reserve1, tx_hash, log_index,
                        block_number, raw_log_json, payload_digest, event_dedupe_key,
                        status, created_at, source_policy
                    ) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)
                    """,
                    (
                        "bsc",
                        pool,
                        "100000000000000000000",
                        "200000000000000000000",
                        f"0xsync{idx}",
                        idx,
                        block,
                        "{}",
                        f"sync-digest-{idx}",
                        f"bsc|Sync|{pool}|0xsync{idx}|{idx}",
                        "raw_observed",
                        "2026-05-22T00:00:00Z",
                        "test",
                    ),
                )
            conn.execute(
                """
                INSERT INTO dex_raw_liquidity_events (
                    chain, pair_address, event_name, sender, recipient, amount0, amount1,
                    tx_hash, log_index, block_number, raw_log_json, payload_digest,
                    event_dedupe_key, status, created_at, source_policy
                ) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)
                """,
                (
                    "bsc",
                    pool,
                    "Mint",
                    "0xsender",
                    "0xrecipient",
                    "1",
                    "2",
                    "0xliq",
                    1,
                    150,
                    "{}",
                    "liq-digest",
                    f"bsc|Mint|{pool}|0xliq|1",
                    "raw_observed",
                    "2026-05-22T00:00:00Z",
                    "test",
                ),
            )
            conn.commit()
        finally:
            conn.close()

        fake_outcome = {
            "ok": True,
            "dry_run": True,
            "collection_status": "partial_with_local_outcomes",
            "chain": "bsc",
            "pool_address": pool,
            "token_address": token,
            "token_symbol": "UFLOKI",
            "quote_token": "0x55d398326f99059ff775485246999027b3197955",
            "snapshot": {"block_number": 100, "block_timestamp": 1_000},
            "outcome_windows": [
                {
                    "window_label": "plus_24h",
                    "status": "usable_local_proxy",
                    "complete": True,
                    "first_block": 100,
                    "last_block": 200,
                    "blockers": ["stale_end_price_proxy_no_recent_swap_near_window_end"],
                }
            ],
            "backtest_readiness": {"local_outcome_backtestable_now": True},
            "blockers": ["some_outcome_windows_have_stale_end_price_proxy"],
        }
        with patch(
            "services.onchain.manipulation_reliability.get_manipulation_detection_source_backed_outcome_window_data_collection_dry_run",
            return_value=fake_outcome,
        ):
            report = onchain_engine.get_manipulation_detection_source_backed_outcome_quality_repair_sync_liquidity_context_dry_run(
                chain="bsc",
                dry_run=True,
            )

        self.assertEqual(report["repair_status"], "repair_context_ready_read_only")
        self.assertTrue(report["quality_readiness"]["can_repair_stale_windows_now"])
        self.assertEqual(report["local_context"]["sync_rows_for_pool"], 2)
        self.assertEqual(report["local_context"]["liquidity_rows_for_pool"], 1)
        self.assertFalse(report["would_create_client_signal"])
        self.assertFalse(report["would_execute_trade"])
        self.assertFalse(report["would_write"])
        self.assertEqual(report["writes_performed"], 0)

    def test_outcome_sync_liquidity_collection_plan_targets_damaged_windows_read_only(self) -> None:
        pool = "0xc722000a77d0ba1b464f38ef5aa3be638f97db61"
        token = "0x86a2a205807b6250ec7e07419710abf89d06b58b"
        fake_repair = {
            "ok": True,
            "dry_run": True,
            "repair_status": "needs_sync_liquidity_collection",
            "source_outcome_status": "partial_with_local_outcomes",
            "chain": "bsc",
            "pool_address": pool,
            "token_address": token,
            "token_symbol": "UFLOKI",
            "snapshot": {"block_number": 100, "block_timestamp": 1_000},
            "local_context": {"sync_rows_for_pool": 0, "liquidity_rows_for_pool": 0},
            "window_assessments": [
                {
                    "window_label": "plus_1h",
                    "needs_quality_repair": False,
                    "start_block": 100,
                    "end_block": 110,
                    "repair_blockers": [],
                },
                {
                    "window_label": "plus_24h",
                    "needs_quality_repair": True,
                    "start_block": 100,
                    "end_block": 200,
                    "repair_blockers": ["sync_reserve_context_needed_for_window"],
                },
            ],
            "blockers": ["no_local_sync_reserve_rows_for_pool"],
        }
        with patch(
            "services.onchain.manipulation_reliability.get_manipulation_detection_source_backed_outcome_quality_repair_sync_liquidity_context_dry_run",
            return_value=fake_repair,
        ):
            report = onchain_engine.get_manipulation_detection_source_backed_outcome_sync_liquidity_collection_plan(
                chain="bsc",
                dry_run=True,
                max_window_blocks=500,
            )

        self.assertEqual(report["plan_status"], "ready_but_disabled")
        self.assertEqual(report["damaged_windows"][0]["window_label"], "plus_24h")
        self.assertEqual({row["event_name"] for row in report["planned_filters"]}, {"Sync", "Mint", "Burn"})
        self.assertGreater(report["planned_filter_count"], 0)
        self.assertFalse(report["execution_readiness"]["topic_binding_required"])
        self.assertTrue(report["execution_readiness"]["lookup_executable_now"])
        self.assertTrue(all(str(row["topic0"]).startswith("0x") for row in report["planned_filters"]))
        self.assertFalse(report["would_call_rpc"])
        self.assertFalse(report["would_write"])
        self.assertEqual(report["writes_performed"], 0)

