    def test_repaired_outcome_dataset_confirmed_ddl_creates_empty_table_once(self) -> None:
        fake_plan = {
            "plan_status": "ready",
            "target_table": "manipulation_repaired_outcome_windows",
            "planned_repaired_outcome_rows": 4,
            "repair_preview_digest": "digest",
            "blockers": [
                "schema_plan_only_no_table_created",
                "shadow_backtest_not_run",
                "client_signal_disabled",
                "trade_disabled",
            ],
        }
        with patch(
            "services.onchain.manipulation_reliability.get_manipulation_detection_source_backed_repaired_outcome_dataset_schema_plan",
            return_value=fake_plan,
        ):
            dry_run = onchain_engine.create_manipulation_detection_source_backed_repaired_outcome_dataset_table(
                chain="bsc",
                dry_run=True,
            )
            missing_confirm = onchain_engine.create_manipulation_detection_source_backed_repaired_outcome_dataset_table(
                chain="bsc",
                dry_run=False,
            )
            created = onchain_engine.create_manipulation_detection_source_backed_repaired_outcome_dataset_table(
                chain="bsc",
                dry_run=False,
                confirm="CREATE_MANIPULATION_REPAIRED_OUTCOME_WINDOWS",
            )
            second = onchain_engine.create_manipulation_detection_source_backed_repaired_outcome_dataset_table(
                chain="bsc",
                dry_run=False,
                confirm="CREATE_MANIPULATION_REPAIRED_OUTCOME_WINDOWS",
            )

        conn = sqlite3.connect(str(self.onchain_db))
        try:
            row_count = conn.execute("SELECT COUNT(*) FROM manipulation_repaired_outcome_windows").fetchone()[0]
            indexes = {
                row[0]
                for row in conn.execute(
                    "SELECT name FROM sqlite_master WHERE type = 'index' AND tbl_name = 'manipulation_repaired_outcome_windows'"
                ).fetchall()
                if not str(row[0]).startswith("sqlite_autoindex_")
            }
        finally:
            conn.close()

        self.assertEqual(dry_run["create_status"], "ready_but_disabled")
        self.assertTrue(dry_run["would_create_table"])
        self.assertFalse(dry_run["would_write"])
        self.assertEqual(dry_run["writes_performed"], 0)
        self.assertEqual(missing_confirm["create_status"], "blocked")
        self.assertIn("confirm_CREATE_MANIPULATION_REPAIRED_OUTCOME_WINDOWS_required", missing_confirm["blockers"])
        self.assertEqual(created["create_status"], "created")
        self.assertTrue(created["table_created"])
        self.assertEqual(created["rows_inserted"], 0)
        self.assertEqual(created["row_count"], 0)
        self.assertEqual(row_count, 0)
        self.assertGreaterEqual(len(indexes), 6)
        self.assertEqual(second["create_status"], "already_exists")
        self.assertEqual(second["writes_performed"], 0)
        self.assertFalse(created["would_create_client_signal"])
        self.assertFalse(created["would_execute_trade"])
        self.assertFalse(created["would_write"])

