    def test_shadow_replay_controls_preview_finds_local_candidates_read_only(self) -> None:
        source_pool = "0xc722000a77d0ba1b464f38ef5aa3be638f97db61"
        conn = sqlite3.connect(str(self.onchain_db))
        try:
            conn.execute("DROP TABLE IF EXISTS swaps")
            conn.execute(
                """
                CREATE TABLE swaps (
                    tx_hash TEXT,
                    chain TEXT,
                    block_number INTEGER,
                    timestamp INTEGER,
                    wallet TEXT,
                    dex TEXT,
                    token_in TEXT,
                    token_out TEXT,
                    amount_in REAL,
                    amount_out REAL,
                    amount_usd REAL,
                    pool TEXT,
                    token_identity_quality TEXT,
                    pair_rpc_source TEXT,
                    router_addr TEXT,
                    venue_source TEXT,
                    venue_confidence REAL
                )
                """
            )
            rows = []
            for pool_index, pool in enumerate(["0xcontrol1", "0xcontrol2", "0xcontrol3"], start=1):
                for tx_index in range(1, 5):
                    rows.append((
                        f"0xcontrol{pool_index}tx{tx_index}",
                        "bsc",
                        1000 + pool_index * 100 + tx_index,
                        2000 + tx_index,
                        f"0xwallet{tx_index}",
                        "PancakeSwap V2",
                        "0x55d398326f99059ff775485246999027b3197955",
                        f"0xtoken{pool_index}",
                        1.0,
                        2.0,
                        10.0,
                        pool,
                        "exact_pair_log_direction",
                        "binance_public_rpc",
                        "0xrouter",
                        "known_router_address",
                        0.8,
                    ))
            conn.executemany(
                """
                INSERT INTO swaps (
                    tx_hash, chain, block_number, timestamp, wallet, dex,
                    token_in, token_out, amount_in, amount_out, amount_usd,
                    pool, token_identity_quality, pair_rpc_source, router_addr,
                    venue_source, venue_confidence
                ) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)
                """,
                rows,
            )
            conn.commit()
            row_count_before = conn.execute("SELECT COUNT(*) FROM swaps").fetchone()[0]
        finally:
            conn.close()

        source_preview = {
            "preview_status": "ready_but_disabled",
            "pool_address": source_pool,
            "token_address": "0xtoken",
            "token_symbol": "UFLOKI",
            "shadow_backtest_preview_digest": "a" * 64,
            "backtest_preview": {
                "outcome_classification": "negative_for_long_opportunity",
                "would_have_supported_long_client_signal": False,
            },
        }
        with patch(
            "services.onchain.manipulation_reliability.get_manipulation_detection_source_backed_shadow_backtest_preview",
            return_value=source_preview,
        ):
            preview = onchain_engine.get_manipulation_detection_source_backed_shadow_replay_controls_preview(
                chain="bsc",
                pool_address=source_pool,
                limit=5,
                dry_run=True,
                min_swaps=4,
            )

        conn = sqlite3.connect(str(self.onchain_db))
        try:
            row_count_after = conn.execute("SELECT COUNT(*) FROM swaps").fetchone()[0]
        finally:
            conn.close()

        self.assertEqual(preview["preview_status"], "ready_but_disabled")
        self.assertEqual(preview["summary"]["local_control_candidates"], 3)
        self.assertEqual(preview["summary"]["candidate_control_collectable"], 3)
        self.assertFalse(preview["summary"]["negative_controls_ready_now"])
        self.assertIn("control_repaired_outcome_datasets_missing", preview["blockers"])
        self.assertFalse(preview["would_create_negative_control_row"])
        self.assertFalse(preview["would_create_client_signal"])
        self.assertFalse(preview["would_execute_trade"])
        self.assertFalse(preview["would_write"])
        self.assertEqual(preview["writes_performed"], 0)
        self.assertEqual(row_count_before, row_count_after)

