    def test_control_outcome_lookup_dry_run_measures_local_swaps_without_writes(self) -> None:
        conn = sqlite3.connect(str(self.onchain_db))
        try:
            conn.execute("DROP TABLE IF EXISTS swaps")
            conn.execute(
                """
                CREATE TABLE swaps (
                    tx_hash TEXT,
                    chain TEXT,
                    block_number INTEGER,
                    timestamp INTEGER,
                    wallet TEXT,
                    dex TEXT,
                    token_in TEXT,
                    token_out TEXT,
                    amount_in REAL,
                    amount_out REAL,
                    amount_usd REAL,
                    pool TEXT,
                    token_identity_quality TEXT,
                    pair_rpc_source TEXT,
                    router_addr TEXT,
                    venue_source TEXT,
                    venue_confidence REAL
                )
                """
            )
            rows = []
            for idx, (block_number, quote_amount, token_amount) in enumerate(
                [(1000, 100.0, 10.0), (1500, 120.0, 10.0), (2200, 90.0, 10.0)],
                start=1,
            ):
                rows.append((
                    f"0xtx{idx}",
                    "bsc",
                    block_number,
                    2000 + idx,
                    f"0xwallet{idx}",
                    "PancakeSwap V2",
                    "0x55d398326f99059ff775485246999027b3197955",
                    "0xtarget",
                    quote_amount,
                    token_amount,
                    quote_amount,
                    "0xcontrol",
                    "exact_pair_log_direction",
                    "binance_public_rpc",
                    "0xrouter",
                    "known_router_address",
                    0.8,
                ))
            conn.executemany(
                """
                INSERT INTO swaps (
                    tx_hash, chain, block_number, timestamp, wallet, dex,
                    token_in, token_out, amount_in, amount_out, amount_usd,
                    pool, token_identity_quality, pair_rpc_source, router_addr,
                    venue_source, venue_confidence
                ) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)
                """,
                rows,
            )
            conn.commit()
            row_count_before = conn.execute("SELECT COUNT(*) FROM swaps").fetchone()[0]
        finally:
            conn.close()

        plan = {
            "plan_status": "ready_but_disabled",
            "source_case": {"pool_address": "0xsource", "token_symbol": "UFLOKI"},
            "control_outcome_plan_digest": "b" * 64,
            "planned_controls": [
                {
                    "chain": "bsc",
                    "pool_address": "0xcontrol",
                    "dex": "PancakeSwap V2",
                    "token_symbols": ["USDT", "TGT"],
                    "token_addresses": ["0x55d398326f99059ff775485246999027b3197955", "0xtarget"],
                    "control_status": "candidate_control_collectable",
                    "planned_windows": [
                        {
                            "window_label": "plus_1h",
                            "anchor_block": 1000,
                            "expected_end_block": 2500,
                            "local_coverage_status": "local_swaps_cover_window",
                            "would_collect_now": False,
                        }
                    ],
                }
            ],
            "blockers": ["control_outcomes_not_collected"],
        }
        with patch(
            "services.onchain.manipulation_reliability.get_manipulation_detection_source_backed_control_outcome_collection_plan",
            return_value=plan,
        ):
            lookup = onchain_engine.run_manipulation_detection_source_backed_control_outcome_lookup_dry_run(
                chain="bsc",
                dry_run=True,
            )

        conn = sqlite3.connect(str(self.onchain_db))
        try:
            row_count_after = conn.execute("SELECT COUNT(*) FROM swaps").fetchone()[0]
        finally:
            conn.close()

        self.assertEqual(lookup["lookup_status"], "ready_but_disabled")
        self.assertEqual(lookup["summary"]["ready_control_windows"], 1)
        self.assertEqual(lookup["assessed_controls"][0]["ready_windows"], 1)
        window = lookup["assessed_controls"][0]["assessed_windows"][0]
        self.assertEqual(window["lookup_status"], "local_proxy_ready")
        self.assertEqual(window["price_proxy_points"], 3)
        self.assertEqual(window["max_favorable_move_pct"], 20.0)
        self.assertEqual(window["max_adverse_move_pct"], -10.0)
        self.assertFalse(lookup["would_persist_control_outcome"])
        self.assertFalse(lookup["would_create_client_signal"])
        self.assertFalse(lookup["would_execute_trade"])
        self.assertFalse(lookup["would_write"])
        self.assertEqual(lookup["writes_performed"], 0)
        self.assertEqual(row_count_before, row_count_after)

