    def test_top_expansion_raw_context_evidence_schema_plan_reuses_raw_tables_read_only(self) -> None:
        conn = sqlite3.connect(str(self.onchain_db))
        try:
            for table in ("dex_raw_swap_events", "dex_raw_sync_events", "erc20_transfer_events"):
                conn.execute(f"CREATE TABLE IF NOT EXISTS {table} (id INTEGER PRIMARY KEY AUTOINCREMENT)")
            before = {
                table: conn.execute(f"SELECT COUNT(*) FROM {table}").fetchone()[0]
                for table in ("dex_raw_swap_events", "dex_raw_sync_events", "erc20_transfer_events")
            }
            conn.commit()
        finally:
            conn.close()

        lookup = {
            "lookup_status": "ready_but_external_disabled",
            "raw_context_collection_plan_digest": "plan-digest",
            "candidate_count": 3,
            "planned_filter_count": 48,
            "planned_filter_chunk_count": 240,
            "selected_filter_count": 9,
            "selection_strategy": "balanced_candidate_event_coverage",
            "max_logs_per_filter": 50,
            "required_confirm": "RUN_TOP_EXPANSION_RAW_CONTEXT_LOOKUP",
        }
        with patch(
            "services.onchain.manipulation_reliability.run_manipulation_detection_source_backed_top_expansion_raw_context_lookup_dry_run",
            return_value=lookup,
        ):
            plan = onchain_engine.get_manipulation_detection_source_backed_top_expansion_raw_context_evidence_schema_plan(
                chain="bsc",
                dry_run=True,
            )
            blocked = onchain_engine.get_manipulation_detection_source_backed_top_expansion_raw_context_evidence_schema_plan(
                chain="bsc",
                dry_run=False,
            )

        conn = sqlite3.connect(str(self.onchain_db))
        try:
            after = {
                table: conn.execute(f"SELECT COUNT(*) FROM {table}").fetchone()[0]
                for table in ("dex_raw_swap_events", "dex_raw_sync_events", "erc20_transfer_events")
            }
        finally:
            conn.close()

        self.assertEqual(plan["plan_status"], "ready_but_disabled")
        self.assertEqual(plan["target_tables"], ["dex_raw_swap_events", "dex_raw_sync_events", "erc20_transfer_events"])
        self.assertEqual(plan["lookup_preview"]["selected_filter_count"], 9)
        self.assertEqual(plan["lookup_preview"]["selection_strategy"], "balanced_candidate_event_coverage")
        self.assertTrue(plan["future_insert_requirements"]["expected_raw_context_lookup_digest_required"])
        self.assertTrue(plan["future_insert_requirements"]["duplicate_event_dedupe_key_blocks"])
        self.assertFalse(plan["would_create_table"])
        self.assertFalse(plan["would_insert_raw_context"])
        self.assertFalse(plan["would_create_mapping"])
        self.assertFalse(plan["would_create_client_signal"])
        self.assertFalse(plan["would_execute_trade"])
        self.assertFalse(plan["would_write"])
        self.assertEqual(plan["writes_performed"], 0)
        self.assertIn("dry_run_required", blocked["blockers"])
        self.assertEqual(after, before)

