    def test_entity_chain_gap_report_is_chain_scoped_and_read_only(self) -> None:
        before_labels = label_ledger.get_label_ledger_summary()["labels"]

        report = onchain_engine.get_rpc_entity_chain_gap_report(min_confidence="medium", limit=10)
        rows = {(row["entity"], row["chain"]): row for row in report["rows"]}

        self.assertEqual(before_labels, 5)
