        self.assertEqual(rows[("Binance", "eth")]["labelled_wallets"], 3)
        self.assertEqual(rows[("Binance", "eth")]["rpc_wallets"], 1)
        self.assertEqual(rows[("Binance", "eth")]["missing_wallets"], 2)
        self.assertEqual(rows[("Binance", "bsc")]["labelled_wallets"], 2)
