        self.assertEqual(row["legacy_or_unverified_labelled_wallets"], 4)
        self.assertEqual(row["label_source_breakdown"]["manual_verified"], 1)
        self.assertEqual(row["label_source_breakdown"]["legacy_scrapling"], 1)
        self.assertEqual(row["label_source_breakdown"]["unknown"], 3)
        self.assertEqual(row["label_quality_status"], "strict_seeded")

