        self.assertEqual(report["token_addresses"], [token])
        self.assertEqual(report["summary"]["deposits"], 1)
        self.assertEqual(report["summary"]["target_exchange_wallets"], 1)
        self.assertEqual(report["rows"][0]["token"], token)
        self.assertEqual(report["rows"][0]["transfer_source"], "erc20_transfer_events")
        self.assertEqual(report["rows"][0]["target_entity"], "Bitget")
        self.assertEqual(report["rows"][0]["proof_status"], "token_transfer_to_source_backed_exchange_wallet")
        self.assertFalse(report["rows"][0]["client_copy_allowed"])
        self.assertFalse(report["rows"][0]["execution_enabled"])

