    def test_local_native_ground_truth_discovery_prefers_local_data_read_only(self) -> None:
        token = "0x" + "7" * 40
        pool = "0x" + "8" * 40
        wbnb = "0xbb4cdb9cbd36b01bd1cbaebf2de08d9173bc095c"
        conn = sqlite3.connect(str(self.onchain_db))
        now_ts = int(time.time()) - 90 * 86_400
        try:
            conn.execute(
                """
                INSERT INTO pair_tokens(chain, pool, token0, token1, rpc_source, observed_at)
                VALUES ('bsc', ?, ?, ?, 'test', ?)
                """,
                (pool, wbnb, token, now_ts),
            )
            conn.execute(
                """
                INSERT INTO token_metadata(chain, token_address, symbol, name, decimals, rpc_source, observed_at, status)
                VALUES ('bsc', ?, 'NATIVE', 'Native Candidate', 18, 'test', ?, 'resolved')
                """,
                (token, now_ts),
            )
            for idx in range(3):
                conn.execute(
                    """
                    INSERT INTO token_transfers(
                        tx_hash, log_index, chain, block_number, timestamp, token,
                        from_addr, to_addr, value_raw, source
                    ) VALUES (?, 0, 'bsc', ?, ?, ?, ?, ?, '1', 'test')
                    """,
                    (
                        f"0xnative{idx}",
                        2000 + idx,
                        now_ts + idx,
                        token,
                        "0x" + str(idx + 1) * 40,
                        "0x" + str(idx + 2) * 40,
                    ),
                )
            conn.commit()
            before_counts = {
                table: conn.execute(f"SELECT COUNT(*) FROM {table}").fetchone()[0]
                for table in ["token_transfers", "wallet_chain_state", "swaps", "pair_tokens"]
            }
        finally:
            conn.close()

        report = onchain_engine.get_manipulation_detection_local_native_ground_truth_discovery_preview(
            chain="bsc",
            limit=5,
            dry_run=True,
            min_swaps=0,
            min_transfers=1,
        )

        conn = sqlite3.connect(str(self.onchain_db))
        try:
            after_counts = {
                table: conn.execute(f"SELECT COUNT(*) FROM {table}").fetchone()[0]
                for table in ["token_transfers", "wallet_chain_state", "swaps", "pair_tokens"]
            }
            table_exists = bool(conn.execute(
                "SELECT 1 FROM sqlite_master WHERE type='table' AND name=?",
                ("cex_listing_ground_truth_dataset",),
            ).fetchone())
        finally:
            conn.close()

        self.assertEqual(before_counts, after_counts)
        self.assertFalse(table_exists)
        self.assertEqual(report["discovery_status"], "ready_but_disabled")
        self.assertGreaterEqual(report["summary"]["native_candidates"], 1)
        candidate = next(row for row in report["candidates"] if row["token_address"] == token)
        self.assertEqual(candidate["token_symbol"], "NATIVE")
        self.assertEqual(candidate["native_context_status"], "labeling_candidate")
