    def test_cex_listing_ground_truth_dataset_create_is_ddl_only_and_idempotent(self) -> None:
        bridge = {
            "ok": True,
            "bridge_status": "ready_but_disabled",
            "summary": {"behavioral_candidates_checked": 0},
            "next_safe_step": "cex_listing_ground_truth_dataset_plan_read_only",
            "blockers": ["cex_announcement_ground_truth_missing"],
        }
        conn = sqlite3.connect(str(self.onchain_db))
        try:
            before_counts = {
                table: conn.execute(f"SELECT COUNT(*) FROM {table}").fetchone()[0]
                for table in ["token_transfers", "wallet_chain_state", "swaps"]
            }
        finally:
            conn.close()

        with patch(
            "services.onchain.cex_listing_prediction.get_manipulation_detection_cex_listing_probability_bridge_preview",
            return_value=bridge,
        ):
            dry_run = onchain_engine.create_manipulation_detection_cex_listing_ground_truth_dataset(
                chain="bsc",
                dry_run=True,
            )
            created = onchain_engine.create_manipulation_detection_cex_listing_ground_truth_dataset(
                chain="bsc",
                dry_run=False,
                confirm="CREATE_CEX_LISTING_GROUND_TRUTH_DATASET",
            )
            second = onchain_engine.create_manipulation_detection_cex_listing_ground_truth_dataset(
                chain="bsc",
                dry_run=False,
                confirm="CREATE_CEX_LISTING_GROUND_TRUTH_DATASET",
            )

        conn = sqlite3.connect(str(self.onchain_db))
        try:
            after_counts = {
                table: conn.execute(f"SELECT COUNT(*) FROM {table}").fetchone()[0]
                for table in ["token_transfers", "wallet_chain_state", "swaps"]
            }
            row_count = conn.execute("SELECT COUNT(*) FROM cex_listing_ground_truth_dataset").fetchone()[0]
            columns = {row[1] for row in conn.execute("PRAGMA table_info(cex_listing_ground_truth_dataset)").fetchall()}
            indexes = {
                row[0]
                for row in conn.execute(
                    "SELECT name FROM sqlite_master WHERE type='index' AND tbl_name='cex_listing_ground_truth_dataset'"
                ).fetchall()
                if not str(row[0]).startswith("sqlite_autoindex_")
            }
        finally:
            conn.close()

        self.assertEqual(before_counts, after_counts)
        self.assertEqual(dry_run["create_status"], "ready_but_disabled")
        self.assertTrue(dry_run["would_create_ground_truth_table"])
        self.assertEqual(dry_run["row_count"], 0)
        self.assertFalse(dry_run["would_write"])
        self.assertEqual(created["create_status"], "created")
        self.assertTrue(created["table_created"])
        self.assertEqual(created["rows_inserted"], 0)
        self.assertEqual(created["row_count"], 0)
        self.assertFalse(created["would_insert_ground_truth_rows"])
        self.assertFalse(created["would_create_listing_signal"])
        self.assertFalse(created["would_execute_trade"])
        self.assertEqual(second["create_status"], "already_exists")
        self.assertFalse(second["table_created"])
        self.assertEqual(second["rows_inserted"], 0)
        self.assertEqual(second["row_count"], 0)
        self.assertEqual(row_count, 0)
        self.assertIn("dedupe_key", columns)
        self.assertIn("idx_cex_listing_ground_truth_dedupe", indexes)

    def test_cex_listing_ground_truth_rows_insert_dry_run_first_and_blocks_duplicate(self) -> None:
        bridge = {
            "ok": True,
            "bridge_status": "ready_but_disabled",
            "summary": {"behavioral_candidates_checked": 0},
            "next_safe_step": "cex_listing_ground_truth_dataset_plan_read_only",
            "blockers": ["cex_announcement_ground_truth_missing"],
        }
        positive = {
            "chain": "bsc",
            "token_address": "0x" + "1" * 40,
            "token_symbol": "POS",
            "cex_name": "Gate",
            "market_pair": "POS/USDT",
            "announcement_url": "https://example.com/gate-pos-listing",
            "announcement_at": "2026-01-01T00:00:00Z",
            "listing_at": "2026-01-02T00:00:00Z",
            "listing_tier": "tier_2_listing",
            "source_tier": "tier_2",
            "source_digest": "a" * 64,
        }
        negative = {
            "chain": "bsc",
            "token_address": "0x" + "2" * 40,
            "token_symbol": "NEG",
            "cex_name": "NONE",
            "market_pair": "NONE",
            "announcement_url": "https://example.com/negative-cohort-neg",
            "listing_tier": "negative_never_listed_90d",
            "source_tier": "manual_source_backed",
            "source_digest": "b" * 64,
        }
        rows = [positive, negative]
        with patch(
            "services.onchain.cex_listing_prediction.get_manipulation_detection_cex_listing_probability_bridge_preview",
            return_value=bridge,
        ):
            onchain_engine.create_manipulation_detection_cex_listing_ground_truth_dataset(
                chain="bsc",
                dry_run=False,
                confirm="CREATE_CEX_LISTING_GROUND_TRUTH_DATASET",
            )
            dry_run = onchain_engine.insert_manipulation_detection_cex_listing_ground_truth_rows(
                rows=rows,
                chain="bsc",
                dry_run=True,
            )
            expected_keys = dry_run["expected_dedupe_keys_required_for_real"]
            inserted = onchain_engine.insert_manipulation_detection_cex_listing_ground_truth_rows(
                rows=rows,
                chain="bsc",
                dry_run=False,
                confirm="INSERT_CEX_LISTING_GROUND_TRUTH_ROWS",
                expected_dedupe_keys=expected_keys,
            )
            duplicate = onchain_engine.insert_manipulation_detection_cex_listing_ground_truth_rows(
                rows=rows,
                chain="bsc",
                dry_run=False,
                confirm="INSERT_CEX_LISTING_GROUND_TRUTH_ROWS",
                expected_dedupe_keys=expected_keys,
            )

        conn = sqlite3.connect(str(self.onchain_db))
        try:
            row_count = conn.execute("SELECT COUNT(*) FROM cex_listing_ground_truth_dataset").fetchone()[0]
            labels = {
                row[0]
                for row in conn.execute("SELECT listing_tier FROM cex_listing_ground_truth_dataset").fetchall()
            }
        finally:
            conn.close()

        self.assertEqual(dry_run["insert_status"], "ready_but_disabled")
        self.assertEqual(dry_run["eligible_rows"], 2)
        self.assertEqual(dry_run["positive_rows"], 1)
        self.assertEqual(dry_run["negative_rows"], 1)
        self.assertTrue(dry_run["would_insert_ground_truth_rows"])
        self.assertEqual(dry_run["writes_performed"], 0)
        self.assertEqual(inserted["insert_status"], "inserted")
        self.assertEqual(inserted["rows_inserted"], 2)
        self.assertEqual(inserted["row_count_after"], 2)
        self.assertFalse(inserted["would_create_listing_signal"])
        self.assertFalse(inserted["would_execute_trade"])
        self.assertEqual(duplicate["insert_status"], "blocked")
        self.assertIn("row_0_duplicate_dedupe_key_already_exists", duplicate["blockers"])
        self.assertEqual(row_count, 2)
        self.assertEqual(labels, {"tier_2_listing", "negative_never_listed_90d"})

