    def test_dex_router_official_evidence_queue_schema_plan_is_read_only(self) -> None:
        conn = sqlite3.connect(str(self.onchain_db))
        try:
            table_before = conn.execute(
                "SELECT 1 FROM sqlite_master WHERE type = 'table' AND name = 'dex_router_official_evidence_queue'"
            ).fetchone()
            wallet_rows_before = conn.execute("SELECT COUNT(*) FROM wallet_chain_state").fetchone()[0]
            swap_rows_before = conn.execute("SELECT COUNT(*) FROM swaps").fetchone()[0]
        finally:
            conn.close()

        plan = onchain_engine.get_dex_router_official_evidence_queue_schema_plan(dry_run=True)

        conn = sqlite3.connect(str(self.onchain_db))
        try:
            table_after = conn.execute(
                "SELECT 1 FROM sqlite_master WHERE type = 'table' AND name = 'dex_router_official_evidence_queue'"
            ).fetchone()
            wallet_rows_after = conn.execute("SELECT COUNT(*) FROM wallet_chain_state").fetchone()[0]
            swap_rows_after = conn.execute("SELECT COUNT(*) FROM swaps").fetchone()[0]
        finally:
            conn.close()

        self.assertTrue(plan["ok"])
        self.assertTrue(plan["dry_run"])
        self.assertFalse(plan["table_exists"])
        self.assertEqual(plan["target_table"], "dex_router_official_evidence_queue")
        self.assertTrue(plan["migration_required"])
        self.assertFalse(plan["would_create_table"])
        self.assertFalse(plan["would_write"])
        self.assertEqual(plan["writes_performed"], 0)
        self.assertIn("chain TEXT NOT NULL", plan["schema_preview"])
        self.assertIn("router_address TEXT NOT NULL", plan["schema_preview"])
        self.assertTrue(any(index["unique"] for index in plan["indexes_preview"]))
        self.assertIsNone(table_before)
        self.assertIsNone(table_after)
        self.assertEqual(wallet_rows_before, wallet_rows_after)
        self.assertEqual(swap_rows_before, swap_rows_after)

    def test_create_dex_router_official_evidence_queue_is_confirmed_and_idempotent(self) -> None:
        conn = sqlite3.connect(str(self.onchain_db))
        try:
            wallet_rows_before = conn.execute("SELECT COUNT(*) FROM wallet_chain_state").fetchone()[0]
            swap_rows_before = conn.execute("SELECT COUNT(*) FROM swaps").fetchone()[0]
        finally:
            conn.close()

        dry_run = onchain_engine.create_dex_router_official_evidence_queue(dry_run=True)
        self.assertTrue(dry_run["dry_run"])
        self.assertTrue(dry_run["would_create_table"])
        self.assertFalse(dry_run["would_write"])
        self.assertEqual(dry_run["writes_performed"], 0)

        blocked = onchain_engine.create_dex_router_official_evidence_queue(
            dry_run=False,
            confirm=None,
        )
        self.assertFalse(blocked["ok"])
        self.assertIn("confirm_CREATE_DEX_ROUTER_OFFICIAL_EVIDENCE_QUEUE_required", blocked["blockers"])

        created = onchain_engine.create_dex_router_official_evidence_queue(
            dry_run=False,
            confirm="CREATE_DEX_ROUTER_OFFICIAL_EVIDENCE_QUEUE",
        )
        self.assertTrue(created["ok"])
        self.assertTrue(created["table_exists"])
        self.assertEqual(created["evidence_rows"], 0)
        self.assertGreaterEqual(created["writes_performed"], 1)

        second = onchain_engine.create_dex_router_official_evidence_queue(
            dry_run=False,
            confirm="CREATE_DEX_ROUTER_OFFICIAL_EVIDENCE_QUEUE",
        )
        self.assertTrue(second["ok"])
        self.assertTrue(second["table_exists"])
        self.assertEqual(second["evidence_rows"], 0)
        self.assertEqual(second["writes_performed"], 0)

        conn = sqlite3.connect(str(self.onchain_db))
        try:
            table_after = conn.execute(
                "SELECT 1 FROM sqlite_master WHERE type = 'table' AND name = 'dex_router_official_evidence_queue'"
            ).fetchone()
            evidence_rows = conn.execute("SELECT COUNT(*) FROM dex_router_official_evidence_queue").fetchone()[0]
            wallet_rows_after = conn.execute("SELECT COUNT(*) FROM wallet_chain_state").fetchone()[0]
            swap_rows_after = conn.execute("SELECT COUNT(*) FROM swaps").fetchone()[0]
        finally:
            conn.close()

        self.assertIsNotNone(table_after)
        self.assertEqual(evidence_rows, 0)
        self.assertEqual(wallet_rows_before, wallet_rows_after)
        self.assertEqual(swap_rows_before, swap_rows_after)

    def test_insert_dex_router_official_evidence_is_confirmed_deduped_and_non_mutating(self) -> None:
        wallet = "0x" + "1" * 40
        router = "0x" + "8" * 40
        conn = sqlite3.connect(str(self.onchain_db))
        try:
            wallet_rows_before = conn.execute("SELECT COUNT(*) FROM wallet_chain_state").fetchone()[0]
            swap_rows_before = conn.execute("SELECT COUNT(*) FROM swaps").fetchone()[0]
            conn.execute(
                """
                INSERT INTO swaps (
                    tx_hash, chain, block_number, timestamp, wallet, dex,
                    token_in, token_out, amount_in, amount_out, amount_usd, pool,
                    router_addr, venue_source, venue_confidence, token_identity_quality
                ) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)
                """,
                (
                    "0x" + "f" * 64,
                    "eth",
                    1_014,
                    1_778_600_500,
                    wallet,
                    "Unknown DEX",
                    "0x" + "d" * 40,
                    "0x" + "e" * 40,
                    1.0,
                    2.0,
                    10.0,
                    "0x" + "f" * 40,
                    router,
                    "swap_pool_event_unattributed",
                    0.35,
                    "exact_pair_log_direction",
                ),
            )
            conn.execute(
                """
                INSERT INTO wallet_chain_state (
                    chain, address, native_balance, tx_count, token_balances_json,
                    rpc_source, label, entity, confidence, address_kind, is_contract,
                    native_value_usd, activity_tier, risk_flags_json, data_quality_score,
                    label_sources_json, source_attribution_json, observed_at
                ) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)
                """,
                (
                    "eth",
                    router,
                    0.0,
                    12,
                    "[]",
                    "test_rpc",
                    "",
                    "",
                    "low",
                    "contract",
                    1,
                    0.0,
                    "contract",
                    json.dumps(["router_like_contract"]),
                    72,
                    "[]",
                    json.dumps({"rpc": "test_rpc", "source": "unit"}),
                    1_778_600_500,
                ),
            )
            conn.commit()
            wallet_rows_seeded = conn.execute("SELECT COUNT(*) FROM wallet_chain_state").fetchone()[0]
            swap_rows_seeded = conn.execute("SELECT COUNT(*) FROM swaps").fetchone()[0]
        finally:
            conn.close()

        table_missing = onchain_engine.insert_dex_router_official_evidence(
            "eth",
            router,
            "official_protocol_docs",
            "https://docs.example.org/contracts",
            "official docs mention exact router",
            True,
        )
        self.assertFalse(table_missing["ok"])
        self.assertEqual(table_missing["dedupe_status"], "table_missing")
        self.assertIn("dex_router_official_evidence_queue_missing", table_missing["blockers"])

        onchain_engine.create_dex_router_official_evidence_queue(
            dry_run=False,
            confirm="CREATE_DEX_ROUTER_OFFICIAL_EVIDENCE_QUEUE",
        )
        dry_run = onchain_engine.insert_dex_router_official_evidence(
            "eth",
            router,
            "official_protocol_docs",
            "https://docs.example.org/contracts",
            "official docs mention exact router",
            True,
        )
        self.assertTrue(dry_run["ok"])
        self.assertFalse(dry_run["inserted"])
        self.assertEqual(dry_run["dedupe_status"], "new")
        self.assertTrue(dry_run["would_insert"])
        self.assertFalse(dry_run["would_write"])
        self.assertEqual(dry_run["writes_performed"], 0)

        rejected = onchain_engine.insert_dex_router_official_evidence(
            "eth",
            router,
            "explorer_label_only",
            "https://etherscan.io/address/" + router,
            None,
            True,
        )
        self.assertFalse(rejected["ok"])
        self.assertIn("evidence_not_accepted", rejected["blockers"])

        inserted = onchain_engine.insert_dex_router_official_evidence(
            "eth",
            router,
            "official_protocol_docs",
            "https://docs.example.org/contracts",
            "official docs mention exact router",
            False,
            "INSERT_DEX_ROUTER_OFFICIAL_EVIDENCE",
        )
        self.assertTrue(inserted["inserted"])
        self.assertEqual(inserted["writes_performed"], 1)

        duplicate = onchain_engine.insert_dex_router_official_evidence(
            "eth",
            router,
            "official_protocol_docs",
            "https://docs.example.org/contracts",
            "official docs mention exact router",
            False,
            "INSERT_DEX_ROUTER_OFFICIAL_EVIDENCE",
        )
        self.assertFalse(duplicate["inserted"])
        self.assertEqual(duplicate["dedupe_status"], "duplicate")
        self.assertIn("duplicate_dedupe_key", duplicate["blockers"])

        conn = sqlite3.connect(str(self.onchain_db))
        try:
            evidence_rows = conn.execute("SELECT COUNT(*) FROM dex_router_official_evidence_queue").fetchone()[0]
            wallet_rows_after = conn.execute("SELECT COUNT(*) FROM wallet_chain_state").fetchone()[0]
            swap_rows_after = conn.execute("SELECT COUNT(*) FROM swaps").fetchone()[0]
        finally:
            conn.close()

        self.assertEqual(evidence_rows, 1)
        self.assertEqual(wallet_rows_seeded, wallet_rows_before + 1)
        self.assertEqual(swap_rows_seeded, swap_rows_before + 1)
        self.assertEqual(wallet_rows_after, wallet_rows_seeded)
        self.assertEqual(swap_rows_after, swap_rows_seeded)

