        self.assertIn("APPLY_DEX_ROUTER_VENUE_MAPPING", no_confirm["required_confirmations"])
        self.assertIn("CONFIRM_DEX_VENUE_MAPPING_WRITE", no_confirm["required_confirmations"])
        self.assertIn("CONFIRM_ROLLBACK_ARTIFACT_BOUND", no_confirm["required_confirmations"])
