        self.assertEqual(no_confirm["rollback_artifact_summary"]["artifact_id"], created_artifact["artifact_id"])
        self.assertIn("rollback_artifact_row_still_exists", no_confirm["required_transaction_rechecks"])
        self.assertIn(
            "rollback_artifact_plan_digest_still_matches_current_plan",
            no_confirm["required_transaction_rechecks"],
        )
        self.assertIn("recheck_inside_same_db_transaction", no_confirm["transaction_rechecks_required"])
        self.assertIsNotNone(no_confirm["write_preview"])
        self.assertIsNotNone(no_confirm["rollback_preview"])
        self.assertFalse(partial_confirm["confirm_received"])
        self.assertTrue(with_confirm["confirm_received"])
        self.assertFalse(with_confirm["mapping_allowed_now"])
        self.assertFalse(with_confirm["real_write_enabled"])
        self.assertEqual(with_confirm["writes_performed"], 0)
        self.assertEqual(blocked["apply_status"], "blocked")
        self.assertFalse(blocked["would_write"])

        conn = sqlite3.connect(str(self.onchain_db))
        try:
            evidence_rows = conn.execute("SELECT COUNT(*) FROM dex_router_official_evidence_queue").fetchone()[0]
            artifact_rows = conn.execute("SELECT COUNT(*) FROM dex_venue_mapping_rollback_artifacts").fetchone()[0]
            wallet_rows_after = conn.execute("SELECT COUNT(*) FROM wallet_chain_state").fetchone()[0]
            swap_rows_after = conn.execute("SELECT COUNT(*) FROM swaps").fetchone()[0]
            mapping_rows_after = conn.execute("SELECT COUNT(*) FROM dex_venue_mappings").fetchone()[0]
        finally:
            conn.close()

        self.assertEqual(evidence_rows, 1)
        self.assertEqual(artifact_rows, 1)
        self.assertEqual(wallet_rows_after, wallet_rows_seeded)
        self.assertEqual(swap_rows_after, swap_rows_seeded)
        self.assertEqual(mapping_rows_after, mapping_rows_seeded)

