        ready = onchain_engine.get_dex_router_venue_mapping_real_write_go_nogo(
            inserted["row_id"],
            "ExampleSwap",
            True,
        )
        blocked = onchain_engine.get_dex_router_venue_mapping_real_write_go_nogo(
            999_999,
            "ExampleSwap",
            True,
        )

        self.assertEqual(ready["decision"], "go_for_write_design")
        self.assertTrue(ready["pipeline_ready"])
        self.assertTrue(ready["apply_contract_ready"])
        self.assertTrue(ready["safety_ready"])
        self.assertTrue(ready["write_preview_ready"])
        self.assertTrue(ready["rollback_preview_ready"])
        self.assertTrue(ready["rollback_artifact_ready"])
        self.assertTrue(ready["plan_digest_bound"])
        self.assertEqual(ready["rollback_artifact_guard"]["rollback_artifact_id"], created_artifact["artifact_id"])
        self.assertEqual(ready["rollback_artifact_summary"]["artifact_id"], created_artifact["artifact_id"])
        self.assertIn("rollback_artifact_row_still_exists", ready["required_transaction_rechecks"])
        self.assertIn("rollback_artifact_plan_digest_still_matches_current_plan", ready["required_transaction_rechecks"])
        self.assertTrue(ready["transaction_rechecks_ready"])
        self.assertIn("rollback_artifact_ready", ready["go_reasons"])
        self.assertIn("rollback_plan_digest_bound", ready["go_reasons"])
        self.assertIn("transaction_rechecks_complete", ready["go_reasons"])
        self.assertEqual(ready["required_next_goal"], "design_real_confirmed_transactional_write_endpoint")
        self.assertIn("dex_venue_mapping_write", ready["must_remain_disabled"])
        self.assertFalse(ready["mapping_allowed_now"])
        self.assertFalse(ready["real_write_enabled"])
        self.assertEqual(ready["writes_performed"], 0)
        self.assertEqual(blocked["decision"], "no_go")
        self.assertFalse(blocked["pipeline_ready"])

        with patch("services.onchain_engine.get_dex_router_venue_mapping_apply_confirmed_design") as fake_apply:
            fake_apply.return_value = {
                **ready,
                "apply_status": "ready_for_future_confirm",
                "would_write": True,
                    "write_preview": {"ok": True},
                    "rollback_preview": {"ok": True},
                    "transaction_rechecks_required": ["evidence_row_still_pending"],
                    "rollback_artifact_ready": True,
                    "plan_digest_bound": True,
                    "blockers": [],
                    "missing_proofs": [],
                }
