    def test_token_market_discovery_candidates_create_is_ddl_only_and_idempotent(self) -> None:
        def count_table(conn: sqlite3.Connection, table: str) -> int | None:
            try:
                return conn.execute(f"SELECT COUNT(*) FROM {table}").fetchone()[0]
            except sqlite3.OperationalError:
                return None

        conn = sqlite3.connect(str(self.onchain_db))
        try:
            before_counts = {
                "evidence": count_table(conn, "dex_router_official_evidence_queue"),
                "mappings": count_table(conn, "dex_venue_mappings"),
                "artifacts": count_table(conn, "dex_venue_mapping_rollback_artifacts"),
                "wallets": count_table(conn, "wallet_chain_state"),
                "swaps": count_table(conn, "swaps"),
            }
        finally:
            conn.close()

        dry_run = onchain_engine.create_token_market_discovery_candidates(
            token_symbol="LAB",
            chain="bsc",
            dry_run=True,
        )
        missing_confirm = onchain_engine.create_token_market_discovery_candidates(
            token_symbol="LAB",
            chain="bsc",
            dry_run=False,
        )

        conn = sqlite3.connect(str(self.onchain_db))
        try:
            table_before_confirm = conn.execute(
                "SELECT 1 FROM sqlite_master WHERE type='table' AND name='token_market_discovery_candidates'"
            ).fetchone()
        finally:
            conn.close()

        created = onchain_engine.create_token_market_discovery_candidates(
            token_symbol="LAB",
            chain="bsc",
            dry_run=False,
            confirm="CREATE_TOKEN_MARKET_DISCOVERY_CANDIDATES_TABLE",
        )
        repeated = onchain_engine.create_token_market_discovery_candidates(
            token_symbol="LAB",
            chain="bsc",
            dry_run=False,
            confirm="CREATE_TOKEN_MARKET_DISCOVERY_CANDIDATES_TABLE",
        )

        conn = sqlite3.connect(str(self.onchain_db))
        try:
            candidate_rows = conn.execute("SELECT COUNT(*) FROM token_market_discovery_candidates").fetchone()[0]
            index_names = {
                row[0]
                for row in conn.execute(
                    "SELECT name FROM sqlite_master WHERE type='index' AND tbl_name='token_market_discovery_candidates'"
                ).fetchall()
            }
            after_counts = {
                "evidence": count_table(conn, "dex_router_official_evidence_queue"),
                "mappings": count_table(conn, "dex_venue_mappings"),
                "artifacts": count_table(conn, "dex_venue_mapping_rollback_artifacts"),
                "wallets": count_table(conn, "wallet_chain_state"),
                "swaps": count_table(conn, "swaps"),
            }
        finally:
            conn.close()

        self.assertTrue(dry_run["would_create_table"])
        self.assertFalse(dry_run["would_write"])
        self.assertEqual(dry_run["writes_performed"], 0)
        self.assertIsNone(table_before_confirm)
        self.assertTrue(missing_confirm["blocked"])
        self.assertIn("confirm_CREATE_TOKEN_MARKET_DISCOVERY_CANDIDATES_TABLE_required", missing_confirm["blockers"])
        self.assertTrue(created["table_created"])
        self.assertTrue(created["idempotent"])
        self.assertEqual(created["candidate_rows"], 0)
        self.assertGreater(created["writes_performed"], 0)
        self.assertFalse(created["would_create_table"])
        self.assertFalse(created["would_write"])
        self.assertTrue(repeated["idempotent"])
        self.assertEqual(repeated["candidate_rows"], 0)
        self.assertEqual(repeated["writes_performed"], 0)
        self.assertEqual(candidate_rows, 0)
        self.assertIn("token_market_discovery_candidates_dedupe_key_uq", index_names)
        self.assertIn("token_market_discovery_candidates_token_symbol_idx", index_names)
        self.assertIn("token_market_discovery_candidates_token_chain_idx", index_names)
        self.assertIn("token_market_discovery_candidates_chain_pool_idx", index_names)
        self.assertEqual(after_counts, before_counts)

