        tier_1 = onchain_engine.insert_token_market_discovery_candidate(
            token_symbol="LAB",
            market_type="cex",
            venue_name="Gate",
            pair="LAB/USDT",
            source_url="https://gate.example/markets/lab-usdt",
            source_tier="tier_1",
            evidence_type="official_exchange_market_page",
            dry_run=False,
            confirm="INSERT_TOKEN_MARKET_DISCOVERY_CANDIDATE",
        )
        tier_3 = onchain_engine.insert_token_market_discovery_candidate(
            token_symbol="LAB",
            market_type="cex",
            venue_name="Bitget",
            pair="LAB/USDT",
            source_url="https://coinmarketcap.example/lab",
            source_tier="tier_3",
            evidence_type="aggregator_listing",
            dry_run=False,
            confirm="INSERT_TOKEN_MARKET_DISCOVERY_CANDIDATE",
        )
        dex = onchain_engine.insert_token_market_discovery_candidate(
            token_symbol="LAB",
            chain="bsc",
            market_type="dex",
            token_contract="0x" + "a" * 40,
            pool_or_pair_address="0x" + "b" * 40,
            source_url="https://docs.example.org/contracts",
            source_tier="tier_2",
            evidence_type="official_protocol_docs",
            dry_run=False,
            confirm="INSERT_TOKEN_MARKET_DISCOVERY_CANDIDATE",
        )
        conn = sqlite3.connect(str(self.onchain_db))
        try:
            conn.execute(
                """
                INSERT INTO token_market_discovery_candidates (
                    token_symbol, chain, market_type, venue_name, venue_key, pair,
                    source_url, source_tier, evidence_type, status, dedupe_key,
                    source_policy, created_at
                ) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)
                """,
                (
                    "LAB",
                    "bsc",
                    "cex",
                    None,
                    None,
                    None,
                    "https://broken.example",
                    "tier_1",
                    "official_exchange_market_page",
                    "pending_admin_review",
                    "broken-dedupe-key",
                    "test broken candidate",
                    "2026-01-01T00:00:00Z",
                ),
            )
            conn.commit()
            before_counts = {
                "candidates": count_table(conn, "token_market_discovery_candidates"),
                "evidence": count_table(conn, "dex_router_official_evidence_queue"),
                "mappings": count_table(conn, "dex_venue_mappings"),
                "artifacts": count_table(conn, "dex_venue_mapping_rollback_artifacts"),
                "wallets": count_table(conn, "wallet_chain_state"),
                "swaps": count_table(conn, "swaps"),
            }
        finally:
            conn.close()

        queue_all = onchain_engine.get_token_market_discovery_candidate_review_queue(
            status="pending_admin_review",
            limit=50,
            dry_run=True,
        )
        queue_cex = onchain_engine.get_token_market_discovery_candidate_review_queue(
            status="pending_admin_review",
            token_symbol="LAB",
            market_type="cex",
            limit=2,
            dry_run=True,
        )
        queue_dex = onchain_engine.get_token_market_discovery_candidate_review_queue(
            status="pending_admin_review",
            market_type="dex",
            dry_run=True,
        )
        reject_write = onchain_engine.get_token_market_discovery_candidate_review_queue(dry_run=False)

        conn = sqlite3.connect(str(self.onchain_db))
        try:
            after_counts = {
                "candidates": count_table(conn, "token_market_discovery_candidates"),
                "evidence": count_table(conn, "dex_router_official_evidence_queue"),
                "mappings": count_table(conn, "dex_venue_mappings"),
                "artifacts": count_table(conn, "dex_venue_mapping_rollback_artifacts"),
                "wallets": count_table(conn, "wallet_chain_state"),
                "swaps": count_table(conn, "swaps"),
            }
        finally:
            conn.close()

        self.assertEqual(missing_table["queue_status"], "blocked")
        self.assertIn("token_market_discovery_candidates_missing", missing_table["blockers"])
        self.assertTrue(tier_1["inserted"])
        self.assertTrue(tier_3["inserted"])
        self.assertTrue(dex["inserted"])
        self.assertEqual(queue_all["queue_status"], "ready")
        self.assertEqual(queue_all["summary"]["total_candidates"], 4)
        self.assertEqual(queue_all["summary"]["ready_for_evidence_intake_preview"], 2)
        self.assertEqual(queue_all["summary"]["review_only_tier_3"], 1)
        self.assertEqual(queue_all["summary"]["blocked"], 1)
        self.assertEqual(queue_all["summary"]["cex_candidates"], 3)
        self.assertEqual(queue_all["summary"]["dex_candidates"], 1)
        readiness_by_id = {row["candidate_id"]: row["review_readiness"] for row in queue_all["rows"]}
        self.assertEqual(readiness_by_id[tier_1["candidate_id"]], "ready_for_evidence_intake_preview")
        self.assertEqual(readiness_by_id[tier_3["candidate_id"]], "review_only_tier_3")
        self.assertEqual(readiness_by_id[dex["candidate_id"]], "ready_for_evidence_intake_preview")
        blocked_row = next(row for row in queue_all["rows"] if row["review_readiness"] == "blocked")
        self.assertIn("cex_venue_name_required", blocked_row["review_blockers"])
        self.assertIn("dedupe_key_drift", blocked_row["review_blockers"])
        for row in queue_all["rows"]:
            self.assertFalse(row["would_create_evidence"])
            self.assertFalse(row["would_create_label"])
            self.assertFalse(row["would_create_mapping"])
            self.assertFalse(row["would_write"])
        self.assertEqual(queue_cex["filters"]["limit"], 2)
        self.assertEqual(len(queue_cex["rows"]), 2)
        self.assertTrue(all(row["market_type"] == "cex" for row in queue_cex["rows"]))
        self.assertEqual(queue_dex["summary"]["dex_candidates"], 1)
        self.assertEqual(queue_dex["rows"][0]["candidate_id"], dex["candidate_id"])
        self.assertEqual(reject_write["queue_status"], "blocked")
        self.assertIn("dry_run_required", reject_write["blockers"])
        self.assertFalse(queue_all["would_create_evidence"])
        self.assertFalse(queue_all["would_create_label"])
        self.assertFalse(queue_all["would_create_mapping"])
        self.assertFalse(queue_all["would_write"])
        self.assertFalse(queue_all["real_write_enabled"])
        self.assertEqual(queue_all["writes_performed"], 0)
        self.assertEqual(after_counts, before_counts)

