        self.assertFalse(ready_plan["would_create_table"])
        self.assertFalse(ready_plan["would_write"])
        self.assertFalse(ready_plan["real_write_enabled"])
        self.assertEqual(ready_plan["writes_performed"], 0)
        self.assertEqual(blocked_plan["plan_status"], "blocked")
        self.assertIn("candidate_preview_not_ready", blocked_plan["blockers"])
        self.assertEqual(missing_plan["plan_status"], "blocked")
        self.assertIn("candidate_missing", missing_plan["blockers"])
        self.assertEqual(reject_write["plan_status"], "blocked")
        self.assertIn("dry_run_required", reject_write["blockers"])
        self.assertIsNone(evidence_queue_table)
        self.assertEqual(after_counts, before_counts)

