        self.assertTrue(all(row["market_type"] == "cex" for row in queue_cex["rows"]))
        self.assertEqual(reject_write["queue_status"], "blocked")
        self.assertIn("dry_run_required", reject_write["blockers"])
        self.assertFalse(queue_all["would_create_label"])
        self.assertFalse(queue_all["would_create_mapping"])
        self.assertFalse(queue_all["would_promote_candidate"])
        self.assertFalse(queue_all["would_write"])
        self.assertFalse(queue_all["real_write_enabled"])
        self.assertEqual(queue_all["writes_performed"], 0)
        self.assertEqual(after_counts, before_counts)

