        conn = sqlite3.connect(str(self.onchain_db))
        try:
            before_counts = {
                "token_evidence": count_table(conn, "token_market_discovery_evidence_queue"),
                "candidates": count_table(conn, "token_market_discovery_candidates"),
                "dex_evidence": count_table(conn, "dex_router_official_evidence_queue"),
                "mappings": count_table(conn, "dex_venue_mappings"),
                "artifacts": count_table(conn, "dex_venue_mapping_rollback_artifacts"),
                "wallets": count_table(conn, "wallet_chain_state"),
                "swaps": count_table(conn, "swaps"),
            }
        finally:
            conn.close()

        cex_preview = onchain_engine.get_token_market_discovery_evidence_controlled_promotion_preview(
            evidence_id=cex_id,
            dry_run=True,
        )
        dex_preview = onchain_engine.get_token_market_discovery_evidence_controlled_promotion_preview(
            evidence_id=dex_id,
            dry_run=True,
        )
        hybrid_preview = onchain_engine.get_token_market_discovery_evidence_controlled_promotion_preview(
            evidence_id=hybrid_id,
            dry_run=True,
        )
        pending_preview = onchain_engine.get_token_market_discovery_evidence_controlled_promotion_preview(
            evidence_id=pending_id,
            dry_run=True,
        )
        missing_preview = onchain_engine.get_token_market_discovery_evidence_controlled_promotion_preview(
            evidence_id=999,
            dry_run=True,
        )
        reject_write = onchain_engine.get_token_market_discovery_evidence_controlled_promotion_preview(
            evidence_id=cex_id,
            dry_run=False,
        )

        conn = sqlite3.connect(str(self.onchain_db))
        try:
            after_counts = {
                "token_evidence": count_table(conn, "token_market_discovery_evidence_queue"),
                "candidates": count_table(conn, "token_market_discovery_candidates"),
                "dex_evidence": count_table(conn, "dex_router_official_evidence_queue"),
                "mappings": count_table(conn, "dex_venue_mappings"),
                "artifacts": count_table(conn, "dex_venue_mapping_rollback_artifacts"),
                "wallets": count_table(conn, "wallet_chain_state"),
                "swaps": count_table(conn, "swaps"),
            }
        finally:
            conn.close()

        self.assertEqual(cex_preview["preview_status"], "ready_but_disabled")
        self.assertEqual(cex_preview["promotion_target"], "cex_market_evidence_flow")
        self.assertEqual(dex_preview["promotion_target"], "dex_router_official_evidence_flow")
        self.assertEqual(hybrid_preview["promotion_target"], "manual_classification_review")
        self.assertIn("future_confirm_required_before_any_promotion_insert", cex_preview["required_gates"])
        self.assertFalse(cex_preview["would_create_cex_label"])
        self.assertFalse(cex_preview["would_create_dex_router_evidence"])
        self.assertFalse(cex_preview["would_create_mapping"])
        self.assertFalse(cex_preview["would_promote_candidate"])
        self.assertFalse(cex_preview["would_write"])
        self.assertFalse(cex_preview["real_write_enabled"])
        self.assertEqual(cex_preview["writes_performed"], 0)
        self.assertEqual(pending_preview["preview_status"], "blocked")
        self.assertIn("evidence_not_accepted_for_promotion", pending_preview["blockers"])
        self.assertIn("evidence_missing", missing_preview["blockers"])
        self.assertIn("dry_run_required", reject_write["blockers"])
        self.assertEqual(after_counts, before_counts)

