        self.assertEqual(created["rows_inserted"], 0)
        self.assertGreater(created["writes_performed"], 0)
        self.assertEqual(second["create_status"], "already_exists")
        self.assertFalse(second["table_created"])
        self.assertEqual(second["rows_inserted"], 0)
        self.assertEqual(second["writes_performed"], 0)
        self.assertEqual(after_counts["downstream_queue"], 0)
        self.assertIn("token_market_downstream_promotion_queue_dedupe_uq", indexes)
        self.assertIn("token_market_downstream_promotion_queue_chain_venue_idx", indexes)
        self.assertEqual(
            {key: value for key, value in after_counts.items() if key != "downstream_queue"},
            {key: value for key, value in before_counts.items() if key != "downstream_queue"},
        )

