        self.assertEqual(row[0], "cex_market_evidence_review_queue")
        self.assertEqual(row[1], downstream_contract["dedupe_key"])
        self.assertEqual(row[3], "pending_admin_review")
        self.assertIn("payload_preview", json.loads(row[2]))
        self.assertEqual(after_counts["downstream_queue"], before_counts["downstream_queue"] + 1)
        self.assertEqual(
            {key: value for key, value in after_counts.items() if key != "downstream_queue"},
            {key: value for key, value in before_counts.items() if key != "downstream_queue"},
        )

