        try:
            before_counts = {
                "business_handoff": count_table(conn, "token_market_downstream_business_handoff_queue"),
                "downstream_queue": count_table(conn, "token_market_downstream_promotion_queue"),
                "token_evidence": count_table(conn, "token_market_discovery_evidence_queue"),
                "candidates": count_table(conn, "token_market_discovery_candidates"),
                "promotion_queue": count_table(conn, "token_market_controlled_promotion_queue"),
                "dex_evidence": count_table(conn, "dex_router_official_evidence_queue"),
                "mappings": count_table(conn, "dex_venue_mappings"),
                "artifacts": count_table(conn, "dex_venue_mapping_rollback_artifacts"),
                "wallets": count_table(conn, "wallet_chain_state"),
                "swaps": count_table(conn, "swaps"),
            }
        finally:
            conn.close()

        dry_run = onchain_engine.insert_token_market_downstream_business_handoff(
            downstream_id=downstream_id,
            expected_business_dedupe_key=contract["business_dedupe_key"],
            dry_run=True,
        )
        mismatch = onchain_engine.insert_token_market_downstream_business_handoff(
            downstream_id=downstream_id,
            expected_business_dedupe_key="wrong",
            dry_run=True,
        )
        no_confirm = onchain_engine.insert_token_market_downstream_business_handoff(
            downstream_id=downstream_id,
            expected_business_dedupe_key=contract["business_dedupe_key"],
            dry_run=False,
        )
        inserted = onchain_engine.insert_token_market_downstream_business_handoff(
            downstream_id=downstream_id,
            expected_business_dedupe_key=contract["business_dedupe_key"],
            dry_run=False,
            confirm="INSERT_TOKEN_MARKET_DOWNSTREAM_BUSINESS_HANDOFF",
        )
        duplicate = onchain_engine.insert_token_market_downstream_business_handoff(
            downstream_id=downstream_id,
            expected_business_dedupe_key=contract["business_dedupe_key"],
            dry_run=False,
            confirm="INSERT_TOKEN_MARKET_DOWNSTREAM_BUSINESS_HANDOFF",
        )

        conn = sqlite3.connect(str(self.onchain_db))
        try:
            after_counts = {
                "business_handoff": count_table(conn, "token_market_downstream_business_handoff_queue"),
                "downstream_queue": count_table(conn, "token_market_downstream_promotion_queue"),
                "token_evidence": count_table(conn, "token_market_discovery_evidence_queue"),
                "candidates": count_table(conn, "token_market_discovery_candidates"),
                "promotion_queue": count_table(conn, "token_market_controlled_promotion_queue"),
                "dex_evidence": count_table(conn, "dex_router_official_evidence_queue"),
                "mappings": count_table(conn, "dex_venue_mappings"),
                "artifacts": count_table(conn, "dex_venue_mapping_rollback_artifacts"),
                "wallets": count_table(conn, "wallet_chain_state"),
                "swaps": count_table(conn, "swaps"),
            }
            row = conn.execute(
                """
                SELECT business_dedupe_key, business_target, status, insert_contract_json
                FROM token_market_downstream_business_handoff_queue
                WHERE id = ?
                """,
                (inserted["business_handoff_id"],),
            ).fetchone()
        finally:
            conn.close()

        self.assertIn("token_market_downstream_business_handoff_queue_missing", table_missing["blockers"])
        self.assertEqual(dry_run["insert_status"], "ready_but_disabled")
        self.assertTrue(dry_run["would_insert"])
        self.assertFalse(dry_run["inserted"])
        self.assertEqual(dry_run["writes_performed"], 0)
        self.assertFalse(dry_run["would_create_cex_label"])
        self.assertFalse(dry_run["would_create_dex_router_evidence"])
        self.assertFalse(dry_run["would_create_mapping"])
        self.assertFalse(dry_run["would_execute_trade"])
        self.assertFalse(dry_run["would_create_client_opt_in"])
        self.assertIn("expected_business_dedupe_key_mismatch", mismatch["blockers"])
        self.assertIn("confirm_INSERT_TOKEN_MARKET_DOWNSTREAM_BUSINESS_HANDOFF_required", no_confirm["blockers"])
        self.assertEqual(inserted["insert_status"], "inserted")
        self.assertTrue(inserted["inserted"])
        self.assertEqual(inserted["writes_performed"], 1)
        self.assertFalse(inserted["would_create_client_opt_in"])
        self.assertEqual(duplicate["insert_status"], "blocked")
        self.assertIn("duplicate_business_dedupe_key", duplicate["blockers"])
        self.assertEqual(after_counts["business_handoff"], before_counts["business_handoff"] + 1)
        self.assertEqual(
            {key: value for key, value in after_counts.items() if key != "business_handoff"},
            {key: value for key, value in before_counts.items() if key != "business_handoff"},
        )
        self.assertEqual(row[0], contract["business_dedupe_key"])
        self.assertEqual(row[1], "cex_market_evidence_review_queue")
        self.assertEqual(row[2], "pending_admin_review")
        self.assertEqual(json.loads(row[3])["insert_kind"], "cex_market_evidence_handoff_not_direct_label_write")

