    def test_refresh_dex_router_venue_mapping_rollback_artifact_after_digest_drift(self) -> None:
        wallet = "0x" + "1" * 40
        router = "0x" + "f" * 40
        stale_digest = "0" * 64
        conn = sqlite3.connect(str(self.onchain_db))
        try:
            conn.execute(
                """
                INSERT INTO swaps (
                    tx_hash, chain, block_number, timestamp, wallet, dex,
                    token_in, token_out, amount_in, amount_out, amount_usd, pool,
                    router_addr, venue_source, venue_confidence, token_identity_quality
                ) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)
                """,
                (
                    "0x" + "c" * 64,
                    "eth",
                    1_032,
                    1_778_601_112,
                    wallet,
                    "Unknown DEX",
                    "0x" + "d" * 40,
                    "0x" + "e" * 40,
                    1.0,
                    2.0,
                    10.0,
                    "0x" + "f" * 40,
                    router,
                    "swap_pool_event_unattributed",
                    0.35,
                    "exact_pair_log_direction",
                ),
            )
            conn.execute(
                """
                INSERT INTO wallet_chain_state (
                    chain, address, native_balance, tx_count, token_balances_json,
                    rpc_source, label, entity, confidence, address_kind, is_contract,
                    native_value_usd, activity_tier, risk_flags_json, data_quality_score,
                    label_sources_json, source_attribution_json, observed_at
                ) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)
                """,
                (
                    "eth",
                    router,
                    0.0,
                    12,
                    "[]",
                    "test_rpc",
                    "",
                    "",
                    "low",
                    "contract",
                    1,
                    0.0,
                    "contract",
                    json.dumps(["router_like_contract"]),
                    72,
                    "[]",
                    json.dumps({"rpc": "test_rpc", "source": "unit"}),
                    1_778_601_112,
                ),
            )
            conn.commit()
            wallet_rows_seeded = conn.execute("SELECT COUNT(*) FROM wallet_chain_state").fetchone()[0]
            swap_rows_seeded = conn.execute("SELECT COUNT(*) FROM swaps").fetchone()[0]
            mapping_rows_seeded = conn.execute("SELECT COUNT(*) FROM dex_venue_mappings").fetchone()[0]
        finally:
            conn.close()

        onchain_engine.create_dex_router_official_evidence_queue(
            dry_run=False,
            confirm="CREATE_DEX_ROUTER_OFFICIAL_EVIDENCE_QUEUE",
        )
        inserted = onchain_engine.insert_dex_router_official_evidence(
            "eth",
            router,
            "official_protocol_docs",
            "https://docs.example.org/contracts",
            "official docs mention exact router",
            False,
            "INSERT_DEX_ROUTER_OFFICIAL_EVIDENCE",
        )
        onchain_engine.create_dex_router_venue_mapping_rollback_artifact_storage(
            dry_run=False,
            confirm="CREATE_DEX_VENUE_MAPPING_ROLLBACK_ARTIFACT_STORAGE",
        )
        created = onchain_engine.create_dex_router_venue_mapping_rollback_artifact(
            inserted["row_id"],
            "ExampleSwap",
            False,
            "CREATE_DEX_VENUE_MAPPING_ROLLBACK_ARTIFACT",
        )
        current_digest = created["plan_digest"]
        conn = sqlite3.connect(str(self.onchain_db))
        try:
            conn.execute(
                "UPDATE dex_venue_mapping_rollback_artifacts SET plan_digest = ? WHERE id = ?",
                (stale_digest, created["artifact_id"]),
            )
            conn.commit()
        finally:
            conn.close()
        backup_files_before = list(Path(self.tmp.name).rglob("*"))

        stale_gate = onchain_engine.get_dex_router_venue_mapping_rollback_artifacts(
            inserted["row_id"],
            "ExampleSwap",
            20,
        )
        self.assertFalse(stale_gate["valid_artifact_available"])
        self.assertIn("plan_digest_drift_or_mismatch", stale_gate["missing_proofs"])

        dry_run = onchain_engine.refresh_dex_router_venue_mapping_rollback_artifact(
            inserted["row_id"],
            "ExampleSwap",
            True,
        )
        self.assertTrue(dry_run["ok"])
        self.assertEqual(dry_run["refresh_status"], "ready_but_disabled")
        self.assertTrue(dry_run["stale_detected"])
        self.assertEqual(dry_run["old_artifact_id"], created["artifact_id"])
        self.assertEqual(dry_run["old_plan_digest"], stale_digest)
        self.assertEqual(dry_run["new_plan_digest"], current_digest)
        self.assertTrue(dry_run["would_create_new_artifact"])
        self.assertFalse(dry_run["would_create_file"])
        self.assertFalse(dry_run["would_create_venue_mapping"])
        self.assertFalse(dry_run["would_write"])
        self.assertEqual(dry_run["writes_performed"], 0)

        blocked = onchain_engine.refresh_dex_router_venue_mapping_rollback_artifact(
            inserted["row_id"],
            "ExampleSwap",
            False,
        )
        self.assertFalse(blocked["ok"])
        self.assertIn("confirm_REFRESH_DEX_VENUE_MAPPING_ROLLBACK_ARTIFACT_required", blocked["blockers"])

        refreshed = onchain_engine.refresh_dex_router_venue_mapping_rollback_artifact(
            inserted["row_id"],
            "ExampleSwap",
            False,
            "REFRESH_DEX_VENUE_MAPPING_ROLLBACK_ARTIFACT",
        )
        self.assertTrue(refreshed["ok"])
        self.assertEqual(refreshed["refresh_status"], "refreshed")
        self.assertTrue(refreshed["artifact_created"])
        self.assertNotEqual(refreshed["new_artifact_id"], created["artifact_id"])
        self.assertEqual(refreshed["new_plan_digest"], current_digest)
        self.assertEqual(refreshed["writes_performed"], 1)
        self.assertFalse(refreshed["would_create_file"])
        self.assertFalse(refreshed["would_create_venue_mapping"])

        duplicate = onchain_engine.refresh_dex_router_venue_mapping_rollback_artifact(
            inserted["row_id"],
            "ExampleSwap",
            False,
            "REFRESH_DEX_VENUE_MAPPING_ROLLBACK_ARTIFACT",
        )
        self.assertFalse(duplicate["ok"])
        self.assertIn("duplicate_current_plan_digest", duplicate["blockers"])
        self.assertEqual(duplicate["writes_performed"], 0)

        verified = onchain_engine.get_dex_router_venue_mapping_rollback_artifacts(
            inserted["row_id"],
            "ExampleSwap",
            20,
        )
        self.assertTrue(verified["valid_artifact_available"])
        self.assertEqual(verified["latest_artifact"]["artifact_id"], refreshed["new_artifact_id"])
        self.assertEqual(verified["latest_artifact"]["plan_digest"], current_digest)

        conn = sqlite3.connect(str(self.onchain_db))
        try:
            rows = conn.execute(
                """
                SELECT id, plan_digest, status
                FROM dex_venue_mapping_rollback_artifacts
                ORDER BY id ASC
                """
            ).fetchall()
            evidence_rows = conn.execute("SELECT COUNT(*) FROM dex_router_official_evidence_queue").fetchone()[0]
            wallet_rows_after = conn.execute("SELECT COUNT(*) FROM wallet_chain_state").fetchone()[0]
            swap_rows_after = conn.execute("SELECT COUNT(*) FROM swaps").fetchone()[0]
            mapping_rows_after = conn.execute("SELECT COUNT(*) FROM dex_venue_mappings").fetchone()[0]
        finally:
            conn.close()
        backup_files_after = list(Path(self.tmp.name).rglob("*"))

        self.assertEqual(len(rows), 2)
        self.assertEqual(rows[0], (created["artifact_id"], stale_digest, "created"))
        self.assertEqual(rows[1], (refreshed["new_artifact_id"], current_digest, "created"))
        self.assertEqual(evidence_rows, 1)
        self.assertEqual(wallet_rows_after, wallet_rows_seeded)
        self.assertEqual(swap_rows_after, swap_rows_seeded)
        self.assertEqual(mapping_rows_after, mapping_rows_seeded)
        self.assertEqual(len(backup_files_after), len(backup_files_before))

