    def test_token_market_source_venue_evidence_marks_partial_source_backed_routes(self) -> None:
        token = "0x" + "1" * 40
        mapped_router = "0x" + "2" * 40
        unknown_router = "0x" + "3" * 40
        pool = "0x" + "4" * 40
        wbnb = "0xbb4cdb9cbd36b01bd1cbaebf2de08d9173bc095c"
        fake_repair = {
            "ok": True,
            "summary": {"repair_rows": 1},
            "rows": [
                {
                    "repair_rank": 1,
                    "lead_id": 1,
                    "token_symbol": "PARTIAL",
                    "chain": "bsc",
                    "token_address": token,
                    "proposed_route": "dex",
                    "repair_priority": 90,
                    "local_evidence": {"distinct_pools": 1},
                    "missing_to_be_source_backed": ["source_url_required"],
                }
            ],
        }
        conn = sqlite3.connect(str(self.onchain_db))
        try:
            conn.execute(
                """
                INSERT INTO dex_venue_mappings (
                    chain, router_addr, venue, source_url, evidence_json,
                    confidence, status, created_at, updated_at, created_by
                ) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?)
                """,
                (
                    "bsc",
                    mapped_router,
                    "Example DEX",
                    "https://docs.example.org/router",
                    "{}",
                    0.95,
                    "active",
                    1_778_100_000,
                    1_778_100_000,
                    "unit_test",
                ),
            )
            for idx, (router, dex, venue_source) in enumerate(
                [
                    (mapped_router, "Example DEX", "source_backed_router_mapping"),
                    (unknown_router, "Unknown DEX", "swap_pool_event_unattributed"),
                ],
                start=1,
            ):
                conn.execute(
                    """
                    INSERT INTO swaps (
                        tx_hash, chain, block_number, timestamp, wallet, dex, token_in, token_out,
                        amount_in, amount_out, amount_usd, pool, token_identity_quality,
                        pair_rpc_source, router_addr, venue_source, venue_confidence
                    ) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)
                    """,
                    (
                        "0x" + str(idx) * 64,
                        "bsc",
                        123 + idx,
                        1_778_100_000 + idx,
                        "0x" + "5" * 40,
                        dex,
                        token,
                        wbnb,
                        1.0,
                        2.0,
                        0.0,
                        pool,
                        "exact_pair_tokens",
                        "test_pair_rpc",
                        router,
                        venue_source,
                        0.95 if router == mapped_router else 0.35,
                    ),
                )
            conn.commit()
        finally:
            conn.close()

        with patch("services.onchain_engine.get_token_market_local_candidate_source_repair_plan", return_value=fake_repair):
            report = onchain_engine.get_token_market_local_candidate_source_venue_evidence(limit=5, dry_run=True)

        row = report["rows"][0]
        self.assertTrue(row["source_backed_venue_ready"])
        self.assertEqual(row["route_truth_status"], "partial_source_backed_route_needs_unresolved_router_repair")
        self.assertEqual(row["candidate_readiness_status"], "route_identity_needs_repair")
        self.assertEqual(report["summary"]["route_source_ready_rows"], 0)
        self.assertEqual(report["summary"]["partial_route_rows"], 1)
        self.assertEqual(report["candidate_batch_readiness"]["status"], "insufficient_route_ready_candidates_for_batch")
        self.assertIn("PARTIAL", report["candidate_batch_readiness"]["partial_route_tokens"])
        self.assertEqual(row["router_source_summary"]["source_backed_router_count"], 1)
        self.assertEqual(row["router_source_summary"]["unresolved_router_count"], 1)
        self.assertTrue(row["router_source_summary"]["unknown_venue_present"])
        self.assertEqual(report["summary"]["unresolved_router_priority_rows"], 1)
        self.assertEqual(report["unresolved_router_priority"][0]["router_addr"], unknown_router)
        self.assertEqual(report["unresolved_router_priority"][0]["total_local_swap_rows"], 1)
        self.assertFalse(row["would_create_mapping"])
        self.assertFalse(row["would_write"])

