    def test_token_market_local_universe_audit_is_read_only_and_explains_data_gap(self) -> None:
        labels_before = label_ledger.get_label_ledger_summary()["labels"]
        candidates_before = label_ledger.get_label_ledger_summary()["label_candidates"]
        jobs_before = onchain_engine.get_data_jobs(limit=100)
        token = "0x" + "7" * 40
        wbnb = "0xbb4cdb9cbd36b01bd1cbaebf2de08d9173bc095c"
        pool = "0x" + "8" * 40
        router = "0x10ed43c718714eb63d5aa57b78b54704e256024e"
        conn = sqlite3.connect(str(self.onchain_db))
        try:
            conn.execute(
                """
                INSERT INTO token_metadata (
                    chain, token_address, symbol, name, decimals, rpc_source, observed_at, status
                ) VALUES (?, ?, ?, ?, ?, ?, ?, ?)
                """,
                ("bsc", token, "BUN", "Bun Token", 18, "test_rpc", 1_778_100_000, "resolved"),
            )
            conn.execute(
                """
                INSERT INTO pair_tokens (chain, pool, token0, token1, rpc_source, observed_at)
                VALUES (?, ?, ?, ?, ?, ?)
                """,
                ("bsc", pool, token, wbnb, "test_pair_rpc", 1_778_100_000),
            )
            conn.execute(
                """
                INSERT INTO swaps (
                    tx_hash, chain, block_number, timestamp, wallet, dex, token_in, token_out,
                    amount_in, amount_out, amount_usd, pool, token_identity_quality,
                    pair_rpc_source, router_addr, venue_source, venue_confidence
                ) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)
                """,
                (
                    "0x" + "a" * 64,
                    "bsc",
                    123,
                    1_778_100_000,
                    "0x" + "b" * 40,
                    "PancakeSwap V2",
                    token,
                    wbnb,
                    1.0,
                    2.0,
                    0.0,
                    pool,
                    "exact_pair_tokens",
                    "test_pair_rpc",
                    router,
                    "known_router_address",
                    0.9,
                ),
            )
            conn.commit()
        finally:
            conn.close()

        report = onchain_engine.get_token_market_local_universe_audit(limit=10, dry_run=True)

        self.assertTrue(report["ok"])
        self.assertTrue(report["dry_run"])
        self.assertFalse(report["usable_for_manipulation"])
        self.assertEqual(report["summary"]["local_tokens_observed"], 2)
        self.assertEqual(report["summary"]["source_backed_candidates"], 0)
        self.assertIn("swap_surface_too_small", report["blockers"])
        self.assertIn("source_backed_candidates_missing", report["blockers"])
        self.assertTrue(report["why_collect_more_data"])
        row = next(item for item in report["rows"] if item["token_address"] == token)
        self.assertEqual(row["token_symbol"], "BUN")
        self.assertEqual(row["exact_swap_rows"], 1)
        self.assertFalse(row["would_insert_candidate"])
        self.assertFalse(report["would_collect_data"])
        self.assertFalse(report["would_create_cex_label"])
        self.assertFalse(report["would_create_mapping"])
        self.assertFalse(report["would_create_client_signal"])
        self.assertFalse(report["would_write"])
        blocked = onchain_engine.get_token_market_local_universe_audit(dry_run=False)
        self.assertFalse(blocked["ok"])
        self.assertIn("dry_run_required", blocked["blockers"])
        self.assertEqual(label_ledger.get_label_ledger_summary()["labels"], labels_before)
        self.assertEqual(label_ledger.get_label_ledger_summary()["label_candidates"], candidates_before)
        self.assertEqual(onchain_engine.get_data_jobs(limit=100), jobs_before)

