        after_counts = {"blocks": 11, "transactions": 103, "swaps": 21, "token_transfers": 44, "pair_tokens": 6, "data_jobs": 8}
        label_counts = {"labels": 0, "derived_labels": 0, "label_candidates": 0, "open_label_candidates": 0}
