        self.assertEqual(confirmed["trace_rows"][0]["top_internal_counterparties"][0]["address"], pool)
        self.assertFalse(confirmed["would_create_dex_router_evidence"])
        self.assertFalse(confirmed["would_create_mapping"])
        self.assertFalse(confirmed["would_create_client_signal"])
        self.assertFalse(confirmed["would_write"])
        self.assertEqual(confirmed["disallowed_table_deltas"], {})
        mock_ingest.assert_called_once()
        mock_rpc.assert_called_once()
        finish_job.assert_called_once()
        self.assertEqual(label_ledger.get_label_ledger_summary()["labels"], labels_before)
        self.assertEqual(label_ledger.get_label_ledger_summary()["label_candidates"], candidates_before)
