        self.assertEqual(report["plan_status"], "ready_read_only")
        self.assertEqual(report["summary"]["path_rows_reviewed"], 1)
        self.assertGreaterEqual(report["summary"]["source_targets"], 2)
        row = report["rows"][0]
        self.assertEqual(row["source_repair_status"], "needs_exact_official_source_repair")
        self.assertEqual(row["confidence"], "source_repair_priority_only")
        self.assertEqual(row["source_targets"][0]["target_kind"], "router_or_intermediary")
        self.assertIn(router, " ".join(row["source_targets"][0]["source_search_queries"]))
        self.assertTrue(any(target["target_kind"] == "pair_pool" for target in row["source_targets"]))
        self.assertIn("exact_official_source_required", row["blockers"])
        self.assertFalse(row["safe_for_mapping_now"])
        self.assertFalse(row["would_create_venue_mapping"])
        self.assertFalse(report["would_call_external"])
        self.assertFalse(report["would_write"])
        self.assertEqual(report["writes_performed"], 0)

        blocked = onchain_engine.get_unknown_dex_local_path_official_source_repair_plan(dry_run=False)
        self.assertFalse(blocked["ok"])
        self.assertIn("dry_run_required", blocked["blockers"])
