        self.assertEqual(row["get_pair_current_state_providers"], 2)
        self.assertEqual(row["paircreated_historical_event_providers"], 1)
        self.assertEqual(row["provider_attempts"][0]["paircreated_log_status"], "provider_limited")
        self.assertEqual(row["provider_attempts"][1]["paircreated_log_status"], "match_found")
        self.assertTrue(row["provider_attempts"][1]["historical_event_proof_ready"])
        self.assertEqual(row["provider_attempts"][1]["parsed_logs_preview"][0]["emitted_pair_address"], pool)
        self.assertFalse(row["would_persist_paircreated_evidence"])
        self.assertFalse(row["would_create_mapping"])
