    def test_create_unknown_dex_paircreated_evidence_is_confirmed_ddl_only(self) -> None:
        labels_before = label_ledger.get_label_ledger_summary()["labels"]
        candidates_before = label_ledger.get_label_ledger_summary()["label_candidates"]
        jobs_before = onchain_engine.get_data_jobs(limit=100)

        dry_run = onchain_engine.create_unknown_dex_paircreated_evidence(dry_run=True)
        self.assertTrue(dry_run["ok"])
        self.assertEqual(dry_run["create_status"], "ready_but_disabled")
        self.assertEqual(dry_run["target_table"], "dex_paircreated_evidence")
        self.assertTrue(dry_run["would_create_table"])
        self.assertFalse(dry_run["table_created"])
        self.assertFalse(dry_run["would_persist_paircreated_evidence"])
        self.assertFalse(dry_run["would_create_mapping"])
        self.assertFalse(dry_run["would_write"])
        self.assertEqual(dry_run["writes_performed"], 0)

        missing_confirm = onchain_engine.create_unknown_dex_paircreated_evidence(dry_run=False)
        self.assertFalse(missing_confirm["ok"])
        self.assertEqual(missing_confirm["create_status"], "blocked")
        self.assertIn("confirm_CREATE_DEX_PAIRCREATED_EVIDENCE_required", missing_confirm["blockers"])

        created = onchain_engine.create_unknown_dex_paircreated_evidence(
            dry_run=False,
            confirm="CREATE_DEX_PAIRCREATED_EVIDENCE",
        )
        self.assertTrue(created["ok"])
        self.assertEqual(created["create_status"], "created")
        self.assertTrue(created["table_exists"])
        self.assertTrue(created["table_created"])
        self.assertEqual(created["row_count"], 0)
        self.assertEqual(created["rows_inserted"], 0)
        self.assertGreaterEqual(len(created["indexes_created"]), 8)
        self.assertFalse(created["would_persist_paircreated_evidence"])
        self.assertFalse(created["would_create_mapping"])
        self.assertFalse(created["would_create_dex_router_evidence"])
        self.assertFalse(created["would_create_cex_label"])
        self.assertFalse(created["would_execute_trade"])
        self.assertFalse(created["would_create_client_signal"])
        self.assertFalse(created["would_create_client_opt_in"])

        second = onchain_engine.create_unknown_dex_paircreated_evidence(
            dry_run=False,
            confirm="CREATE_DEX_PAIRCREATED_EVIDENCE",
        )
        self.assertTrue(second["ok"])
        self.assertEqual(second["create_status"], "already_exists")
        self.assertFalse(second["table_created"])
        self.assertEqual(second["row_count"], 0)
        self.assertEqual(second["indexes_created"], [])

        conn = sqlite3.connect(str(self.onchain_db))
        try:
            columns = {row[1] for row in conn.execute("PRAGMA table_info(dex_paircreated_evidence)").fetchall()}
            index_names = {
                row[1] for row in conn.execute("PRAGMA index_list(dex_paircreated_evidence)").fetchall()
            }
            row_count = conn.execute("SELECT COUNT(*) FROM dex_paircreated_evidence").fetchone()[0]
        finally:
            conn.close()
        self.assertIn("paircreated_dedupe_key", columns)
        self.assertIn("raw_payload_json", columns)
        self.assertIn("idx_dex_paircreated_evidence_dedupe", index_names)
        self.assertEqual(row_count, 0)
        self.assertEqual(label_ledger.get_label_ledger_summary()["labels"], labels_before)
        self.assertEqual(label_ledger.get_label_ledger_summary()["label_candidates"], candidates_before)
        self.assertEqual(onchain_engine.get_data_jobs(limit=100), jobs_before)

