        eligible_row = {
            "chain": "bsc",
            "eligible_for_future_evidence_persistence": True,
            "source_type": "sqd_portal_stream_api",
            "source_label": "sqd_portal",
            "source_url": "https://portal.sqd.dev/datasets/binance-mainnet/stream",
            "source_tier": "tier_2_indexer_corroboration",
            "official_venue": "PancakeSwap V2",
            "factory_address": factory,
            "pair_address": pool,
            "token0": "0x55d398326f99059ff775485246999027b3197955",
            "token0_symbol": "USDT",
            "token1": "0x" + "7" * 40,
            "token1_symbol": "TST",
            "tx_hash": tx_hash,
            "log_index": 2,
            "block_number": 34499500,
            "block_hash": "0x" + "3" * 64,
            "event_timestamp": 1700000000,
            "paircreated_event_topic": onchain_engine.PAIR_CREATED_TOPIC,
            "paircreated_dedupe_key": dedupe_key,
            "evidence_payload_digest": "a" * 64,
            "future_status": "pending_admin_review",
            "raw_payload_preview_not_persisted": {"source": "sqd", "tx_hash": tx_hash, "pair": pool},
            "would_persist_paircreated_evidence": False,
            "would_create_mapping": False,
        }
        fake_plan = {
            "ok": True,
            "dry_run": True,
            "plan_status": "ready_read_only",
            "target_table": "dex_paircreated_evidence",
            "table_exists": True,
            "migration_required": False,
            "eligible_rows": [eligible_row],
            "blocked_rows": [],
            "summary": {"eligible_paircreated_evidence_rows": 1, "blocked_research_only_rows": 0},
            "would_persist_paircreated_evidence": False,
            "would_create_mapping": False,
            "would_write": False,
            "writes_performed": 0,
        }

        table_missing = onchain_engine.insert_unknown_dex_paircreated_evidence(
            expected_paircreated_dedupe_key=dedupe_key,
            dry_run=True,
        )
        onchain_engine.create_unknown_dex_paircreated_evidence(
            dry_run=False,
            confirm="CREATE_DEX_PAIRCREATED_EVIDENCE",
        )

        with patch(
            "services.onchain_engine.get_unknown_dex_paircreated_evidence_persistence_schema_plan",
            return_value=fake_plan,
        ):
            mismatch = onchain_engine.insert_unknown_dex_paircreated_evidence(
                expected_paircreated_dedupe_key="bad-key",
                dry_run=True,
            )
            dry_run = onchain_engine.insert_unknown_dex_paircreated_evidence(
                expected_paircreated_dedupe_key=dedupe_key,
                dry_run=True,
            )
            no_confirm = onchain_engine.insert_unknown_dex_paircreated_evidence(
                expected_paircreated_dedupe_key=dedupe_key,
                dry_run=False,
            )
            inserted = onchain_engine.insert_unknown_dex_paircreated_evidence(
                expected_paircreated_dedupe_key=dedupe_key,
                dry_run=False,
                confirm="INSERT_DEX_PAIRCREATED_EVIDENCE",
            )
            duplicate = onchain_engine.insert_unknown_dex_paircreated_evidence(
                expected_paircreated_dedupe_key=dedupe_key,
                dry_run=True,
            )

        conn = sqlite3.connect(str(self.onchain_db))
        try:
            def count_optional_table(table_name: str) -> int:
                exists = conn.execute(
                    "SELECT 1 FROM sqlite_master WHERE type='table' AND name=? LIMIT 1",
                    (table_name,),
                ).fetchone()
                return int(conn.execute(f"SELECT COUNT(*) FROM {table_name}").fetchone()[0]) if exists else 0

            row_count = conn.execute("SELECT COUNT(*) FROM dex_paircreated_evidence").fetchone()[0]
            row = conn.execute(
                """
                SELECT pair_address, factory_address, tx_hash, log_index, paircreated_dedupe_key,
                       status, raw_payload_json
                FROM dex_paircreated_evidence
                """
            ).fetchone()
            mappings = count_optional_table("dex_venue_mappings")
            router_evidence = count_optional_table("dex_router_official_evidence_queue")
        finally:
            conn.close()

        self.assertIn("dex_paircreated_evidence_table_missing", table_missing["blockers"])
        self.assertEqual(mismatch["insert_status"], "blocked")
        self.assertIn("expected_paircreated_dedupe_key_mismatch", mismatch["blockers"])
        self.assertEqual(dry_run["insert_status"], "ready_for_insert")
        self.assertTrue(dry_run["would_insert"])
        self.assertFalse(dry_run["inserted"])
        self.assertEqual(dry_run["writes_performed"], 0)
        self.assertIn("confirm_INSERT_DEX_PAIRCREATED_EVIDENCE_required", no_confirm["blockers"])
        self.assertTrue(inserted["inserted"])
        self.assertTrue(inserted["persisted_paircreated_evidence"])
        self.assertEqual(inserted["writes_performed"], 1)
        self.assertFalse(inserted["would_create_mapping"])
        self.assertFalse(inserted["would_create_dex_router_evidence"])
        self.assertFalse(inserted["would_create_cex_label"])
        self.assertFalse(inserted["would_execute_trade"])
        self.assertFalse(inserted["would_create_client_signal"])
        self.assertFalse(inserted["would_create_client_opt_in"])
        self.assertEqual(duplicate["insert_status"], "blocked")
        self.assertEqual(duplicate["dedupe_status"], "duplicate")
        self.assertIn("duplicate_paircreated_evidence", duplicate["blockers"])
        self.assertEqual(row_count, 1)
        self.assertEqual(row[:6], (pool, factory, tx_hash, 2, dedupe_key, "pending_admin_review"))
        self.assertEqual(json.loads(row[6])["pair"], pool)
        self.assertEqual(mappings, 0)
        self.assertEqual(router_evidence, 0)
        self.assertEqual(label_ledger.get_label_ledger_summary()["labels"], labels_before)
        self.assertEqual(label_ledger.get_label_ledger_summary()["label_candidates"], candidates_before)
        self.assertEqual(onchain_engine.get_data_jobs(limit=100), jobs_before)

