        self.assertEqual(row["pair_address"], pool)
        self.assertEqual(row["factory_address"], factory)
        self.assertEqual(row["tx_hash"], tx_hash)
        self.assertEqual(row["log_index"], 2)
        self.assertEqual(row["status"], "pending_admin_review")
