        self.assertTrue(row["payload_json_valid"])
        self.assertTrue(row["payload_digest_bound"])
        self.assertTrue(row["official_factory_bound"])
        self.assertEqual(row["review_readiness"], "ready_for_paircreated_evidence_decision_preview")
        self.assertFalse(row["would_create_mapping"])
        self.assertFalse(row["would_create_dex_router_evidence"])
        self.assertFalse(row["would_execute_trade"])
        self.assertFalse(review["would_persist_paircreated_evidence"])
        self.assertFalse(review["would_create_mapping"])
        self.assertFalse(review["would_create_dex_router_evidence"])
        self.assertFalse(review["would_create_client_signal"])
        self.assertFalse(review["would_execute_trade"])
        self.assertFalse(review["would_write"])
        self.assertEqual(review["writes_performed"], 0)
        self.assertIn("dry_run_required", reject_write["blockers"])
        self.assertEqual(drift["rows"][0]["review_readiness"], "blocked")
        self.assertFalse(drift["rows"][0]["payload_digest_bound"])
        self.assertIn("evidence_payload_digest_not_bound", drift["rows"][0]["review_blockers"])
        self.assertEqual(label_ledger.get_label_ledger_summary()["labels"], labels_before)
        self.assertEqual(label_ledger.get_label_ledger_summary()["label_candidates"], candidates_before)
        self.assertEqual(onchain_engine.get_data_jobs(limit=100), jobs_before)

