        second_apply = onchain_engine.apply_unknown_dex_paircreated_evidence_decision(
            paircreated_evidence_id=inserted["paircreated_evidence_id"],
            proposed_decision="accept_for_future_paircreated_evidence",
            dry_run=False,
            confirm="APPLY_DEX_PAIRCREATED_EVIDENCE_DECISION",
        )

        conn = sqlite3.connect(str(self.onchain_db))
        try:
            status = conn.execute(
                "SELECT status FROM dex_paircreated_evidence WHERE id = ?",
                (inserted["paircreated_evidence_id"],),
            ).fetchone()[0]
            after_counts = {
                "paircreated": count_table(conn, "dex_paircreated_evidence"),
                "mappings": count_table(conn, "dex_venue_mappings"),
                "router_evidence": count_table(conn, "dex_router_official_evidence_queue"),
                "swaps": count_table(conn, "swaps"),
                "wallets": count_table(conn, "wallet_chain_state"),
            }
        finally:
            conn.close()

