        self.assertTrue(dry_run["would_update_paircreated_evidence_status"])
        self.assertFalse(dry_run["updated"])
        self.assertEqual(dry_run["writes_performed"], 0)
        self.assertIn("confirm_APPLY_DEX_PAIRCREATED_EVIDENCE_DECISION_required", no_confirm["blockers"])
        self.assertEqual(invalid["apply_status"], "blocked")
        self.assertIn("only_accept_for_future_paircreated_evidence_can_be_applied", invalid["blockers"])
        self.assertEqual(applied["apply_status"], "updated")
        self.assertEqual(applied["previous_status"], "pending_admin_review")
        self.assertEqual(applied["new_status"], "accepted_for_future_mapping_review")
        self.assertTrue(applied["updated"])
        self.assertEqual(applied["writes_performed"], 1)
        self.assertFalse(applied["would_persist_paircreated_evidence"])
        self.assertFalse(applied["would_create_mapping"])
        self.assertFalse(applied["would_create_dex_router_evidence"])
        self.assertFalse(applied["would_create_client_signal"])
        self.assertFalse(applied["would_execute_trade"])
        self.assertEqual(second_apply["apply_status"], "blocked")
        self.assertIn("paircreated_evidence_status_not_pending_admin_review", second_apply["blockers"])
        self.assertEqual(status, "accepted_for_future_mapping_review")
        self.assertEqual(after_counts, before_counts)
        self.assertEqual(label_ledger.get_label_ledger_summary()["labels"], labels_before)
        self.assertEqual(label_ledger.get_label_ledger_summary()["label_candidates"], candidates_before)
        self.assertEqual(onchain_engine.get_data_jobs(limit=100), jobs_before)

