    def test_core_equity_agent_os_lite_schedule_activation_checklist_uses_non_rpc_fallback(self) -> None:
        fake_snapshot = {
            "ok": True,
            "dry_run": True,
            "snapshot_status": "ready_read_only",
            "last_audit_receipt": {"clean": True, "data_job_id": 123},
            "schedule_state": {"can_schedule_eventually": True, "can_schedule_now": False},
            "readiness": {"trade_ready": False, "client_signal_ready": False},
            "blockers": [],
        }
        top_rpc_task = {
            "task_id": "unknown_dex_pool_factory_inference_checkpoint",
            "queue_readiness": "ready_for_manual_or_future_bounded_cycle",
            "requires_rpc_if_run_later": True,
            "requires_external_if_run_later": False,
            "would_run_now": False,
            "would_write": False,
        }
        fallback_task = {
            "task_id": "unknown_dex_family_context_candidate_repair_plan",
            "queue_readiness": "queued_read_only",
            "requires_rpc_if_run_later": False,
            "requires_external_if_run_later": False,
            "would_run_now": False,
            "would_write": False,
        }
        fake_queue = {
            "ok": True,
            "dry_run": True,
            "queue_status": "ready_read_only",
            "summary": {"total_tasks": 2, "schedule_safe_task_id": fallback_task["task_id"]},
            "selected_task": top_rpc_task,
            "schedule_safe_task": fallback_task,
            "rows": [top_rpc_task, fallback_task],
            "blockers": [],
        }

        with patch("services.onchain_engine.get_core_equity_agent_os_lite_state_snapshot", return_value=fake_snapshot), patch(
            "services.onchain_engine.get_core_equity_agent_os_lite_task_queue_view", return_value=fake_queue
        ):
            report = onchain_engine.get_core_equity_agent_os_lite_schedule_activation_checklist(
                dry_run=True,
                cadence_minutes=60,
                max_cycles_per_day=6,
                allow_live_checks=False,
            )

        self.assertEqual(report["checklist_status"], "ready_but_paused")
        self.assertEqual(report["top_task"]["task_id"], top_rpc_task["task_id"])
        self.assertEqual(report["selected_task"]["task_id"], fallback_task["task_id"])
        self.assertTrue(report["schedule_safe_fallback_used"])
        self.assertTrue(all(row["passed"] for row in report["preflight_checks"]))
        self.assertFalse(report["would_create_schedule"])
        self.assertFalse(report["would_write"])
        self.assertEqual(report["writes_performed"], 0)

    def test_unknown_dex_traceability_candidate_internal_probe_is_read_only(self) -> None:
        labels_before = label_ledger.get_label_ledger_summary()["labels"]
        candidates_before = label_ledger.get_label_ledger_summary()["label_candidates"]
        jobs_before = onchain_engine.get_data_jobs(limit=100)
        router = "0x" + "8" * 40
        pool = "0x" + "a" * 40
        counterparty = "0x" + "b" * 40
        tx_hash = "0x" + "1" * 64
        fake_selector = {
            "ok": True,
            "dry_run": True,
            "selector_status": "ready_read_only",
            "chain": "bsc",
            "summary": {"probe_ready_candidates": 1},
            "rows": [
                {
                    "route_candidate_status": "candidate_for_internal_transaction_or_trace_probe",
                    "router_addr": router,
                    "tx_hash": tx_hash,
                    "block_number": 1_000,
                    "traceability_score": 90,
                    "non_infrastructure_symbols": ["TST"],
                    "token_context": [],
                    "local_context": {"pair_tokens_bound": True, "transfer_rows": 2},
                }
            ],
            "blockers": ["traceable_unknown_dex_candidates_are_context_only"],
        }
        fake_internal_items = [
            {
                "type": "call",
                "from": {"hash": router, "name": "Intermediary"},
                "to": {"hash": pool, "name": "Pair"},
                "created_contract": None,
                "value": "0",
                "gas_limit": "100000",
                "index": 0,
                "error": None,
            },
            {
                "type": "call",
                "from": {"hash": pool, "name": "Pair"},
                "to": {"hash": counterparty, "name": "Counterparty"},
                "created_contract": None,
                "value": "0",
                "gas_limit": "90000",
                "index": 1,
                "error": None,
            },
        ]

        with patch(
            "services.onchain_engine.get_unknown_dex_traceability_candidate_selector",
            return_value=fake_selector,
        ), patch(
            "services.onchain_engine._blockscout_transaction_internal_transactions",
            return_value=(fake_internal_items, None),
        ) as mock_internal:
            dry = onchain_engine.run_unknown_dex_traceability_candidate_internal_probe(
                chain="bsc",
                dry_run=True,
                max_external_calls=1,
            )
            confirmed = onchain_engine.run_unknown_dex_traceability_candidate_internal_probe(
                chain="bsc",
                dry_run=False,
                external_fetch=True,
                confirm="RUN_UNKNOWN_DEX_TRACEABILITY_CANDIDATE_INTERNAL_PROBE",
                max_external_calls=1,
            )

        self.assertEqual(dry["probe_status"], "ready_for_confirmed_external_fetch")
        self.assertTrue(dry["would_call_external"])
        self.assertEqual(dry["external_calls_performed"], 0)
        self.assertEqual(mock_internal.call_count, 1)
        self.assertEqual(confirmed["probe_status"], "external_internal_transactions_observed_read_only")
        self.assertEqual(confirmed["summary"]["external_calls_attempted"], 1)
        self.assertEqual(confirmed["summary"]["transactions_with_internal_items"], 1)
        self.assertEqual(confirmed["summary"]["internal_items_observed"], 2)
        self.assertFalse(confirmed["rows"][0]["would_persist_internal_transactions"])
        self.assertFalse(confirmed["would_create_venue_mapping"])
        self.assertFalse(confirmed["would_create_client_signal"])
        self.assertFalse(confirmed["would_write"])
        self.assertEqual(confirmed["writes_performed"], 0)

        blocked = onchain_engine.run_unknown_dex_traceability_candidate_internal_probe(
            dry_run=False,
            external_fetch=False,
            confirm="RUN_UNKNOWN_DEX_TRACEABILITY_CANDIDATE_INTERNAL_PROBE",
        )
        self.assertFalse(blocked["ok"])
        self.assertIn("external_fetch_false", blocked["blockers"])
        self.assertEqual(label_ledger.get_label_ledger_summary()["labels"], labels_before)
        self.assertEqual(label_ledger.get_label_ledger_summary()["label_candidates"], candidates_before)
        self.assertEqual(onchain_engine.get_data_jobs(limit=100), jobs_before)

