                    (tx_hashes[1], "bsc", 501, 1_778_100_001, wallet, "Unknown DEX", token, wbnb, 2, 1, 1200, pools[1], "exact_pair_log_direction", "test_rpc", router, "test", 0.1),
                    (tx_hashes[2], "bsc", 502, 1_778_100_002, wallet, "Unknown DEX", token_b, usdt, 3, 3, 3, pools[2], "exact_pair_log_direction", "test_rpc", router, "test", 0.1),
