    def test_token_market_local_candidate_metadata_repair_targets_source_repair_rows(self) -> None:
        original_rpc_evm_chain = onchain_engine._rpc_evm_chain
        token = "0x" + "7" * 40
        labels_before = label_ledger.get_label_ledger_summary()["labels"]
        fake_repair = {
            "ok": True,
            "summary": {"repair_rows": 1},
            "rows": [
                {
                    "repair_rank": 1,
                    "lead_id": 1,
                    "token_symbol": None,
                    "chain": "eth",
                    "token_address": token,
                    "proposed_route": "dex",
                    "repair_priority": 85,
                    "source_repair_status": "needs_source_backing",
                    "local_evidence": {"distinct_pools": 2},
                    "missing_to_be_source_backed": ["token_symbol_required"],
                }
            ],
        }

        def abi_string(value: str) -> str:
            raw = value.encode().hex()
            padded_len = ((len(raw) + 63) // 64) * 64
            return "0x" + f"{32:064x}" + f"{len(value):064x}" + raw.ljust(padded_len, "0")

        def fake_rpc_evm_chain(chain: str, method: str, params: list) -> tuple[str, str]:
            selector = params[0]["data"]
            if selector == "0x95d89b41":
                return abi_string("RPR"), "test_rpc"
            if selector == "0x06fdde03":
                return abi_string("Repair Token"), "test_rpc"
            if selector == "0x313ce567":
                return "0x" + f"{18:064x}", "test_rpc"
            return "0x", "test_rpc"

        try:
            onchain_engine._rpc_evm_chain = fake_rpc_evm_chain
            with patch("services.onchain_engine.get_token_market_local_candidate_source_repair_plan", return_value=fake_repair):
                plan = onchain_engine.get_token_market_local_candidate_metadata_repair_plan(limit=5, dry_run=True)
                dry = onchain_engine.enrich_token_metadata_for_local_candidate_repair(limit=5, dry_run=True)
                result = onchain_engine.enrich_token_metadata_for_local_candidate_repair(
                    limit=5,
                    dry_run=False,
                    confirm=onchain_engine.TOKEN_MARKET_LOCAL_CANDIDATE_METADATA_REPAIR_CONFIRM,
                    max_seconds=30,
                )
        finally:
            onchain_engine._rpc_evm_chain = original_rpc_evm_chain

        self.assertTrue(plan["ok"])
        self.assertEqual(plan["plan_status"], "ready")
        self.assertEqual(plan["selected_for_enrichment"][0]["token_address"], token)
        self.assertFalse(plan["would_write"])
        self.assertEqual(dry["repair_status"], "ready_but_disabled")
        self.assertTrue(dry["would_enrich_metadata"])
        self.assertFalse(dry["would_write"])
        self.assertEqual(result["repair_status"], "completed")
        self.assertEqual(result["resolved"], 1)
        self.assertEqual(result["changed_tables"]["token_metadata"], 1)
        self.assertEqual(result["changed_tables"]["data_jobs"], 1)
        self.assertEqual(result["disallowed_table_deltas"], {})
        self.assertFalse(result["labels_changed"])
        self.assertFalse(result["would_create_cex_label"])
        self.assertFalse(result["would_create_mapping"])
        self.assertFalse(result["would_create_client_signal"])
        self.assertFalse(result["would_execute_trade"])
        self.assertEqual(label_ledger.get_label_ledger_summary()["labels"], labels_before)

