    def test_aster_dex_fund_flow_collection_is_dry_run_first_and_data_only(self) -> None:
        labels_before = label_ledger.get_label_ledger_summary()["labels"]
        candidates_before = label_ledger.get_label_ledger_summary()["label_candidates"]
        aster_treasury = "0x128463a60784c4d3f46c23af3f65ed859ba87974"
        token = "0x" + "6" * 40
        source_wallet = "0x" + "8" * 40
        original_rpc = onchain_engine._rpc_evm_chain

        def topic(address: str) -> str:
            return "0x" + address.lower().replace("0x", "").rjust(64, "0")

        def fake_rpc(chain: str, method: str, params: list) -> tuple[object, str]:
            if method == "eth_blockNumber":
                return hex(2500), "test_rpc"
            if method == "eth_getBlockByNumber":
                return {"timestamp": hex(1_778_200_000)}, "test_rpc"
            if method == "eth_getLogs":
                filter_payload = params[0] or {}
                if str(filter_payload.get("address") or "").lower() != token:
                    return [], "test_rpc"
                requested_to_topic = (filter_payload.get("topics") or [None, None, None])[2]
                if requested_to_topic != topic(aster_treasury):
                    return [], "test_rpc"
                return [
                    {
                        "address": token,
                        "transactionHash": "0x" + "c" * 64,
                        "logIndex": "0x1",
                        "blockNumber": hex(2400),
                        "topics": [
                            onchain_engine.TRANSFER_TOPIC,
                            topic(source_wallet),
                            topic(aster_treasury),
                        ],
                        "data": hex(12345),
                    }
                ], "test_rpc"
            raise AssertionError(f"unexpected rpc call {method}")

        conn = sqlite3.connect(str(self.onchain_db))
        try:
            conn.execute(
                """
                INSERT INTO token_metadata (
                    chain, token_address, symbol, name, decimals, rpc_source, observed_at, status
                ) VALUES (?, ?, ?, ?, ?, ?, ?, ?)
                """,
                ("bsc", token, "TEST", "Test Token", 18, "test", 1_778_100_000, "resolved"),
            )
            conn.commit()
        finally:
            conn.close()

        try:
            onchain_engine._rpc_evm_chain = fake_rpc
            dry_run = onchain_engine.run_aster_dex_fund_flow_collection(
                chain="bsc",
                lookback_blocks=100,
                max_tokens_per_chain=10,
                dry_run=True,
            )
            blocked = onchain_engine.run_aster_dex_fund_flow_collection(
                chain="bsc",
                lookback_blocks=100,
                max_tokens_per_chain=10,
                dry_run=False,
                confirm=None,
            )
            confirmed = onchain_engine.run_aster_dex_fund_flow_collection(
                chain="bsc",
                lookback_blocks=100,
                max_tokens_per_chain=10,
                dry_run=False,
                confirm="COLLECT_ASTER_DEX_FUND_FLOW_DATA",
            )
        finally:
            onchain_engine._rpc_evm_chain = original_rpc

        self.assertEqual(dry_run["collection_status"], "ready_but_disabled")
        self.assertTrue(dry_run["would_call_rpc"])
        self.assertIn(token, dry_run["token_refs_by_chain"]["bsc"])
        self.assertFalse(dry_run["would_write"])
        self.assertIn("confirm_required", blocked["blockers"])
        self.assertEqual(confirmed["collection_status"], "completed")
        self.assertEqual(confirmed["logs_found"], 1)
        self.assertEqual(confirmed["rows_inserted"], 1)
        self.assertEqual(confirmed["changed_tables"].get("token_transfers"), 1)
        self.assertEqual(confirmed["changed_tables"].get("data_jobs"), 1)
        self.assertEqual(confirmed["disallowed_table_deltas"], {})
        self.assertFalse(confirmed["would_create_cex_label"])
        self.assertFalse(confirmed["would_create_dex_router_evidence"])
        self.assertFalse(confirmed["would_create_mapping"])
        self.assertEqual(label_ledger.get_label_ledger_summary()["labels"], labels_before)
        self.assertEqual(label_ledger.get_label_ledger_summary()["label_candidates"], candidates_before)

    def test_aster_dex_paginated_collection_runs_small_windows_data_only(self) -> None:
        labels_before = label_ledger.get_label_ledger_summary()["labels"]
        candidates_before = label_ledger.get_label_ledger_summary()["label_candidates"]
        original_latest = onchain_engine.get_latest_block
        original_child = onchain_engine.run_aster_dex_fund_flow_collection
        calls: list[dict] = []

        def fake_latest(chain: str) -> int:
            self.assertEqual(chain, "bsc")
            return 3000

        def fake_child(**kwargs):
            calls.append(kwargs)
            conn = sqlite3.connect(str(self.onchain_db))
            try:
                conn.execute(
                    """
                    INSERT OR IGNORE INTO token_transfers (
                        tx_hash, log_index, chain, block_number, timestamp, token,
                        from_addr, to_addr, value_raw, source
                    ) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?)
                    """,
                    (
                        "0x" + str(len(calls)) * 64,
                        len(calls),
                        "bsc",
                        2900 - len(calls),
                        1_778_300_000,
                        "0x" + "6" * 40,
                        "0x" + "8" * 40,
                        "0x128463a60784c4d3f46c23af3f65ed859ba87974",
                        "1",
                        "test_paginated_aster",
                    ),
                )
                conn.commit()
            finally:
                conn.close()
            return {
                "collection_status": "completed",
                "job_id": 9000 + len(calls),
                "logs_found": 1,
                "rows_inserted": 1,
                "per_reference": [],
                "errors": [],
                "blockers": [],
            }

        try:
            onchain_engine.get_latest_block = fake_latest
            onchain_engine.run_aster_dex_fund_flow_collection = fake_child
            dry_run = onchain_engine.run_aster_dex_paginated_fund_flow_collection(
                chain="bsc",
                pages=2,
                page_size_blocks=50,
                dry_run=True,
            )
            blocked = onchain_engine.run_aster_dex_paginated_fund_flow_collection(
                chain="bsc",
                pages=2,
                page_size_blocks=50,
                dry_run=False,
                confirm=None,
            )
            confirmed = onchain_engine.run_aster_dex_paginated_fund_flow_collection(
                chain="bsc",
                pages=2,
                page_size_blocks=50,
                dry_run=False,
                confirm="COLLECT_ASTER_DEX_PAGINATED_FUND_FLOW_DATA",
            )
        finally:
            onchain_engine.get_latest_block = original_latest
            onchain_engine.run_aster_dex_fund_flow_collection = original_child

        self.assertEqual(dry_run["collection_status"], "ready_but_disabled")
        self.assertFalse(dry_run["would_write"])
        self.assertIn("confirm_required", blocked["blockers"])
        self.assertEqual(confirmed["collection_status"], "completed")
