    def test_aster_source_wallet_token_flow_collection_is_bounded_and_data_only(self) -> None:
        labels_before = label_ledger.get_label_ledger_summary()["labels"]
        candidates_before = label_ledger.get_label_ledger_summary()["label_candidates"]
        aster_treasury = "0x128463a60784c4d3f46c23af3f65ed859ba87974"
        token = "0x" + "6" * 40
        source_wallet = "0x" + "8" * 40
        binance_wallet = "0x" + "b" * 40
        original_rpc = onchain_engine._rpc_evm_chain

        def topic(address: str) -> str:
            return "0x" + address.lower().replace("0x", "").rjust(64, "0")

        def transfer_log(tx_suffix: str, log_index: int, block_number: int, from_addr: str, to_addr: str, value: int) -> dict:
            return {
                "address": token,
                "transactionHash": "0x" + tx_suffix * 64,
                "logIndex": hex(log_index),
                "blockNumber": hex(block_number),
                "topics": [
                    onchain_engine.TRANSFER_TOPIC,
                    topic(from_addr),
                    topic(to_addr),
                ],
                "data": hex(value),
            }

        def fake_rpc(chain: str, method: str, params: list) -> tuple[object, str]:
            self.assertEqual(chain, "bsc")
            if method == "eth_getBlockByNumber":
                return {"timestamp": hex(1_778_500_000)}, "test_rpc"
            if method == "eth_getLogs":
                filter_payload = params[0] or {}
                self.assertEqual(str(filter_payload.get("address") or "").lower(), token)
                topics = filter_payload.get("topics") or []
                if len(topics) >= 3 and topics[1] is None and topics[2] == topic(source_wallet):
                    return [transfer_log("a", 1, 295, binance_wallet, source_wallet, 7)], "test_rpc"
                if len(topics) >= 3 and topics[1] == topic(source_wallet) and topics[2] is None:
                    return [transfer_log("f", 2, 305, source_wallet, aster_treasury, 3)], "test_rpc"
                return [], "test_rpc"
            raise AssertionError(f"unexpected rpc call {method}")

        conn = sqlite3.connect(str(self.onchain_db))
        try:
            conn.execute(
                """
                INSERT INTO token_metadata (
                    chain, token_address, symbol, name, decimals, rpc_source, observed_at, status
                ) VALUES (?, ?, ?, ?, ?, ?, ?, ?)
                """,
                ("bsc", token, "TEST", "Test Token", 18, "test", 1_778_100_000, "resolved"),
            )
            conn.execute(
                """
                INSERT INTO token_transfers (
                    tx_hash, log_index, chain, block_number, timestamp, token,
                    from_addr, to_addr, value_raw, source
                ) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?)
                """,
                (
                    "0x" + "d" * 64,
                    1,
                    "bsc",
                    300,
                    1_778_400_000,
                    token,
                    source_wallet,
                    aster_treasury,
                    "1234500000000000000",
                    "aster_official_reference_transfer:test",
                ),
            )
            conn.commit()
        finally:
            conn.close()

        try:
            onchain_engine._rpc_evm_chain = fake_rpc
            dry_run = onchain_engine.run_aster_source_wallet_token_flow_collection(
                chain="bsc",
                lookback_blocks=10,
                forward_blocks=10,
                max_tokens_per_chain=1,
                dry_run=True,
            )
            blocked = onchain_engine.run_aster_source_wallet_token_flow_collection(
                chain="bsc",
                lookback_blocks=10,
                forward_blocks=10,
                max_tokens_per_chain=1,
                dry_run=False,
                confirm=None,
            )
            confirmed = onchain_engine.run_aster_source_wallet_token_flow_collection(
                chain="bsc",
                lookback_blocks=10,
                forward_blocks=10,
                max_tokens_per_chain=1,
                dry_run=False,
                confirm="COLLECT_ASTER_SOURCE_WALLET_TOKEN_FLOW_DATA",
            )
        finally:
            onchain_engine._rpc_evm_chain = original_rpc

        self.assertEqual(dry_run["collection_status"], "ready_but_disabled")
        self.assertTrue(dry_run["would_call_rpc"])
        self.assertFalse(dry_run["would_write"])
        self.assertIn("confirm_required", blocked["blockers"])
        self.assertEqual(confirmed["collection_status"], "completed")
        self.assertEqual(confirmed["logs_found"], 2)
        self.assertEqual(confirmed["rows_inserted"], 2)
        self.assertEqual(confirmed["changed_tables"].get("token_transfers"), 2)
        self.assertEqual(confirmed["changed_tables"].get("data_jobs"), 1)
        self.assertEqual(confirmed["disallowed_table_deltas"], {})
        self.assertFalse(confirmed["would_create_cex_label"])
        self.assertFalse(confirmed["would_create_dex_router_evidence"])
        self.assertFalse(confirmed["would_create_mapping"])
        self.assertEqual(label_ledger.get_label_ledger_summary()["labels"], labels_before)
        self.assertEqual(label_ledger.get_label_ledger_summary()["label_candidates"], candidates_before)

    def test_unknown_router_official_source_search_scan_is_read_only_and_requires_exact_source(self) -> None:
        labels_before = label_ledger.get_label_ledger_summary()["labels"]
        candidates_before = label_ledger.get_label_ledger_summary()["label_candidates"]
        jobs_before = onchain_engine.get_data_jobs(limit=100)
        router = "0x" + "1" * 40
        fake_queue = {
            "ok": True,
            "chain": "eth",
            "summary": {"queue_rows": 1, "ready_for_official_source_search": 1},
            "rows": [
                {
                    "candidate_id": f"eth:{router}",
                    "chain": "eth",
                    "router_addr": router,
                    "queue_status": "ready_for_official_source_search",
                    "priority_score": 82,
                    "public_evidence": {"proposed_venue": "0x Protocol"},
                    "official_source_status": {"status": "official_rule_terms_only", "has_rule": True},
                    "official_source_requirements": [
                        "official_protocol_domain_or_docs",
                        "exact_router_address_visible",
                        "contract_role_explained_router_or_aggregator",
                    ],
                    "official_urls_to_check": [
                        "https://docs.0x.org/docs/0x-swap-api/additional-topics/how-to-set-your-token-allowances"
                    ],
                    "source_search_queries": ["0x search"],
                    "blockers": ["no_auto_mapping"],
                }
            ],
        }

        class FakeResponse:
            status = 200

            def __init__(self, url: str):
                self.url = url

            def __enter__(self):
                return self

            def __exit__(self, *_args):
                return False

            def read(self, *_args):
                return (
                    f"<title>0x Docs</title>0x API uses AllowanceHolder for swap API approvals. "
                    f"Ethereum router {router}"
                ).encode()

            def geturl(self):
                return self.url

        def fake_urlopen(req, timeout=0):
            return FakeResponse(req.full_url)

        with patch("services.onchain_engine.get_unknown_router_official_source_acquisition_queue", return_value=fake_queue):
            with patch("services.onchain_engine.urllib.request.urlopen", fake_urlopen):
                report = onchain_engine.get_unknown_router_official_source_search_scan(
                    "eth",
                    limit=5,
                    timeout=2,
                )

        self.assertTrue(report["ok"])
        self.assertEqual(report["summary"]["source_scan_rows"], 1)
        self.assertEqual(report["summary"]["official_source_corroborated"], 1)
        self.assertEqual(report["summary"]["admin_review_ready_rows"], 1)
        self.assertEqual(report["summary"]["auto_write_candidates"], 0)
        row = report["rows"][0]
        self.assertEqual(row["proposed_venue"], "0x Protocol")
        self.assertTrue(row["official_source_corroborated"])
        self.assertTrue(row["ready_for_admin_review"])
        self.assertFalse(row["can_write_evidence_bundle"])
        self.assertFalse(row["can_promote_or_map"])
        self.assertIn("allowanceholder", row["official_sources"][0]["matched_terms"])
        self.assertEqual(row["review_package"]["admin_header_required"], "X-Core-Admin-Token")
        self.assertEqual(row["review_package"]["confirm_required"], "UPSERT_SOURCE_BACKED_VENUE_MAPPING")
        self.assertIn("no_auto_write", row["review_package"]["blocked_mutations"])
        self.assertIn("official_sources_verified_but_admin_review_required", report["blockers"])
        self.assertIn("read-only", report["source_policy"])
        self.assertEqual(label_ledger.get_label_ledger_summary()["labels"], labels_before)
        self.assertEqual(label_ledger.get_label_ledger_summary()["label_candidates"], candidates_before)
        self.assertEqual(onchain_engine.get_data_jobs(limit=100), jobs_before)

