        self.assertEqual(report["summary"]["ready_for_official_source_search_after_identity"], 1)
        self.assertEqual(report["summary"]["auto_write_candidates"], 0)
        row = report["rows"][0]
        self.assertEqual(row["candidate_venue_hint"], "Uniswap")
        self.assertEqual(row["identity_status"], "candidate_venue_hint_found_needs_official_source")
        self.assertGreaterEqual(row["source_score"], 50)
        self.assertEqual(len(row["pages"]), 2)
        self.assertFalse(row["can_promote_or_map"])
        self.assertIn("official_source_not_checked", row["blockers"])
        self.assertIn("no_auto_mapping", row["blocked_mutations"])
        self.assertIn("official_source_search_required_after_identity_hint", report["blockers"])
        self.assertIn("read-only", report["source_policy"])
        self.assertEqual(label_ledger.get_label_ledger_summary()["labels"], labels_before)
        self.assertEqual(label_ledger.get_label_ledger_summary()["label_candidates"], candidates_before)
        self.assertEqual(onchain_engine.get_data_jobs(limit=100), jobs_before)

