        self.assertEqual(report["summary"]["routers_with_exact_token_rows"], 1)
        row = report["rows"][0]
        self.assertEqual(row["fingerprint_status"], "interaction_surface_with_exact_tokens")
        self.assertEqual(row["interaction_summary"]["swap_rows"], 1)
        self.assertEqual(row["interaction_summary"]["exact_token_rows"], 1)
        self.assertIn(token_in, row["sample_tokens"])
        self.assertIn(pool, row["sample_pools"])
        self.assertEqual(row["labelled_counterparties"][0]["entity"], "Alpha")
        self.assertFalse(row["can_promote_or_map"])
        self.assertIn("calldata_method_trace_missing", row["blockers"])
        self.assertIn("no_auto_mapping", row["blocked_mutations"])
        self.assertIn("router_interaction_trace_methods_missing", report["blockers"])
        self.assertIn("read-only", report["source_policy"])
        self.assertEqual(label_ledger.get_label_ledger_summary()["labels"], labels_before)
        self.assertEqual(label_ledger.get_label_ledger_summary()["label_candidates"], candidates_before)
        self.assertEqual(onchain_engine.get_data_jobs(limit=100), jobs_before)

