    def test_token_market_recent_unknown_router_internal_fallback_is_explicit_and_read_only(self) -> None:
        labels_before = label_ledger.get_label_ledger_summary()["labels"]
        candidates_before = label_ledger.get_label_ledger_summary()["label_candidates"]
        jobs_before = onchain_engine.get_data_jobs(limit=100)
        tx_hash = "0x" + "8" * 64
        router = "0x" + "1" * 40
        pair = "0x" + "2" * 40
        vault = "0x" + "3" * 40
        token = "0x" + "4" * 40
        wbnb = "0xbb4cdb9cbd36b01bd1cbaebf2de08d9173bc095c"
        conn = sqlite3.connect(str(self.onchain_db))
        try:
            conn.execute(
                """
                INSERT INTO swaps (
                    tx_hash, chain, block_number, timestamp, wallet, dex,
                    token_in, token_out, amount_in, amount_out, amount_usd, pool,
                    token_identity_quality, pair_rpc_source, router_addr, venue_source, venue_confidence
                ) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)
                """,
                (
                    tx_hash,
                    "bsc",
                    2000,
                    1_779_000_000,
                    "0x" + "5" * 40,
                    "Unknown DEX",
                    token,
                    wbnb,
                    100.0,
                    0.5,
                    None,
                    pair,
                    "exact_pair_log_direction",
                    "test_pair_rpc",
                    router,
                    "local_unknown",
                    0.1,
                ),
            )
            conn.commit()
        finally:
            conn.close()

        with patch("services.onchain_engine._blockscout_transaction_internal_transactions") as mock_internal:
            dry = onchain_engine.get_token_market_recent_unknown_router_internal_transaction_fallback_scan(
                "bsc",
                block_window=100,
                limit=5,
                timeout=2,
                external_fetch=False,
                dry_run=True,
            )
        mock_internal.assert_not_called()
        self.assertTrue(dry["ok"])
        self.assertEqual(dry["summary"]["recent_unknown_router_candidates"], 1)
        self.assertTrue(dry["would_call_external"])
        self.assertEqual(dry["rows"][0]["fallback_status"], "external_fetch_disabled")
        self.assertFalse(dry["rows"][0]["can_promote_or_map"])
        self.assertFalse(dry["would_write"])

        fake_internal_items = [
            {
                "type": "call",
                "from": {"hash": router, "name": "Unknown Router"},
                "to": {"hash": pair, "name": "PancakeSwap: Pair"},
                "value": "0",
                "index": 0,
            },
            {
                "type": "call",
                "from": {"hash": pair, "name": "PancakeSwap: Pair"},
                "to": {"hash": vault, "implementation_name": "Vault"},
                "value": "1",
                "index": 1,
            },
        ]
        with patch(
            "services.onchain_engine._blockscout_transaction_internal_transactions",
            return_value=(fake_internal_items, None),
        ) as mock_internal:
            report = onchain_engine.get_token_market_recent_unknown_router_internal_transaction_fallback_scan(
                "bsc",
                block_window=100,
                limit=5,
                timeout=2,
                external_fetch=True,
                dry_run=True,
            )
        mock_internal.assert_called_once()
        self.assertTrue(report["ok"])
        self.assertEqual(report["summary"]["external_calls_attempted"], 1)
        self.assertEqual(report["summary"]["routers_with_internal_transactions"], 1)
        self.assertEqual(report["rows"][0]["fallback_status"], "explorer_internal_transactions_observed")
        self.assertEqual(report["rows"][0]["top_internal_counterparties"][0]["address"], pair)
        self.assertIn("explorer_internal_transactions_available_but_not_venue_proof", report["rows"][0]["blockers"])
        self.assertFalse(report["rows"][0]["can_promote_or_map"])
        self.assertFalse(report["would_create_dex_router_evidence"])
        self.assertFalse(report["would_create_mapping"])
        self.assertFalse(report["would_write"])
        self.assertEqual(report["writes_performed"], 0)
        self.assertEqual(label_ledger.get_label_ledger_summary()["labels"], labels_before)
        self.assertEqual(label_ledger.get_label_ledger_summary()["label_candidates"], candidates_before)
        self.assertEqual(onchain_engine.get_data_jobs(limit=100), jobs_before)

