    def test_unknown_swap_attribution_enrichment_is_dry_run_by_default(self) -> None:
        wallet = "0x" + "1" * 40
        router = "0x" + "2" * 40
        labels_before = label_ledger.get_label_ledger_summary()["labels"]
        candidates_before = label_ledger.get_label_ledger_summary()["label_candidates"]
        jobs_before = onchain_engine.get_data_jobs(limit=100)
        conn = sqlite3.connect(str(self.onchain_db))
        try:
            conn.execute(
                """
                INSERT INTO swaps (
                    tx_hash, chain, block_number, timestamp, wallet, dex,
                    token_in, token_out, amount_in, amount_out, amount_usd, pool,
                    router_addr, venue_source, venue_confidence
                ) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)
                """,
                (
                    "0x" + "4" * 64,
                    "eth",
                    1_010,
                    1_778_600_001,
                    wallet,
                    "Unknown DEX",
                    "0x" + "d" * 40,
                    "0x" + "e" * 40,
                    1.0,
                    2.0,
                    10.0,
                    "0x" + "f" * 40,
                    router,
                    "swap_pool_event_unattributed",
                    0.35,
                ),
            )
            conn.commit()
        finally:
            conn.close()

        report = onchain_engine.enrich_unknown_swap_attribution_targets(chain="eth", limit=5, dry_run=True)

        self.assertTrue(report["ok"])
        self.assertTrue(report["dry_run"])
        self.assertEqual(report["targets_found"], 2)
        self.assertEqual([row["role"] for row in report["targets"]], ["router", "swap_wallet"])
        self.assertEqual(report["confirm_required_for_write"], "ENRICH_UNKNOWN_SWAP_ATTRIBUTION")
        self.assertIn("dry-run", report["source_policy"])
        self.assertEqual(label_ledger.get_label_ledger_summary()["labels"], labels_before)
        self.assertEqual(label_ledger.get_label_ledger_summary()["label_candidates"], candidates_before)
        self.assertEqual(onchain_engine.get_data_jobs(limit=100), jobs_before)
        conn = sqlite3.connect(str(self.onchain_db))
        try:
            target_rows = conn.execute(
                "SELECT COUNT(*) FROM wallet_chain_state WHERE address IN (?, ?)",
                (wallet, router),
            ).fetchone()[0]
            self.assertEqual(target_rows, 0)
        finally:
            conn.close()

    def test_unknown_swap_attribution_enrichment_requires_confirm_and_is_audited(self) -> None:
        wallet = "0x" + "1" * 40
        router = "0x" + "2" * 40
        labels_before = label_ledger.get_label_ledger_summary()["labels"]
        candidates_before = label_ledger.get_label_ledger_summary()["label_candidates"]
        conn = sqlite3.connect(str(self.onchain_db))
        try:
            conn.execute(
                """
                INSERT INTO swaps (
                    tx_hash, chain, block_number, timestamp, wallet, dex,
                    token_in, token_out, amount_in, amount_out, amount_usd, pool,
                    router_addr, venue_source, venue_confidence
                ) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)
                """,
                (
                    "0x" + "5" * 64,
                    "eth",
                    1_011,
                    1_778_600_002,
                    wallet,
                    "Unknown DEX",
                    "0x" + "d" * 40,
                    "0x" + "e" * 40,
                    1.0,
                    2.0,
                    10.0,
                    "0x" + "f" * 40,
                    router,
                    "swap_pool_event_unattributed",
                    0.35,
                ),
            )
            conn.commit()
        finally:
            conn.close()

        blocked = onchain_engine.enrich_unknown_swap_attribution_targets(
            chain="eth",
            limit=5,
            dry_run=False,
            confirm=None,
        )
        self.assertFalse(blocked["ok"])
        self.assertEqual(blocked["error"], "confirm_ENRICH_UNKNOWN_SWAP_ATTRIBUTION_required")

        calls: list[tuple[str, str, bool]] = []

        def fake_persist(address, *, chains=None, include_tokens=True, refresh_after_hours=12, force_refresh=False):
            calls.append((address, chains, include_tokens))
            return {
                "ok": True,
                "address": address,
                "updated": 1,
                "skipped_fresh": 0,
                "errors": [],
                "source_policy": "mock wallet_chain_state write only",
            }

        with patch("services.onchain_engine.persist_wallet_analysis_rpc_snapshot", fake_persist):
            result = onchain_engine.enrich_unknown_swap_attribution_targets(
                chain="eth",
                limit=5,
                dry_run=False,
                confirm="ENRICH_UNKNOWN_SWAP_ATTRIBUTION",
            )

        self.assertTrue(result["ok"])
        self.assertFalse(result["dry_run"])
        self.assertEqual(result["targets_found"], 2)
        self.assertEqual(result["wallet_chain_state_updated"], 2)
        self.assertEqual(calls[0], (router, "eth", False))
        self.assertEqual(calls[1], (wallet, "eth", False))
        self.assertIsNotNone(result["job_id"])
        jobs = onchain_engine.get_data_jobs(limit=5)
        self.assertEqual(jobs["rows"][0]["job_type"], "unknown_swap_attribution_rpc_enrichment")
        self.assertEqual(jobs["rows"][0]["status"], "ok")
        self.assertEqual(label_ledger.get_label_ledger_summary()["labels"], labels_before)
        self.assertEqual(label_ledger.get_label_ledger_summary()["label_candidates"], candidates_before)

    def test_unknown_swap_router_code_fingerprints_are_read_only(self) -> None:
        original_get_evm_code = onchain_engine.get_evm_code
        router_a = "0x" + "9" * 40
        router_b = "0x" + "8" * 40
        pool = "0x" + "a" * 40
        labels_before = label_ledger.get_label_ledger_summary()["labels"]
        candidates_before = label_ledger.get_label_ledger_summary()["label_candidates"]
        jobs_before = onchain_engine.get_data_jobs(limit=100)
        conn = sqlite3.connect(str(self.onchain_db))
        try:
            for idx, router in enumerate((router_a, router_b), start=1):
                conn.execute(
                    """
                    INSERT INTO swaps (
                        tx_hash, chain, block_number, timestamp, wallet, dex,
                        token_in, token_out, amount_in, amount_out, amount_usd, pool,
                        router_addr, venue_source, venue_confidence
                    ) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)
                    """,
                    (
                        "0x" + str(idx) * 64,
                        "eth",
                        1_000 + idx,
                        1_778_600_000 + idx,
                        "0x" + "b" * 40,
                        "Unknown DEX",
                        "0x" + "c" * 40,
                        "0x" + "d" * 40,
                        1.0,
                        2.0,
                        0.0,
                        pool,
                        router,
                        "swap_pool_event_unattributed",
                        0.35,
                    ),
                )
            conn.commit()
        finally:
            conn.close()

        try:
            onchain_engine.get_evm_code = lambda chain, address: "0x60016002" if address.lower() == router_a else "0x"
            report = onchain_engine.get_unknown_swap_router_code_fingerprints(chain="eth", limit=2)
        finally:
            onchain_engine.get_evm_code = original_get_evm_code

        self.assertTrue(report["ok"])
        self.assertEqual(report["summary"]["routers_fingerprinted"], 2)
        self.assertEqual(report["summary"]["contract_routers"], 1)
        self.assertEqual(report["summary"]["eoa_or_no_code_routers"], 1)
        contract_row = next(row for row in report["rows"] if row["router_addr"] == router_a)
        eoa_row = next(row for row in report["rows"] if row["router_addr"] == router_b)
        self.assertEqual(contract_row["code_kind"], "contract")
        self.assertTrue(contract_row["code_hash"])
        self.assertEqual(contract_row["mapping_policy"], "do_not_map_as_venue_without_official_source")
        self.assertEqual(eoa_row["mapping_policy"], "not_a_contract_venue_candidate")
        self.assertIn("read-only", report["source_policy"])
        self.assertEqual(label_ledger.get_label_ledger_summary()["labels"], labels_before)
        self.assertEqual(label_ledger.get_label_ledger_summary()["label_candidates"], candidates_before)
        self.assertEqual(onchain_engine.get_data_jobs(limit=100), jobs_before)

