    def test_source_backed_venue_mapping_requires_source_and_is_audited(self) -> None:
        router = "0x10ed43c718714eb63d5aa57b78b54704e256024e"
        pool = "0x" + "2" * 40
        labels_before = label_ledger.get_label_ledger_summary()["labels"]
        candidates_before = label_ledger.get_label_ledger_summary()["label_candidates"]
        conn = sqlite3.connect(str(self.onchain_db))
        try:
            conn.execute(
                """
                INSERT INTO swaps (
                    tx_hash, chain, block_number, timestamp, wallet, dex,
                    token_in, token_out, amount_in, amount_out, amount_usd, pool,
                    router_addr, venue_source, venue_confidence
                ) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)
                """,
                (
                    "0x" + "3" * 64,
                    "bsc",
                    333,
                    1_778_300_000,
                    "0x" + "1" * 40,
                    "Unknown DEX",
                    "0x" + "4" * 40,
                    "0x" + "5" * 40,
                    1.0,
                    2.0,
                    0.0,
                    pool,
                    router,
                    "swap_pool_event_unattributed",
                    0.35,
                ),
            )
            conn.commit()
        finally:
            conn.close()

        blocked = onchain_engine.preview_source_backed_venue_mapping(
            "bsc",
            router,
            "Example DEX",
            "",
            0.85,
        )
        self.assertIn("source_url_required", blocked["blockers"])
        self.assertIn("official_source_rule_missing_for_venue", blocked["blockers"])
        self.assertFalse(blocked["can_apply"])

        weak_protocol_source = onchain_engine.preview_source_backed_venue_mapping(
            "bsc",
            router,
            "PancakeSwap V2",
            f"https://bscscan.com/address/{router}",
            0.85,
        )
        self.assertIn("official_source_url_required_for_venue", weak_protocol_source["blockers"])
        self.assertFalse(weak_protocol_source["can_apply"])

        official_protocol_source = onchain_engine.preview_source_backed_venue_mapping(
            "bsc",
            router,
            "PancakeSwap V2",
            "https://docs.pancakeswap.finance/to-delete/smart-contracts/pancakeswap-exchange/v2-contracts/router-v2",
            0.85,
        )
        self.assertNotIn("official_source_url_required_for_venue", official_protocol_source["blockers"])
        self.assertNotIn("official_chain_address_match_missing", official_protocol_source["blockers"])
        self.assertTrue(official_protocol_source["can_apply"])

        dry_run = onchain_engine.upsert_source_backed_venue_mapping(
            "bsc",
            router,
            "Example DEX",
            "https://docs.example.org/router",
            {"reason": "verified contract and docs match router"},
            0.85,
            dry_run=True,
        )
        self.assertFalse(dry_run["ok"])
        self.assertIn("official_source_rule_missing_for_venue", dry_run["blockers"])
        self.assertEqual(onchain_engine.get_source_backed_venue_mappings()["summary"]["total_mappings"], 0)

        result = onchain_engine.upsert_source_backed_venue_mapping(
            "bsc",
            router,
            "PancakeSwap V2",
            "https://docs.pancakeswap.finance/to-delete/smart-contracts/pancakeswap-exchange/v2-contracts/router-v2",
            {"reason": "verified contract and docs match router"},
            0.85,
            dry_run=False,
            confirm="UPSERT_SOURCE_BACKED_VENUE_MAPPING",
        )

        self.assertTrue(result["ok"])
        self.assertFalse(result["dry_run"])
        self.assertEqual(result["updated_swaps"], 1)
        self.assertTrue(Path(result["backup_path"]).exists())
        mappings = onchain_engine.get_source_backed_venue_mappings(chain="bsc")
        self.assertEqual(mappings["summary"]["total_mappings"], 1)
        self.assertEqual(mappings["rows"][0]["venue"], "PancakeSwap V2")
        inferred = onchain_engine._infer_swap_venue("bsc", router, pool)
        self.assertEqual(inferred["venue"], "PancakeSwap V2")
        self.assertIn(inferred["source"], {"known_router_address", "source_backed_router_mapping"})
