    def test_manipulation_readiness_keeps_review_action_when_strict_labels_pass(self) -> None:
        fake_readiness = {
            "summary": {
                "strict_label_pct": 25.0,
                "rpc_coverage_pct": 100.0,
                "venue_mapping_drafts": 0,
                "venue_skipped_drafts": 0,
                "venue_admin_review_ready": 0,
            },
            "venue_discovery": {"summary": {"unknown_venue_swaps": 0}},
        }
        fake_wallet_audit = {
            "traceability_pct": 100.0,
            "total_wallets": 1,
            "missing_label_sources": 0,
        }
        with patch("services.onchain_engine.get_onchain_data_readiness", return_value=fake_readiness), \
             patch("services.onchain_engine.get_rpc_wallet_state_audit", return_value=fake_wallet_audit), \
             patch("services.label_ledger.get_label_candidate_evidence_scores", return_value={"rows": []}):
            report = onchain_engine.get_manipulation_detection_readiness(entity="Binance", limit=5)

        contract = report["readiness_contract"]
        failed_ids = [item["id"] for item in contract["failed_requirements"]]
        self.assertIn("strict_review_candidates", failed_ids)
        action_ids = [item["action_id"] for item in contract["next_safe_actions"]]
        self.assertEqual(len(action_ids), len(set(action_ids)))
        self.assertIn("review_verified_label_candidates", action_ids)
        review_action = next(
            item for item in contract["next_safe_actions"]
            if item["action_id"] == "review_verified_label_candidates"
        )
        self.assertEqual(review_action["method"], "GET")
        self.assertFalse(review_action["admin_required"])
        self.assertTrue(review_action["client_visible"])
        self.assertFalse(review_action["execution_enabled"])
        self.assertFalse(review_action["client_safe"])
        client_visible_ids = [
            item["action_id"] for item in contract["client_visible_actions"]
        ]
        self.assertIn("review_verified_label_candidates", client_visible_ids)
        self.assertFalse(contract["automation_decision"]["first_client_diagnostic"]["execution_enabled"])

