    def test_readiness_gap_auto_fill_is_dry_run_and_traceable_by_default(self) -> None:
        with patch("services.onchain_engine.run_exact_swap_ingestion_plan_once") as ingest_once:
            ingest_once.side_effect = AssertionError("dry run must not ingest swaps")
            result = onchain_engine.run_readiness_gap_auto_fill(
                entity="Binance",
                dry_run=True,
                max_cycles=8,
                max_pairs=2,
            )

        self.assertTrue(result["ok"])
        self.assertTrue(result["dry_run"])
        self.assertFalse(result["execution_envelope"]["client_execution_enabled"])
        self.assertFalse(result["execution_envelope"]["copy_trading_enabled"])
        self.assertFalse(result["execution_envelope"]["profit_guarantee_allowed"])
        self.assertIn("source_trace", result)
        self.assertGreater(len(result["source_trace"]), 0)
        self.assertTrue(all(step["dry_run"] is True for step in result["source_trace"]))
        self.assertTrue(all(isinstance(step.get("source_policy"), str) for step in result["source_trace"]))
        self.assertTrue(all("client_execution_disabled" in step.get("warnings", []) for step in result["source_trace"]))
        self.assertEqual(result["before"], result["after"])
        ingest_once.assert_not_called()

    def test_readiness_gap_auto_fill_real_mode_requires_confirm(self) -> None:
        result = onchain_engine.run_readiness_gap_auto_fill(
            entity="Binance",
            dry_run=False,
            confirm=None,
            max_cycles=1,
        )

        self.assertFalse(result["ok"])
        self.assertEqual(result["error"], "confirm_RUN_READYNESS_GAP_FILL_required")
        self.assertTrue(result["execution_envelope"]["admin_confirm_required"])
        self.assertFalse(result["execution_envelope"]["client_execution_enabled"])
        self.assertEqual(result["source_trace"], [])

