    def test_ingest_block_respects_receipt_budget(self) -> None:
        original_get_block = onchain_engine.get_block
        original_get_tx_receipt = onchain_engine.get_tx_receipt
        tx_hashes = ["0x" + "a" * 64, "0x" + "b" * 64]
        calls: list[str] = []
        try:
            onchain_engine.get_block = lambda chain, block_number: {
                "number": hex(block_number),
                "timestamp": hex(1_778_100_000),
                "hash": "0x" + "c" * 64,
                "transactions": [
                    {
                        "hash": tx_hashes[0],
                        "from": "0x" + "1" * 40,
                        "to": "0x" + "2" * 40,
                        "value": "0x0",
                    },
                    {
                        "hash": tx_hashes[1],
                        "from": "0x" + "3" * 40,
                        "to": "0x" + "4" * 40,
                        "value": "0x0",
                    },
                ],
            }

            def fake_receipt(chain: str, tx_hash: str) -> dict:
                calls.append(tx_hash)
                return {"logs": []}

            onchain_engine.get_tx_receipt = fake_receipt

            result = onchain_engine.ingest_block("eth", 321, max_receipts_per_block=1)

            self.assertTrue(result["ok"])
            self.assertEqual(result["tx_count"], 2)
            self.assertEqual(result["tx_ingested"], 1)
            self.assertEqual(result["receipts_checked"], 1)
            self.assertTrue(result["partial"])
            self.assertEqual(result["stop_reason"], "receipt_budget_reached")
            self.assertEqual(calls, [tx_hashes[0]])
        finally:
            onchain_engine.get_block = original_get_block
            onchain_engine.get_tx_receipt = original_get_tx_receipt

    def test_swap_token_identity_backfill_is_bounded_and_audited(self) -> None:
        original_resolve_pair_tokens = onchain_engine._resolve_pair_tokens
        tx_hash = "0x" + "d" * 64
        pool = "0x" + "e" * 40
        token0 = "0x" + "5" * 40
