    def test_bounded_exact_swap_transfer_collection_confirm_writes_only_data_tables(self) -> None:
        original_run_exact_swap_ingestion_plan_once = onchain_engine.run_exact_swap_ingestion_plan_once
        labels_before = label_ledger.get_label_ledger_summary()["labels"]

        def fake_run_exact_swap_ingestion_plan_once(
            max_chains: int,
            count_per_chain: int,
            confirmations: int,
            max_receipts_per_block: int | None = None,
            max_seconds_per_block: float | None = None,
        ) -> dict:
            self.assertIsNotNone(max_receipts_per_block)
            self.assertIsNotNone(max_seconds_per_block)
            conn = sqlite3.connect(str(self.onchain_db))
            try:
                conn.execute(
                    """
                    INSERT INTO swaps (
                        tx_hash, chain, block_number, timestamp, wallet, dex,
                        token_in, token_out, amount_in, amount_out, amount_usd, pool,
                        token_identity_quality, pair_rpc_source, router_addr, venue_source, venue_confidence
                    ) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)
                    """,
                    (
                        "0x" + "9" * 64,
                        "bsc",
                        456,
                        1_778_200_000,
                        "0x" + "1" * 40,
                        "PancakeSwap V2",
                        "0x" + "2" * 40,
                        "0x" + "3" * 40,
                        1.0,
                        2.0,
                        0.0,
                        "0x" + "4" * 40,
                        "exact_pair_log_direction",
                        "test_rpc",
                        "0x" + "5" * 40,
                        "known_router_address",
                        0.9,
                    ),
                )
                conn.execute(
                    """
                    INSERT INTO token_transfers (
                        tx_hash, log_index, chain, block_number, timestamp,
                        token, from_addr, to_addr, value_raw, source
                    ) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?)
                    """,
                    (
                        "0x" + "8" * 64,
                        1,
                        "bsc",
                        456,
                        1_778_200_000,
                        "0x" + "2" * 40,
                        "0x" + "6" * 40,
                        "0x" + "7" * 40,
                        "1000000000000000000",
                        "test_transfer_log",
                    ),
                )
                conn.commit()
            finally:
                conn.close()
            return {
                "ok": True,
                "job_id": 123,
                "result": {
                    "chains_attempted": max_chains,
                    "totals": {
                        "exact_swap_token_rows_delta": 1,
                        "total_swaps_delta": 1,
                        "distinct_swap_tokens_delta": 1,
                    },
                },
            }

        try:
            onchain_engine.run_exact_swap_ingestion_plan_once = fake_run_exact_swap_ingestion_plan_once
            result = onchain_engine.run_bounded_exact_swap_transfer_collection(
                max_chains=1,
                count_per_chain=1,
                confirmations=12,
                dry_run=False,
                confirm=onchain_engine.BOUNDED_EXACT_SWAP_TRANSFER_COLLECTION_CONFIRM,
            )
        finally:
            onchain_engine.run_exact_swap_ingestion_plan_once = original_run_exact_swap_ingestion_plan_once

        self.assertTrue(result["ok"])
        self.assertEqual(result["collection_status"], "completed")
        self.assertEqual(result["changed_tables"]["swaps"], 1)
        self.assertEqual(result["changed_tables"]["token_transfers"], 1)
        self.assertEqual(result["disallowed_table_deltas"], {})
        self.assertFalse(result["labels_changed"])
        self.assertFalse(result["would_create_cex_label"])
        self.assertFalse(result["would_execute_trade"])
        self.assertFalse(result["amount_usd_decision_enabled"])
        self.assertEqual(label_ledger.get_label_ledger_summary()["labels"], labels_before)

