    def test_token_metadata_enrichment_confirm_writes_only_metadata(self) -> None:
        original_rpc_evm_chain = onchain_engine._rpc_evm_chain
        token = "0x" + "b" * 40

        def abi_string(value: str) -> str:
            raw = value.encode().hex()
            padded_len = ((len(raw) + 63) // 64) * 64
            return "0x" + f"{32:064x}" + f"{len(value):064x}" + raw.ljust(padded_len, "0")

        conn = sqlite3.connect(str(self.onchain_db))
        try:
            conn.execute(
                """
                INSERT INTO swaps (
                    tx_hash, chain, block_number, timestamp, wallet, dex,
                    token_in, token_out, amount_in, amount_out, amount_usd, pool,
                    token_identity_quality, pair_rpc_source, router_addr, venue_source, venue_confidence
                ) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)
                """,
                (
                    "0x" + "4" * 64,
                    "eth",
                    123,
                    1_778_100_000,
                    "0x" + "5" * 40,
                    "Unknown DEX",
                    token,
                    "0xc02aaa39b223fe8d0a0e5c4f27ead9083c756cc2",
                    1.0,
                    2.0,
                    0.0,
                    "0x" + "7" * 40,
                    "exact_pair_log_direction",
                    "test_rpc",
                    "0x" + "8" * 40,
                    "unknown",
                    0.0,
                ),
            )
            conn.commit()
        finally:
            conn.close()

        def fake_rpc_evm_chain(chain: str, method: str, params: list) -> tuple[str, str]:
            selector = params[0]["data"]
            if selector == "0x95d89b41":
                return abi_string("TST"), "test_rpc"
            if selector == "0x06fdde03":
                return abi_string("Test Token"), "test_rpc"
            if selector == "0x313ce567":
                return "0x" + f"{18:064x}", "test_rpc"
            return "0x", "test_rpc"

        labels_before = label_ledger.get_label_ledger_summary()["labels"]
        try:
            onchain_engine._rpc_evm_chain = fake_rpc_evm_chain
            result = onchain_engine.enrich_token_metadata_from_local_observations(
                limit=1,
                dry_run=False,
                confirm=onchain_engine.TOKEN_METADATA_ENRICHMENT_CONFIRM,
                max_seconds=30,
            )
        finally:
            onchain_engine._rpc_evm_chain = original_rpc_evm_chain

        self.assertTrue(result["ok"])
        self.assertEqual(result["enrichment_status"], "completed")
        self.assertEqual(result["changed_tables"]["token_metadata"], 1)
        self.assertEqual(result["changed_tables"]["data_jobs"], 1)
        self.assertEqual(result["disallowed_table_deltas"], {})
        self.assertFalse(result["labels_changed"])
        self.assertFalse(result["would_create_cex_label"])
        self.assertFalse(result["would_execute_trade"])
        self.assertEqual(label_ledger.get_label_ledger_summary()["labels"], labels_before)

        audit = onchain_engine.get_token_manipulation_data_usability_audit(limit=10, dry_run=True)
        enriched = next(row for row in audit["token_findings"] if row["token_address"] == token)
        self.assertEqual(enriched["token_symbol"], "TST")
        self.assertNotIn("token_symbol_missing", enriched["blockers"])

