        self.assertEqual(audit["source_attribution"]["with_rpc_source"], 2)
        self.assertEqual(audit["by_rpc_source"][0]["traceable_rows"], 0)
        self.assertEqual(audit["by_rpc_source"][0]["recommended_action"], "backfill_source_attribution")
