        self.assertEqual(audit["by_entity_chain"][0]["chain"], "eth")
        self.assertEqual(audit["by_entity_chain"][0]["recommended_action"], "refresh_low_quality_or_review_sources")
        self.assertEqual(audit["weakest_wallets"][0]["address"], low_quality_address)
        self.assertFalse(audit["weakest_wallets"][0]["traceable"])
        self.assertEqual(audit["weakest_wallets"][0]["source_attribution_quality"], "missing_source_attribution")
        self.assertIn("read-only", audit["source_policy"])

