    def test_rpc_label_source_gap_report_is_read_only_and_actionable(self) -> None:
        unlabelled = "0x00000000000000000000000000000000000000bb"
        orphan_label = "0x00000000000000000000000000000000000000cc"
        conn = sqlite3.connect(str(self.onchain_db))
        try:
            for address, label, entity, confidence in (
                (unlabelled, None, None, "observed"),
                (orphan_label, "Binance: Hot Wallet", "Binance", "high"),
            ):
                conn.execute(
                """
                INSERT INTO wallet_chain_state (
                    chain, address, native_balance, tx_count, token_balances_json,
                    rpc_source, label, entity, confidence, address_kind, is_contract,
                    native_value_usd, activity_tier, risk_flags_json, data_quality_score,
                    label_sources_json, source_attribution_json, observed_at
                ) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)
                """,
                (
                    "eth",
                    address,
                    0.0,
                    1,
                    "[]",
                    "test_rpc",
                    label,
                    entity,
                    confidence,
                    "wallet",
                    0,
                    0.0,
                    "fresh",
                    "[]",
                    50,
                    "[]",
                    '{"rpc_source":"test_rpc"}',
                    3,
                ),
            )
            conn.commit()
        finally:
            conn.close()

        before = onchain_engine.get_rpc_wallet_quality_audit(limit=10)
        report = onchain_engine.get_rpc_label_source_gap_report(limit=10)
        after = onchain_engine.get_rpc_wallet_quality_audit(limit=10)

        self.assertEqual(before, after)
        self.assertGreaterEqual(report["summary"]["total_missing_label_sources"], 2)
        self.assertGreaterEqual(report["summary"]["stage_for_public_corroboration"], 1)
        self.assertGreaterEqual(report["summary"]["skip_unlabelled_observation"], 1)
        actions = {row["address"]: row["candidate_action"] for row in report["rows"]}
        self.assertEqual(actions["0x0000000000000000000000000000000000000001"], "refresh_ledger_sources")
        self.assertEqual(actions[orphan_label], "stage_for_public_corroboration")
        self.assertEqual(actions[unlabelled], "skip_unlabelled_observation")
        self.assertIn("read-only", report["source_policy"])

