    def test_rpc_label_source_gap_corroboration_persists_evidence_only(self) -> None:
        orphan_label = "0x00000000000000000000000000000000000000cc"
        conn = sqlite3.connect(str(self.onchain_db))
        try:
            conn.execute(
                """
                INSERT INTO wallet_chain_state (
                    chain, address, native_balance, tx_count, token_balances_json,
                    rpc_source, label, entity, confidence, address_kind, is_contract,
                    native_value_usd, activity_tier, risk_flags_json, data_quality_score,
                    label_sources_json, source_attribution_json, observed_at
                ) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)
                """,
                (
                    "eth",
                    orphan_label,
                    0.0,
                    1,
                    "[]",
                    "test_rpc",
                    "Binance: Hot Wallet",
                    "Binance",
                    "high",
                    "wallet",
                    0,
                    0.0,
                    "fresh",
                    "[]",
                    50,
                    "[]",
                    '{"rpc_source":"test_rpc"}',
                    3,
                ),
            )
            conn.commit()
        finally:
            conn.close()

        onchain_engine.stage_rpc_label_source_gap_candidates(limit=10, dry_run=False)
        original_corroborate = label_ledger._corroborate_candidate
        labels_before = label_ledger.get_label_ledger_summary()["labels"]

        def fake_corroborate(candidate, timeout=12):
            return {
                **candidate,
                "corroboration": {
                    "status": "needs_more_evidence",
                    "score": 42,
                    "evidence": [
                        {
                            "source": "blockscout_address",
                            "candidate_entity": candidate["entity"],
                            "observed_address": candidate["address"],
                        }
                    ],
                    "blockers": ["entity_not_confirmed_by_public_source"],
                },
            }

        try:
            label_ledger._corroborate_candidate = fake_corroborate
            dry = onchain_engine.corroborate_rpc_label_source_gap_candidates(limit=10, dry_run=True, timeout=2)
            external_dry = onchain_engine.corroborate_rpc_label_source_gap_candidates(
                limit=10,
                dry_run=True,
                timeout=2,
                allow_external=True,
            )
            blocked_real = onchain_engine.corroborate_rpc_label_source_gap_candidates(
                limit=10,
                dry_run=False,
                timeout=2,
                allow_external=True,
            )
            real = onchain_engine.corroborate_rpc_label_source_gap_candidates(
                limit=10,
                dry_run=False,
                timeout=2,
                allow_external=True,
                confirm="CORROBORATE_LABEL_SOURCE_GAP_CANDIDATES",
            )
        finally:
            label_ledger._corroborate_candidate = original_corroborate

        conn = sqlite3.connect(str(self.label_db))
        try:
            evidence_rows = conn.execute(
                """
                SELECT COUNT(*)
                FROM label_candidate_evidence e
                JOIN label_candidates c ON c.id = e.candidate_id
                WHERE c.source = 'rpc_label_source_gap'
                """
            ).fetchone()[0]
        finally:
            conn.close()
        jobs = onchain_engine.get_data_jobs(limit=5, job_type="rpc_label_source_gap_candidate_corroboration")

        self.assertEqual(dry["result"]["corroboration_status"], "external_disabled")
        self.assertEqual(dry["result"]["evidence_bundles_written"], 0)
        self.assertGreaterEqual(external_dry["result"]["candidates_selected"], 1)
        self.assertEqual(external_dry["result"]["evidence_bundles_written"], 0)
        self.assertFalse(blocked_real["ok"])
        self.assertIn("confirm_CORROBORATE_LABEL_SOURCE_GAP_CANDIDATES_required", blocked_real["result"]["blockers"])
        self.assertGreaterEqual(real["result"]["candidates_selected"], 1)
        self.assertGreaterEqual(real["result"]["evidence_bundles_written"], 1)
        self.assertGreaterEqual(evidence_rows, 1)
        self.assertFalse(real["result"]["trusted_labels_changed"])
        self.assertEqual(label_ledger.get_label_ledger_summary()["labels"], labels_before)
        self.assertEqual(jobs["rows"][0]["result"]["candidate_source"], "rpc_label_source_gap")
        self.assertIn("no candidates are promoted", real["result"]["source_policy"])

