    def test_label_source_gap_local_observation_collection_is_dry_run_first(self) -> None:
        orphan_label = "0x00000000000000000000000000000000000000cc"
        conn = sqlite3.connect(str(self.onchain_db))
        try:
            conn.execute(
                """
                INSERT INTO wallet_chain_state (
                    chain, address, native_balance, tx_count, token_balances_json,
                    rpc_source, label, entity, confidence, address_kind, is_contract,
                    native_value_usd, activity_tier, risk_flags_json, data_quality_score,
                    label_sources_json, source_attribution_json, observed_at
                ) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)
                """,
                (
                    "eth",
                    orphan_label,
                    0.0,
                    1,
                    "[]",
                    "test_rpc",
                    "Binance: Hot Wallet",
                    "Binance",
                    "high",
                    "wallet",
                    0,
                    0.0,
                    "fresh",
                    "[]",
                    50,
                    "[]",
                    '{"rpc_source":"test_rpc"}',
                    3,
                ),
            )
            conn.commit()
        finally:
            conn.close()

        onchain_engine.stage_rpc_label_source_gap_candidates(limit=10, dry_run=False)
        onchain_engine.backfill_rpc_label_source_gap_candidate_urls(limit=10, dry_run=False)

        def counts() -> dict[str, int]:
            onchain_conn = sqlite3.connect(str(self.onchain_db))
            label_conn = sqlite3.connect(str(self.label_db))
            try:
                return {
                    "wallet_chain_state": onchain_conn.execute("SELECT COUNT(*) FROM wallet_chain_state").fetchone()[0],
                    "data_jobs": onchain_conn.execute("SELECT COUNT(*) FROM data_jobs").fetchone()[0],
                    "labels": label_conn.execute("SELECT COUNT(*) FROM labels").fetchone()[0],
                    "label_candidates": label_conn.execute("SELECT COUNT(*) FROM label_candidates").fetchone()[0],
                    "label_candidate_evidence": label_conn.execute("SELECT COUNT(*) FROM label_candidate_evidence").fetchone()[0],
                }
            finally:
                onchain_conn.close()
                label_conn.close()

        before = counts()
        default_dry = onchain_engine.collect_label_source_gap_local_observations(limit=10, dry_run=True)
        rpc_dry = onchain_engine.collect_label_source_gap_local_observations(
            limit=10,
            dry_run=True,
            allow_rpc=True,
        )
        blocked_real = onchain_engine.collect_label_source_gap_local_observations(
            limit=10,
            dry_run=False,
            allow_rpc=True,
        )
        after = counts()

        self.assertEqual(before, after)
        self.assertEqual(default_dry["collection_status"], "blocked")
        self.assertIn("allow_rpc_true_required", default_dry["blockers"])
        self.assertEqual(rpc_dry["collection_status"], "ready_but_disabled")
        self.assertGreaterEqual(rpc_dry["wallet_count"], 1)
        self.assertTrue(rpc_dry["would_collect_snapshots"])
        self.assertTrue(rpc_dry["would_call_rpc"])
        self.assertTrue(rpc_dry["would_refresh_wallet_state"])
        self.assertFalse(rpc_dry["would_write"])
        self.assertEqual(rpc_dry["writes_performed"], 0)
        self.assertFalse(blocked_real["ok"])
        self.assertIn("confirm_COLLECT_LABEL_SOURCE_GAP_LOCAL_OBSERVATIONS_required", blocked_real["blockers"])
        self.assertFalse(blocked_real["would_collect_snapshots"])
        self.assertFalse(blocked_real["would_write"])

