        self.assertTrue(external_wrapper["external_access_enabled"])
        self.assertTrue(external_wrapper["would_call_external"])
        self.assertFalse(external_wrapper["would_persist_evidence"])
        self.assertFalse(external_wrapper["would_apply_label_source"])
        self.assertFalse(external_wrapper["would_create_cex_label"])
        self.assertFalse(external_wrapper["would_write"])
        self.assertEqual(external_wrapper["writes_performed"], 0)

