    def test_source_proof_grading_checkpoint_grades_oklink_without_writes(self) -> None:
        def _probe_row(candidate_id: int, address: str, proof: bool) -> dict[str, object]:
            entity_terms = ["binance"] if proof else []
            return {
                "label_candidate_id": candidate_id,
                "wallet_address": address,
                "proposed_label": "Binance: hot_wallet",
                "proposed_entity": "Binance",
                "source_name": "oklink_address_page",
                "source_url": f"https://www.oklink.com/ethereum/address/{address}",
                "final_url": f"https://www.oklink.com/ethereum/address/{address}",
                "source_tier": "tier_2",
                "evidence_type": "non_etherscan_public_address_source",
                "content_digest": f"digest-{candidate_id}",
                "text_sample": f"{address} Binance" if proof else address,
                "fetch_status": "fetched_preview_only",
                "proof_status": (
                    "address_and_entity_terms_observed_preview_only"
                    if proof
                    else "address_observed_entity_confirmation_missing"
                ),
                "proof_candidate_found": proof,
                "address_observed": True,
                "entity_terms_observed": entity_terms,
                "label_terms_observed": entity_terms,
                "source_replacement_preview": {
                    "label_candidate_id": candidate_id,
                    "replacement_source_url": f"https://www.oklink.com/ethereum/address/{address}",
                    "source_tier": "tier_2",
                    "evidence_type": "non_etherscan_public_address_source",
                    "evidence_preview_digest": f"digest-{candidate_id}",
                } if proof else None,
                "blockers": [] if proof else ["entity_or_label_terms_missing"],
            }

        addresses = {
            5039: "0x3f5ce5fbfe3e9af3971dd833d26ba9b5c936f0be",
            5040: "0xd93d01ce3156c64c6204fb11c712b601f33dcd37",
            5041: "0x3f5ce5fbfe3e9af3971dd833d26ba9b5c936f0be",
            5042: "0xd93d01ce3156c64c6204fb11c712b601f33dcd37",
            5043: "0x28c6c06298d514db089934071355e5743bf21d60",
        }
        fake_probe = {
            "run_status": "completed_preview_only",
            "selected_url_count": 5,
            "proof_candidate_count": 3,
            "db_unchanged": True,
            "rows": [
                _probe_row(5039, addresses[5039], True),
                _probe_row(5040, addresses[5040], False),
                _probe_row(5041, addresses[5041], True),
                _probe_row(5042, addresses[5042], False),
                _probe_row(5043, addresses[5043], True),
            ],
            "blockers": [],
        }
        fake_intake = {
            "intake_status": "ready_but_disabled",
            "summary": {"eligible": 3, "blocked": 0},
            "rows": [
                {
                    "label_candidate_id": candidate_id,
                    "eligible": True,
                    "evidence_preview_digest": f"digest-{candidate_id}",
                    "source_replacement_dedupe_key": f"dedupe-{candidate_id}",
                }
                for candidate_id in (5039, 5041, 5043)
            ],
            "blockers": [],
        }
        with (
            patch("services.onchain_engine.run_label_source_gap_source_url_probe_dry_run", return_value=fake_probe),
            patch("services.onchain_engine.get_label_source_gap_source_replacement_intake_preview", return_value=fake_intake),
        ):
            result = onchain_engine.get_label_source_gap_source_proof_grading_checkpoint(
                source_name="oklink_address_page",
                max_urls=5,
                dry_run=True,
                allow_external=True,
                timeout=4,
            )

        self.assertEqual(result["checkpoint_status"], "ready_read_only")
        self.assertEqual(result["summary"]["candidate_corroborated_not_applied"], 3)
        self.assertEqual(result["summary"]["blocked"], 2)
        self.assertEqual(result["summary"]["entity_confirmation_missing"], 2)
        by_id = {row["label_candidate_id"]: row for row in result["rows"]}
        self.assertEqual(by_id[5039]["proof_grade"], "candidate_corroborated_not_applied")
        self.assertEqual(by_id[5041]["proof_grade"], "candidate_corroborated_not_applied")
        self.assertEqual(by_id[5043]["proof_grade"], "candidate_corroborated_not_applied")
        self.assertEqual(by_id[5040]["proof_grade"], "blocked")
        self.assertEqual(by_id[5042]["proof_grade"], "blocked")
        self.assertFalse(result["would_persist_evidence"])
        self.assertFalse(result["would_apply_label_source"])
        self.assertFalse(result["would_create_cex_label"])
        self.assertFalse(result["would_write"])
        self.assertEqual(result["writes_performed"], 0)

