        self.assertEqual(bad_lead["local_evidence"]["amount_usd_quarantined_rows"], 1)
        self.assertTrue(radar["summary"]["amount_usd_quarantine_enabled"])
        self.assertFalse(radar["would_write"])
        self.assertEqual(radar["writes_performed"], 0)

        poisoned_scan = onchain_engine.get_adaptive_accumulation_breakout_scan(token=bad_token, limit=5)
        clean_scan = onchain_engine.get_adaptive_accumulation_breakout_scan(token=good_token, limit=5)
        self.assertEqual(poisoned_scan["summary"]["raw_swap_rows"], 0)
        self.assertEqual(clean_scan["summary"]["raw_swap_rows"], 1)
        self.assertTrue(poisoned_scan["summary"]["amount_usd_quarantine_enabled"])
        self.assertTrue(clean_scan["summary"]["amount_usd_quarantine_enabled"])

