    def test_dex_trades_raw_log_provenance_drilldown_is_read_only(self) -> None:
        conn = sqlite3.connect(str(self.onchain_db))
        token = "0x" + "8" * 40
        usdt = "0x55d398326f99059ff775485246999027b3197955"
        pool = "0x" + "3" * 40
        wallet = "0x" + "2" * 40
        clean_hash = "0x" + "6" * 64
        no_context_hash = "0x" + "7" * 64
        try:
            for token_address, symbol, name, decimals in (
                (token, "GOOD", "Good Token", 18),
                (usdt, "USDT", "Tether USD", 18),
            ):
                conn.execute(
                    """
                    INSERT INTO token_metadata (
                        chain, token_address, symbol, name, decimals, rpc_source, observed_at, status
                    ) VALUES (?, ?, ?, ?, ?, ?, ?, ?)
                    """,
                    ("bsc", token_address, symbol, name, decimals, "test_rpc", 1_778_200_000, "resolved"),
                )
            for tx_hash, block_number in ((clean_hash, 51), (no_context_hash, 52)):
                conn.execute(
                    """
                    INSERT INTO swaps (
                        tx_hash, chain, block_number, timestamp, wallet, dex,
                        token_in, token_out, amount_in, amount_out, amount_usd, pool,
                        token_identity_quality, pair_rpc_source, router_addr, venue_source, venue_confidence
                    ) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)
                    """,
                    (
                        tx_hash,
                        "bsc",
                        block_number,
                        1_778_200_000 + block_number,
                        wallet,
                        "PancakeSwap V2",
                        token,
                        usdt,
                        10.0,
                        25.0,
                        25.0,
                        pool,
                        "exact_pair_log_direction",
                        "test_rpc",
                        "0x" + "4" * 40,
                        "source_backed_dex_venue_mapping",
                        0.95,
                    ),
                )
            conn.execute(
                """
                INSERT INTO token_transfers (
                    tx_hash, log_index, chain, block_number, timestamp, token, from_addr, to_addr, value_raw, source
                ) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?)
                """,
                (clean_hash, 11, "bsc", 51, 1_778_200_051, token, wallet, pool, "10000000000000000000", "test_receipt"),
            )
            conn.execute(
                """
                INSERT INTO token_transfers (
                    tx_hash, log_index, chain, block_number, timestamp, token, from_addr, to_addr, value_raw, source
                ) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?)
                """,
                (clean_hash, 12, "bsc", 51, 1_778_200_051, usdt, pool, wallet, "25000000000000000000", "test_receipt"),
            )
            conn.commit()
        finally:
            conn.close()

        drilldown = onchain_engine.get_dex_trades_raw_log_provenance_drilldown(limit=10, dry_run=True)
        rows_by_hash = {row["tx_hash"]: row for row in drilldown["rows"]}
        self.assertEqual(drilldown["drilldown_status"], "ready_read_only")
        self.assertIn(clean_hash, rows_by_hash)
        self.assertIn(no_context_hash, rows_by_hash)
        self.assertEqual(
            rows_by_hash[clean_hash]["raw_log_provenance_status"],
            "local_transfer_context_present_swap_log_index_missing",
        )
        self.assertEqual(rows_by_hash[clean_hash]["local_transfer_logs_found"], 2)
        self.assertEqual(rows_by_hash[clean_hash]["token_in_transfer_logs"], 1)
        self.assertEqual(rows_by_hash[clean_hash]["token_out_transfer_logs"], 1)
        self.assertGreaterEqual(rows_by_hash[clean_hash]["pool_transfer_logs"], 1)
        self.assertFalse(rows_by_hash[clean_hash]["would_call_rpc"])
        self.assertFalse(rows_by_hash[clean_hash]["would_write"])
        self.assertEqual(rows_by_hash[no_context_hash]["raw_log_provenance_status"], "needs_bounded_receipt_replay")
        self.assertIn("no_local_transfer_logs_for_tx", rows_by_hash[no_context_hash]["blockers"])
        self.assertFalse(drilldown["would_call_rpc"])
        self.assertFalse(drilldown["would_collect_raw_logs"])
        self.assertFalse(drilldown["would_create_cex_label"])
        self.assertFalse(drilldown["would_create_mapping"])
        self.assertFalse(drilldown["would_execute_trade"])
        self.assertFalse(drilldown["would_create_client_signal"])
        self.assertFalse(drilldown["would_write"])
        self.assertEqual(drilldown["writes_performed"], 0)

        blocked = onchain_engine.get_dex_trades_raw_log_provenance_drilldown(limit=10, dry_run=False)
        self.assertEqual(blocked["drilldown_status"], "blocked")
        self.assertIn("dry_run_required", blocked["blockers"])
        self.assertFalse(blocked["would_call_rpc"])
        self.assertFalse(blocked["would_write"])
        self.assertEqual(blocked["writes_performed"], 0)

