    def test_source_backed_curated_history_collection_plan_is_dry_run_first(self) -> None:
        token = "0x" + "b" * 40
        fake_ranking = {
            "ok": True,
            "summary": {"source_backed_token_groups": 1},
            "rows": [
                {
                    "rank": 1,
                    "chain": "bsc",
                    "token_symbol": "BBB",
                    "token_address": token,
                    "source_backed_rows": 2,
                    "unique_wallets": 1,
                    "research_readiness": "thin_clean_dataset_research_only",
                    "curated_trade_ids": [1, 2],
                }
            ],
        }
        fake_review = {
            "ok": True,
            "rows": [
                {
                    "dex_trade_curated_id": 1,
                    "chain": "bsc",
                    "block_number": 100,
                    "token_in": "0xbb4cdb9cbd36b01bd1cbaebf2de08d9173bc095c",
                    "token_out": token,
                    "swap_dex": "PancakeSwap V2",
                    "swap_venue_confidence": 0.95,
                    "shadow_scoring_readiness": "ready_for_shadow_scoring_preview",
                },
                {
                    "dex_trade_curated_id": 2,
                    "chain": "bsc",
                    "block_number": 105,
                    "token_in": token,
                    "token_out": "0xbb4cdb9cbd36b01bd1cbaebf2de08d9173bc095c",
                    "swap_dex": "PancakeSwap V2",
                    "swap_venue_confidence": 0.95,
                    "shadow_scoring_readiness": "ready_for_shadow_scoring_preview",
                },
            ],
        }
        labels_before = label_ledger.get_label_ledger_summary()["labels"]
        candidates_before = label_ledger.get_label_ledger_summary()["label_candidates"]
        jobs_before = onchain_engine.get_data_jobs(limit=100)

        with (
            patch("services.onchain_engine.get_dex_trades_curated_source_backed_token_ranking", return_value=fake_ranking),
            patch("services.onchain_engine.get_dex_trades_curated_review", return_value=fake_review),
        ):
            plan = onchain_engine.get_dex_trades_curated_source_backed_history_collection_plan(
                chain="bsc",
                token_symbol="BBB",
                limit=10,
                max_tokens=1,
                window_radius_blocks=1,
                max_blocks=4,
                dry_run=True,
            )
            dry = onchain_engine.run_dex_trades_curated_source_backed_history_collection(
                chain="bsc",
                token_symbol="BBB",
                limit=10,
                max_tokens=1,
                window_radius_blocks=1,
                max_blocks=4,
                dry_run=True,
            )

        self.assertTrue(plan["ok"])
        self.assertTrue(plan["dry_run"])
        self.assertEqual(plan["plan_status"], "ready_but_disabled")
        self.assertEqual(plan["summary"]["tokens_selected_for_history"], 1)
        self.assertEqual(plan["summary"]["collection_windows"], 2)
        self.assertEqual(plan["summary"]["target_blocks"], 4)
        self.assertTrue(plan["would_collect_data"])
        self.assertTrue(plan["would_call_rpc"])
        self.assertFalse(plan["would_write"])
        self.assertEqual(plan["writes_performed"], 0)

        self.assertEqual(dry["collection_status"], "ready_but_disabled")
        self.assertTrue(dry["would_collect_data"])
        self.assertTrue(dry["would_call_rpc"])
        self.assertFalse(dry["would_write"])
        self.assertEqual(dry["writes_performed"], 0)
        self.assertEqual(label_ledger.get_label_ledger_summary()["labels"], labels_before)
        self.assertEqual(label_ledger.get_label_ledger_summary()["label_candidates"], candidates_before)
        self.assertEqual(onchain_engine.get_data_jobs(limit=100), jobs_before)

    def test_dex_trades_curated_expansion_collection_plan_targets_missing_swaps_only(self) -> None:
        onchain_engine.create_dex_trade_raw_swap_provenance(
            dry_run=False,
            confirm="CREATE_DEX_TRADE_RAW_SWAP_PROVENANCE",
        )
        pool = "0x" + "7" * 40
        wbnb = "0xbb4cdb9cbd36b01bd1cbaebf2de08d9173bc095c"
        token1 = "0x" + "b" * 40
        curated_tx = "0x" + "4" * 64
        missing_tx = "0x" + "5" * 64
        missing_transfer_tx = "0x" + "6" * 64
        unknown_route_tx = "0x" + "8" * 64
        swap_data = (
            "0x"
            + f"{10 ** 18:064x}"
            + f"{0:064x}"
            + f"{0:064x}"
            + f"{25 * 10 ** 6:064x}"
        )
        conn = sqlite3.connect(str(self.onchain_db))
        try:
            conn.execute(
                """
                INSERT INTO pair_tokens (chain, pool, token0, token1, rpc_source, observed_at)
                VALUES (?, ?, ?, ?, ?, ?)
                """,
                ("bsc", pool, wbnb, token1, "test_pair_cache", 1),
            )
            conn.execute(
                """
                INSERT INTO token_metadata (
                    chain, token_address, symbol, name, decimals, rpc_source, observed_at, status
                ) VALUES (?, ?, ?, ?, ?, ?, ?, ?)
                """,
                ("bsc", token1, "BBB", "Token BBB", 6, "test", 1, "resolved"),
            )
            conn.execute(
                """
                INSERT INTO dex_trade_raw_swap_provenance (
                    chain, tx_hash, receipt_block_number, receipt_status, swap_log_index,
                    swap_log_address, swap_log_topics_json, swap_log_data, swap_event_topic,
                    matched_trade_key, candidate_trade_rows_json, candidate_trade_key_count,
                    matched_by, ambiguity_reason, match_status, match_confidence, parser_version,
                    source, created_at, source_policy
                ) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)
                """,
                (
                    "bsc",
                    curated_tx,
                    751,
                    "0x1",
                    101,
                    pool,
                    json.dumps([onchain_engine.SWAP_TOPIC, "0x" + "0" * 64, "0x" + "1" * 64]),
                    swap_data,
                    onchain_engine.SWAP_TOPIC,
                    "trade:bsc:curated",
                    '[{"trade_key":"trade:bsc:curated"}]',
                    1,
                    "pool_topic_token_pair",
                    None,
                    "matched",
                    0.96,
                    "swap_v2_topic_v1",
                    "test",
                    "2026-05-17T00:00:00Z",
                    "test_policy",
                ),
            )
            for tx_hash, timestamp, wallet, dex, router_addr, venue_source, venue_confidence, insert_transfer in (
                (
                    curated_tx,
                    10,
                    "0x" + "6" * 40,
                    "PancakeSwap V2",
                    "0x10ed43c718714eb63d5aa57b78b54704e256024e",
                    "known_router_address",
                    0.95,
                    True,
                ),
                (
                    missing_tx,
                    20,
                    "0x" + "7" * 40,
                    "PancakeSwap V2",
                    "0x10ed43c718714eb63d5aa57b78b54704e256024e",
                    "known_router_address",
                    0.95,
                    True,
                ),
                (
                    missing_transfer_tx,
                    25,
                    "0x" + "a" * 40,
                    "PancakeSwap V2",
                    "0x10ed43c718714eb63d5aa57b78b54704e256024e",
                    "known_router_address",
                    0.95,
                    False,
                ),
                (
                    unknown_route_tx,
                    30,
                    "0x" + "8" * 40,
                    "Unknown DEX",
                    "0x" + "9" * 40,
                    "swap_pool_event_unattributed",
                    0.35,
                    True,
                ),
            ):
                conn.execute(
                    """
                    INSERT INTO swaps (
                        tx_hash, chain, block_number, timestamp, wallet, dex, token_in, token_out,
                        amount_in, amount_out, amount_usd, pool, token_identity_quality, pair_rpc_source,
                        router_addr, venue_source, venue_confidence
                    ) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)
                    """,
                    (
                        tx_hash,
                        "bsc",
                        751,
                        timestamp,
                        wallet,
                        dex,
                        wbnb,
                        token1,
                        1.0,
                        25.0,
                        300.0,
                        pool,
                        "exact_pair_log_direction",
                        "test_pair_cache",
                        router_addr,
                        venue_source,
                        venue_confidence,
                    ),
                )
                if insert_transfer:
                    conn.execute(
                        """
                        INSERT INTO token_transfers (
                            tx_hash, log_index, chain, block_number, timestamp, token, from_addr, to_addr, value_raw, source
                        ) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?)
                        """,
                        (
                            tx_hash,
                            1,
                            "bsc",
                            751,
                            timestamp,
                            token1,
                            pool,
                            wallet,
                            "25000000",
                            "test_receipt",
                        ),
                    )
            conn.commit()
        finally:
            conn.close()

        onchain_engine.create_dex_trades_curated(
            limit=10,
            dry_run=False,
            confirm=onchain_engine.CREATE_DEX_TRADES_CURATED_CONFIRM,
        )
        onchain_engine.insert_dex_trades_curated_from_raw_provenance(
            limit=10,
            expected_insert_count=1,
            dry_run=False,
            confirm=onchain_engine.INSERT_DEX_TRADES_CURATED_CONFIRM,
        )

        plan = onchain_engine.get_dex_trades_curated_expansion_collection_plan(
            token_symbol="BBB",
            limit=10,
            max_tokens=1,
            dry_run=True,
        )
        self.assertEqual(plan["plan_status"], "ready_but_disabled")
        self.assertEqual(plan["summary"]["new_replay_targets"], 1)
        self.assertEqual(plan["summary"]["estimated_rpc_calls"], 1)
        self.assertEqual(plan["token_summaries"][0]["existing_curated_txs"], 1)
        self.assertEqual(plan["token_summaries"][0]["new_replay_targets_planned"], 1)
        self.assertEqual(plan["rows"][0]["tx_hash"], missing_tx)
        self.assertEqual(plan["rows"][0]["token_symbol"], "BBB")
        self.assertTrue(plan["rows"][0]["can_plan_replay"])
        blocked_unknown_route = next(row for row in plan["rows"] if row["tx_hash"] == unknown_route_tx)
        self.assertFalse(blocked_unknown_route["can_plan_replay"])
        self.assertIn("route_identity_repair_required_before_expansion_replay", blocked_unknown_route["blockers"])
        self.assertFalse(plan["would_call_rpc"])
        self.assertFalse(plan["would_write"])
        self.assertEqual(plan["writes_performed"], 0)

        source_backed_plan = onchain_engine.get_dex_trades_curated_source_backed_collection_plan(
            chain="bsc",
            limit=10,
            max_tokens=3,
            min_source_backed_rows=5,
            dry_run=True,
        )
        self.assertEqual(source_backed_plan["plan_status"], "ready_but_disabled")
        self.assertEqual(source_backed_plan["summary"]["tokens_selected_for_collection"], 1)
        self.assertEqual(source_backed_plan["summary"]["replay_ready_targets"], 1)
        self.assertEqual(source_backed_plan["summary"]["transfer_context_repair_targets"], 1)
        self.assertEqual(source_backed_plan["summary"]["route_repair_targets"], 1)
        self.assertEqual(source_backed_plan["token_plans"][0]["token_symbol"], "BBB")
        self.assertEqual(source_backed_plan["token_plans"][0]["next_data_action"], "confirmed_raw_provenance_replay_possible_after_dry_run")
        self.assertTrue(any(row["tx_hash"] == missing_tx and row["can_plan_replay"] for row in source_backed_plan["rows"]))
        self.assertFalse(source_backed_plan["would_call_rpc"])
        self.assertFalse(source_backed_plan["would_write"])
        self.assertEqual(source_backed_plan["writes_performed"], 0)

        transfer_context_plan = onchain_engine.get_dex_trades_curated_source_backed_transfer_context_plan(
            chain="bsc",
            limit=10,
            max_tokens=3,
            min_source_backed_rows=5,
            dry_run=True,
        )
        self.assertEqual(transfer_context_plan["plan_status"], "ready_but_disabled")
        self.assertEqual(transfer_context_plan["summary"]["transfer_context_targets"], 1)
        self.assertEqual(transfer_context_plan["summary"]["estimated_future_rpc_calls"], 1)
        self.assertEqual(transfer_context_plan["rows"][0]["tx_hash"], missing_transfer_tx)
        self.assertEqual(transfer_context_plan["rows"][0]["repair_target"], "token_transfers")
        self.assertIn("token_transfer_context_missing", transfer_context_plan["rows"][0]["blockers"])
        self.assertFalse(transfer_context_plan["would_call_rpc"])
        self.assertFalse(transfer_context_plan["would_insert_token_transfers"])
        self.assertFalse(transfer_context_plan["would_write"])
        self.assertEqual(transfer_context_plan["writes_performed"], 0)

        transfer_apply_dry_run = onchain_engine.collect_token_transfer_context_from_receipts(
            chain="bsc",
            limit=10,
            max_tokens=3,
            min_source_backed_rows=5,
            dry_run=True,
        )
        self.assertEqual(transfer_apply_dry_run["apply_status"], "ready_but_disabled")
        self.assertEqual(transfer_apply_dry_run["planned_target_count"], 1)
        self.assertEqual(transfer_apply_dry_run["planned_rpc_calls"], 1)
        self.assertEqual(transfer_apply_dry_run["planned_chains"], ["bsc"])
        self.assertTrue(transfer_apply_dry_run["would_call_rpc"])
        self.assertTrue(transfer_apply_dry_run["would_insert_token_transfers"])
        self.assertFalse(transfer_apply_dry_run["would_write"])
        self.assertEqual(transfer_apply_dry_run["writes_performed"], 0)

        blocked_transfer_apply = onchain_engine.collect_token_transfer_context_from_receipts(
            chain="bsc",
            limit=10,
            max_tokens=3,
            min_source_backed_rows=5,
            expected_target_count=1,
            expected_chain="bsc",
            expected_max_rpc_calls=1,
            expected_min_token_transfers=1,
            expected_max_token_transfers=5,
            expected_transfer_context_repair_dedupe_key=transfer_context_plan["rows"][0]["transfer_context_repair_dedupe_key"],
            dry_run=False,
            confirm=None,
        )
        self.assertEqual(blocked_transfer_apply["apply_status"], "blocked")
        self.assertIn(
            "confirm_COLLECT_TOKEN_TRANSFER_CONTEXT_FROM_RECEIPTS_required",
            blocked_transfer_apply["blockers"],
        )

        transfer_log = {
            "address": token1,
            "transactionHash": missing_transfer_tx,
            "blockNumber": hex(751),
            "logIndex": hex(44),
            "topics": [
                onchain_engine.TRANSFER_TOPIC,
                "0x" + pool[2:].rjust(64, "0"),
                "0x" + ("a" * 40).rjust(64, "0"),
            ],
            "data": "0x" + f"{25 * 10 ** 6:064x}",
        }
        original_get_tx_receipt = onchain_engine.get_tx_receipt
        try:
            onchain_engine.get_tx_receipt = lambda chain, tx_hash: {
                "blockNumber": hex(751),
                "status": "0x1",
                "logs": [transfer_log],
            }
            transfer_inserted = onchain_engine.collect_token_transfer_context_from_receipts(
                chain="bsc",
                limit=10,
                max_tokens=3,
                min_source_backed_rows=5,
                expected_target_count=1,
                expected_chain="bsc",
                expected_max_rpc_calls=1,
                expected_min_token_transfers=1,
                expected_max_token_transfers=5,
                expected_transfer_context_repair_dedupe_key=transfer_context_plan["rows"][0]["transfer_context_repair_dedupe_key"],
                dry_run=False,
                confirm=onchain_engine.COLLECT_TOKEN_TRANSFER_CONTEXT_FROM_RECEIPTS_CONFIRM,
            )
        finally:
            onchain_engine.get_tx_receipt = original_get_tx_receipt

        self.assertTrue(transfer_inserted["ok"])
        self.assertEqual(transfer_inserted["apply_status"], "inserted")
        self.assertEqual(transfer_inserted["receipts_requested"], 1)
        self.assertEqual(transfer_inserted["receipts_returned"], 1)
        self.assertEqual(transfer_inserted["token_transfers_found"], 1)
        self.assertEqual(transfer_inserted["token_transfers_inserted"], 1)
        self.assertEqual(transfer_inserted["writes_performed"], 1)
        self.assertFalse(transfer_inserted["would_insert_raw_provenance"])
        self.assertFalse(transfer_inserted["would_insert_curated_trade"])
        self.assertFalse(transfer_inserted["would_create_cex_label"])
        self.assertFalse(transfer_inserted["would_execute_trade"])
        self.assertFalse(transfer_inserted["would_create_client_signal"])

        duplicate_transfer_apply = onchain_engine.collect_token_transfer_context_from_receipts(
            chain="bsc",
            limit=10,
            max_tokens=3,
            min_source_backed_rows=5,
            expected_target_count=1,
            expected_chain="bsc",
            expected_max_rpc_calls=1,
            expected_min_token_transfers=1,
            expected_max_token_transfers=5,
            expected_transfer_context_repair_dedupe_key=transfer_context_plan["rows"][0]["transfer_context_repair_dedupe_key"],
            dry_run=False,
            confirm=onchain_engine.COLLECT_TOKEN_TRANSFER_CONTEXT_FROM_RECEIPTS_CONFIRM,
        )
        self.assertEqual(duplicate_transfer_apply["apply_status"], "blocked")
        self.assertEqual(duplicate_transfer_apply["writes_performed"], 0)

        blocked_transfer_context_plan = onchain_engine.get_dex_trades_curated_source_backed_transfer_context_plan(
            limit=10,
            dry_run=False,
        )
        self.assertEqual(blocked_transfer_context_plan["plan_status"], "blocked")
        self.assertIn("dry_run_required", blocked_transfer_context_plan["blockers"])
        self.assertFalse(blocked_transfer_context_plan["would_write"])
        self.assertEqual(blocked_transfer_context_plan["writes_performed"], 0)

        blocked = onchain_engine.get_dex_trades_curated_expansion_collection_plan(
            limit=10,
            dry_run=False,
        )
        self.assertEqual(blocked["plan_status"], "blocked")
        self.assertIn("dry_run_required", blocked["blockers"])
        self.assertFalse(blocked["would_write"])
        self.assertEqual(blocked["writes_performed"], 0)

        conn = sqlite3.connect(str(self.onchain_db))
        try:
            curated_count = conn.execute("SELECT COUNT(*) FROM dex_trades_curated").fetchone()[0]
            raw_count = conn.execute("SELECT COUNT(*) FROM dex_trade_raw_swap_provenance").fetchone()[0]
        finally:
            conn.close()
        self.assertEqual(curated_count, 1)
        self.assertEqual(raw_count, 1)

