    def test_refresh_rpc_wallet_state_audit_targets_is_bounded_and_logged(self) -> None:
        original_audit = onchain_engine.get_rpc_wallet_state_audit
        original_enrich = onchain_engine.enrich_labeled_wallets_rpc
        calls: list[dict] = []
        audits = [
            {
                "total_wallets": 10,
                "traceable_wallets": 0,
                "traceability_pct": 0.0,
                "missing_source_attribution": 10,
                "missing_label_sources": 10,
                "stale_rows": 2,
                "low_quality_rows": 1,
                "refresh_targets": [
                    {
                        "entity": "Binance",
                        "chain": "eth",
                        "wallets": 10,
                        "missing_source_attribution": 10,
                        "missing_label_sources": 10,
                        "stale_rows": 2,
                        "low_quality_rows": 1,
                    }
                ],
            },
            {
                "total_wallets": 10,
                "traceable_wallets": 3,
                "traceability_pct": 30.0,
                "missing_source_attribution": 7,
                "missing_label_sources": 7,
                "stale_rows": 1,
                "low_quality_rows": 0,
                "refresh_targets": [],
            },
        ]

        def fake_audit(**kwargs):
            calls.append({"audit": kwargs})
            return audits.pop(0)

        def fake_enrich(**kwargs):
            calls.append({"enrich": kwargs})
            return {
                "wallets_updated": 3,
                "seeds_loaded": 3,
                "chains_seen": {"eth": 3},
                "errors": [],
            }

        try:
            onchain_engine.get_rpc_wallet_state_audit = fake_audit
            onchain_engine.enrich_labeled_wallets_rpc = fake_enrich
            result = onchain_engine.refresh_rpc_wallet_state_audit_targets(
                limit_per_target=3,
                max_targets=1,
                include_tokens=False,
                min_confidence="medium",
                stale_after_hours=24,
                quality_below=50,
            )
        finally:
            onchain_engine.get_rpc_wallet_state_audit = original_audit
            onchain_engine.enrich_labeled_wallets_rpc = original_enrich

        jobs = onchain_engine.get_data_jobs(limit=1, job_type="rpc_wallet_state_audit_refresh")
        enrich_call = next(item["enrich"] for item in calls if "enrich" in item)

        self.assertEqual(result["targets_attempted"], 1)
        self.assertEqual(result["wallets_updated"], 3)
        self.assertEqual(result["before"]["traceable_wallets"], 0)
        self.assertEqual(result["after"]["traceable_wallets"], 3)
        self.assertEqual(enrich_call["limit"], 3)
        self.assertEqual(enrich_call["entity"], "Binance")
        self.assertEqual(enrich_call["chain"], "eth")
        self.assertTrue(enrich_call["refresh_missing_attribution"])
        self.assertFalse(enrich_call["missing_only"])
        self.assertEqual(jobs["rows"][0]["job_type"], "rpc_wallet_state_audit_refresh")
        self.assertEqual(jobs["rows"][0]["status"], "ok")

    def test_auto_enrich_once_defaults_to_chain_gap_routing(self) -> None:
        calls: list[tuple[str, dict]] = []
        original_chain_gaps = onchain_engine.enrich_priority_entity_chain_gaps_rpc
        original_entities = onchain_engine.enrich_priority_entities_rpc
        original_env = os.environ.get("CORE_AUTO_LABEL_BUILD_ENABLED")
        original_source_env = os.environ.get("CORE_AUTO_SOURCE_ACQUIRE_ENABLED")

        def fake_chain_gaps(**kwargs):
            calls.append(("chain_gaps", kwargs))
            return {"ok": True, "mode": "priority_entity_chain_rpc_enrichment"}

        def fake_entities(**kwargs):
            calls.append(("entities", kwargs))
            return {"ok": True, "mode": "priority_entity_rpc_enrichment"}

        try:
            os.environ["CORE_AUTO_LABEL_BUILD_ENABLED"] = "false"
            os.environ["CORE_AUTO_SOURCE_ACQUIRE_ENABLED"] = "false"
            onchain_engine.enrich_priority_entity_chain_gaps_rpc = fake_chain_gaps
            onchain_engine.enrich_priority_entities_rpc = fake_entities
            result = onchain_engine._run_auto_enrich_once(
                limit_per_entity=7,
                max_entities=3,
                min_confidence="medium",
                include_tokens=True,
                mode="chain_gaps",
            )
        finally:
            onchain_engine.enrich_priority_entity_chain_gaps_rpc = original_chain_gaps
            onchain_engine.enrich_priority_entities_rpc = original_entities
            if original_env is None:
                os.environ.pop("CORE_AUTO_LABEL_BUILD_ENABLED", None)
            else:
                os.environ["CORE_AUTO_LABEL_BUILD_ENABLED"] = original_env
            if original_source_env is None:
                os.environ.pop("CORE_AUTO_SOURCE_ACQUIRE_ENABLED", None)
            else:
                os.environ["CORE_AUTO_SOURCE_ACQUIRE_ENABLED"] = original_source_env

        self.assertEqual(result["mode"], "priority_entity_chain_rpc_enrichment")
        self.assertEqual(calls, [("chain_gaps", {
            "limit_per_pair": 7,
            "max_pairs": 3,
            "min_confidence": "medium",
            "include_tokens": True,
        })])

    def test_auto_enrich_acquires_sources_when_chain_gaps_idle(self) -> None:
        calls: list[tuple[str, dict]] = []
        original_chain_gaps = onchain_engine.enrich_priority_entity_chain_gaps_rpc
        original_acquire = onchain_engine.acquire_label_sources_job
        original_dedup = onchain_engine.consolidate_label_candidate_duplicates_job
        original_label_env = os.environ.get("CORE_AUTO_LABEL_BUILD_ENABLED")
        env_names = [
            "CORE_AUTO_SOURCE_ACQUIRE_ENABLED",
            "CORE_AUTO_SOURCE_ACQUIRE_LIMIT",
            "CORE_AUTO_SOURCE_MIN_TRUSTED_PER_ENTITY",
            "CORE_AUTO_SOURCE_TIMEOUT_MS",
            "CORE_AUTO_SOURCE_MAX_XHR",
            "CORE_AUTO_CORROBORATE_ENABLED",
        ]
        original_env = {name: os.environ.get(name) for name in env_names}

        def fake_chain_gaps(**kwargs):
            calls.append(("chain_gaps", kwargs))
            return {"ok": True, "mode": "priority_entity_chain_rpc_enrichment", "pairs_attempted": 0}

        def fake_acquire(**kwargs):
            calls.append(("acquire_sources", kwargs))
            return {"ok": True, "job_id": 42, "result": {"sources_attempted": 1}}

        def fake_dedup(**kwargs):
            calls.append(("dedup_candidates", kwargs))
            return {"ok": True, "job_id": 43, "result": {"rows_removed": 2}}

        try:
            os.environ["CORE_AUTO_LABEL_BUILD_ENABLED"] = "false"
            os.environ["CORE_AUTO_SOURCE_ACQUIRE_ENABLED"] = "true"
            os.environ["CORE_AUTO_SOURCE_ACQUIRE_LIMIT"] = "1"
            os.environ["CORE_AUTO_SOURCE_MIN_TRUSTED_PER_ENTITY"] = "100"
            os.environ["CORE_AUTO_SOURCE_TIMEOUT_MS"] = "5000"
            os.environ["CORE_AUTO_SOURCE_MAX_XHR"] = "10"
            os.environ["CORE_AUTO_CORROBORATE_ENABLED"] = "false"
            onchain_engine.enrich_priority_entity_chain_gaps_rpc = fake_chain_gaps
            onchain_engine.acquire_label_sources_job = fake_acquire
            onchain_engine.consolidate_label_candidate_duplicates_job = fake_dedup
            result = onchain_engine._run_auto_enrich_once(
                limit_per_entity=7,
                max_entities=3,
                min_confidence="medium",
                include_tokens=True,
                mode="chain_gaps",
            )
        finally:
            onchain_engine.enrich_priority_entity_chain_gaps_rpc = original_chain_gaps
            onchain_engine.acquire_label_sources_job = original_acquire
            onchain_engine.consolidate_label_candidate_duplicates_job = original_dedup
            if original_label_env is None:
                os.environ.pop("CORE_AUTO_LABEL_BUILD_ENABLED", None)
            else:
                os.environ["CORE_AUTO_LABEL_BUILD_ENABLED"] = original_label_env
            for name, value in original_env.items():
                if value is None:
                    os.environ.pop(name, None)
                else:
                    os.environ[name] = value

        self.assertIn("idle_source_acquisition", result)
        self.assertIn("idle_candidate_dedup", result)
        self.assertEqual(calls, [
            ("chain_gaps", {
                "limit_per_pair": 7,
                "max_pairs": 3,
                "min_confidence": "medium",
                "include_tokens": True,
            }),
            ("acquire_sources", {
                "limit": 1,
                "min_trusted_per_entity": 100,
                "timeout_ms": 5000,
                "max_xhr": 10,
            }),
            ("dedup_candidates", {
                "limit": 25,
                "dry_run": False,
            }),
        ])

