        queue = label_ledger.get_verified_label_candidate_review_queue(limit=10, entity="Binance")

        self.assertTrue(queue["ok"])
        self.assertEqual(queue["ready_for_admin_review"], 1)
        row = queue["lanes"]["ready_for_admin_review"][0]
