        plan = label_ledger.get_label_acquisition_plan(limit=10)
        binance_plan = next(item for item in plan["rows"] if item["entity"] == "Binance")
        self.assertGreaterEqual(binance_plan["strict_ready_candidates"], 1)
        self.assertEqual(binance_plan["recommended_action"], "dry_run_promote_strict_ready")
        self.assertEqual(label_ledger.get_label_ledger_summary()["labels"], labels_before)

