    def test_promotion_impact_preview_reports_insert_update_and_blocks_read_only(self) -> None:
        labels_before = label_ledger.get_label_ledger_summary()["labels"]
        now = label_ledger._utc_now()
        existing_address = "0x0000000000000000000000000000000000000001"
        new_address = "0x00000000000000000000000000000000000000fb"
        weak_address = "0x00000000000000000000000000000000000000fc"
        conn = sqlite3.connect(str(self.label_db))
        try:
            candidate_ids = []
            rows = [
                (existing_address, "impact-existing", "Binance: Existing Update", 88, []),
                (new_address, "impact-new", "Binance: New Insert", 88, []),
                (
                    weak_address,
                    "impact-weak",
                    "Binance: Weak Blocked",
                    45,
                    ["strict_requires_verified_or_external_source"],
                ),
            ]
            for address, source_key, label, score, blockers in rows:
                cur = conn.execute(
                    """
                    INSERT INTO label_candidates (
                        chain, address, proposed_label, proposed_entity, proposed_wallet_type,
                        confidence, status, source, source_key, source_url, evidence_json,
                        first_seen_at, last_seen_at, seen_count
                    ) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)
                    """,
                    (
                        "ethereum",
                        address,
                        label,
                        "Binance",
                        "hot wallet",
                        "medium",
                        "candidate",
                        "scrapling_transfer_side",
                        source_key,
                        "https://intel.arkm.com/explorer/entity/binance",
                        "[]",
                        now,
                        now,
                        20,
                    ),
                )
                candidate_id = int(cur.lastrowid)
                candidate_ids.append(candidate_id)
                conn.execute(
                    """
                    INSERT INTO label_candidate_evidence (
                        candidate_id, chain, address, source, source_key, status, score,
                        evidence_json, blockers_json, observed_at
                    ) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?)
                    """,
                    (
                        candidate_id,
                        "ethereum",
                        address,
                        "corroboration_bundle",
                        f"{source_key}-proof",
                        "verified_source_ready" if score >= 80 else "needs_more_evidence",
                        score,
                        json.dumps([
                            {"source": "blockscout_address", "name": "Binance"},
                            {"source": "explorer_html_title", "title": "Binance wallet"},
                        ]),
                        json.dumps(blockers),
                        now,
                    ),
                )
            conn.commit()
        finally:
            conn.close()

        preview = label_ledger.preview_label_candidate_promotion_impact(candidate_ids)

        self.assertTrue(preview["ok"])
        self.assertEqual(preview["would_insert"], 1)
        self.assertEqual(preview["would_update_existing"], 1)
        self.assertEqual(preview["blocked"], 1)
        operations = {row["id"]: row["operation"] for row in preview["rows"]}
        self.assertEqual(operations[candidate_ids[0]], "update_existing_label")
        self.assertEqual(operations[candidate_ids[1]], "insert_new_label")
        self.assertEqual(operations[candidate_ids[2]], "blocked")
        blocked_row = next(row for row in preview["rows"] if row["id"] == candidate_ids[2])
        self.assertIn("persisted_evidence_not_review_ready", blocked_row["promotion"]["blockers"])
        self.assertEqual(label_ledger.get_label_ledger_summary()["labels"], labels_before)

